--
-- Complète `dc_hotfixes.broadcast_text_locale` avec les chaînes françaises
-- présentes dans le BroadcastText.db2 du client mais absentes de notre
-- base. Extraites via `mapextractor -e 2 -l frFR` puis relues avec la
-- structure du core (DB2Metadata.h : types "sshhhbbii", tailles
-- {1,1,3,3,1,1,1,1,2}, identifiant en table d'index).
--
-- Apport réel mesuré : +907 entrées (88 288 -> 89 195), puis +2 dialogues
-- de créatures après relance du pont (voir pont_traductions_broadcast.sql).
--
-- LIMITE IMPORTANTE, constatée à cette occasion : le client ne stocke
-- localement que 3 869 entrées de BroadcastText pour des identifiants
-- allant jusqu'à 146 482. Blizzard livre tout le reste par son système de
-- hotfix, hors de notre portée. Les dialogues de l'ère Legion (identifiants
-- > 90 000, dont toute la campagne des chasseurs de démons) n'ont AUCUNE
-- ligne de traduction, dans aucune langue, ni chez nous ni dans le client.
-- Inutile de refaire cette extraction en espérant mieux.
--
-- Rejouable sans risque (INSERT IGNORE). À appliquer sur dc_hotfixes avec
--   mysql --default-character-set=utf8mb4 dc_hotfixes < ce_fichier.sql
