INSERT IGNORE INTO `broadcast_text_locale` (ID, locale, Text_lang, Text1_lang, VerifiedBuild) VALUES
(1,'frFR','Au secours, au secours ! On m’opprime !','',26972),
(3927,'frFR','Séquence d’autodestruction activée.','',26972),
(9426,'frFR','PAR LE FEU, SOYEZ PURIFIÉS !','',26972),
(15708,'frFR','','Venez… par ici.',26972),
(33996,'frFR','Perte de vie inévitable.','',26972),
(33997,'frFR','Je fais ce que je dois.','',26972),
(34001,'frFR','Votre temps est écoulé.','',26972),
(34012,'frFR','Peut-être est-ce cette imperfection, celle qui vous donne ce libre arbitre, qui vous permet de persévérer à l’encontre de toutes les probabilités cosmiques. Vous triomphez là où les parfaites créations des titans ont échoué.','',26972),
(44223,'frFR','','Vous étiez un homme du peuple, Liam. Plus qu’aucun sang bleu que j’ai connu. Ils paieront pour ça.',26972),
(50471,'frFR','Puisse la Lumière bénir les esprits de nos ancêtres, qui ont permis à mon fils de reposer en cette terre sacrée.','',26972),
(50472,'frFR','C’est ici qu’est sa place, parmi les patriotes et les héros de Gilnéas.','',26972),
(50473,'frFR','Nous reviendrons, Liam. Je te le promets.','',26972),
(50477,'frFR','Gilnéas n’oubliera jamais votre courage, Liam.','',26972),
(56129,'frFR','Pardonnez-moi cette tromperie, mais elle était nécessaire.','',26972),
(56130,'frFR','Durant des millénaires, nous n’avons jamais rencontré de vos semblables.','',26972),
(56131,'frFR','Il était impératif que je commence par prendre la mesure de votre cœur.','',26972),
(56154,'frFR','Accompagnez-moi, petit être. Je souhaite que vous voyiez quelque chose.','',26972),
(57715,'frFR','Cet endroit ne sera bientôt plus qu’un énorme cratère, haha.','',26972),
(57899,'frFR','Oh, fichez donc la paix à $gce pauvre gars:cette pauvre fille; ! Bande de vachards.','',26972),
(58170,'frFR','Cours, smoualeux ! Je douke des comme toi au petit-déjeuner !','',26972),
(58171,'frFR','Je m’appelle Anduin Wrynn, prince de Hurlevent. Je ne mourrai pas ici. Pas comme ça !','',26972),
(59411,'frFR','Pour la Pandarie !!!','',26972),
(60365,'frFR','','Ça marche ! La blessure se referme !',26972),
(60627,'frFR','','Nous avons tout risqué, mais nous avons réussi. Shen Zin Su se remettra de sa blessure.',26972),
(61462,'frFR','Notre histoire commence il y a longtemps, à l’époque du monstrueux empereur Tian.','',26972),
(61463,'frFR','L’empereur avait besoin de messagers et coursiers de confiance.','',26972),
(61464,'frFR','Il captura donc une petite créature trouvée dans une caverne, et la déforma avec les pouvoirs du val.','',26972),
(61465,'frFR','Sa création était un « grumelot ».','',26972),
(61470,'frFR','Parlons de la nature du pouvoir. Dans mes mains, je tiens une épée. Je vous le demande : qui détient le pouvoir ?','',26972),
(61471,'frFR','C’est moi, car je détiens l’épée !','',26972),
(61495,'frFR','Un grumelot peut porter cinq fois son propre poids. Il ne sue jamais. Il possède un odorat incroyable.','',26972),
(61496,'frFR','Et leur crâne est plus dur que le granit. Étrangement, ils semblent tous appartenir à une seule et même famille.','',26972),
(61497,'frFR','Les anciens héros pandarens libérèrent les grumelots de leur servitude.','',26972),
(61567,'frFR','Le seigneur de guerre yaungol se dévoile ! Venez, finissons-en !','',26972),
(61643,'frFR','Aujourd’hui, ils sont encore marchands, messagers, guides et sherpas pour les expéditions vers le sommet de Kun-Lai.','',26972),
(61647,'frFR','C’est un peuple très superstitieux, dont les membres prennent souvent le nom de leurs charmes préférés, leurs « porte-bonheur ».','',26972),
(61649,'frFR','Les grumelots se méfient de tout ce qu’ils ne peuvent pas sentir, aussi est-il préférable de rencontrer un nouveau grumelot avec une poche remplie de crottes.','',26972),
(61650,'frFR','C’est une race bien étrange.','',26972),
(61798,'frFR','Il y a des millénaires, les mogu détenaient tout le pouvoir. Ils dirigeaient ces contrées d’une main de fer. Mais comme leur empire grandissait, ils eurent besoin d’un moyen d’y maintenir l’ordre.','',26972),
(61799,'frFR','Ils utilisèrent les pouvoirs du val, et leurs propres pouvoirs de transformation de la chair, pour dénaturer une race de féroces lézards et en faire une arme vivante. Ils créèrent une armée. Une armée de sauroks. Des sauvages assoiffés de sang créés pour faire respecter la volonté de l’empereur.','',26972),
(61800,'frFR','Ah, mais il y a un problème, si l’on crée une arme vivante. Le voyez-vous ?','',26972),
(61801,'frFR','Qui, à présent, détient le pouvoir ?','',26972),
(61802,'frFR','Les cruels saurok, malgré leurs minuscules cerveaux de reptiles, saisirent sans tarder quelle était leur place. Ils tuèrent les ennemis des mogu.','',26972),
(61803,'frFR','Puis ils tuèrent les sujets des mogu.','',26972),
(61804,'frFR','Bientôt, ils commencèrent à tuer les mogu eux-mêmes.','',26972),
(61805,'frFR','L’empereur mogu ordonna alors l’extermination totale des sauroks. Cette tentative fut cependant vaine. Les sauroks infestent encore la Pandarie de nos jours.','',26972),
(61806,'frFR','Comme vous l’aurez compris : le pouvoir se prend facilement, mais ne doit pas être donné à la légère.','',26972),
(61828,'frFR','','Je me tiens prête, $p.',26972),
(61979,'frFR','','Venez, $p, je vais vous montrer.',26972),
(61980,'frFR','','Regardez dans la lunette.',26972),
(61981,'frFR','','Le sha de la haine se trouve dans le bâtiment mantide… je le soupçonne d’avoir investi un hôte puissant.',26972),
(61982,'frFR','','Pour rentrer, nous allons avoir besoin de cristaux réglés sur une fréquence spécifique, détenus par certains des chefs mantides.',26972),
(61983,'frFR','','J’ai localisé ces chefs ici…',26972),
(61984,'frFR','','ici…',26972),
(61985,'frFR','','… et là.',26972),
(61986,'frFR','','Tuez-les, prenez leurs cristaux. Ça devrait être assez simple.',26972),
(62624,'frFR','Bien le bonjour ! Vous avez goûté ma bière onirique, pas vrai ? Les visions qu’elle procure sont difficiles à déchiffrer. Mi-vérité, mi-illusion. Mais qui peut les distinguer ?','',26972),
(62776,'frFR','Mais que…?','',26972),
(62777,'frFR','Qu’est-ce que c’était que ce bruit ?','',26972),
(62778,'frFR','Ça venait du mur, mon général.','',26972),
(62779,'frFR','Je sais D’OÙ ça venait. Mais qu’est-ce que c’était ?','',26972),
(62781,'frFR','Non… Non…','',26972),
(62782,'frFR','Soldats ! Aux armes !','',26972),
(62783,'frFR','Vous trois ! $n ! Assistez le capitaine Bouclier de Chêne au front !','',26972),
(62784,'frFR','Labour de Jouvence ! Terre d’Encre ! Couvrez notre flanc gauche ! Je ne veux pas de mauvaise surprise !','',26972),
(62785,'frFR','Leven, le flanc droit ! Il va falloir vous débrouiller seul !','',26972),
(62786,'frFR','Tous les autres ! Si vous pouvez tenir une arme, protégez le village ! Ne les laissez pas franchir cette ligne ! Vous…','',26972),
(62789,'frFR','Nous n’avons aucune chance…','',26972),
(62790,'frFR','Repliez-vous ! REP…','',26972),
(62791,'frFR','Rrrraaaa !!!','',26972),
(62792,'frFR','Qui êtes-vous ?','',26972),
(62794,'frFR','Peu importe qui nous sommes. Nous sommes ici pour vous aider.','',26972),
(62795,'frFR','Hé ! Passez-moi une des ces fourches !','',26972),
(62796,'frFR','Vous étiez en train de vous rendre ? Pourquoi ? Parce que ces envahisseurs peuvent casser un rempart ?','',26972),
(62797,'frFR','Vous en avez un autre … fait de tous ceux qui appellent cet endroit leur PATRIE.','',26972),
(62798,'frFR','N’importe lequel d’entre nous donnerait sa vie pour protéger cette terre.','',26972),
(62799,'frFR','Elle nous appartient…','',26972),
(62800,'frFR','Elle appartient à nos ancêtres…','',26972),
(62801,'frFR','Elle appartient à nos enfants.','',26972),
(62802,'frFR','Et il est encore loin le jour où nous permettons que ça change.','',26972),
(63378,'frFR','Vous arrivez trop tard ! Le roi-tonnerre va venir vous prendre ces terres.','',26972),
(63387,'frFR','Comment nous ont-ils retrouvés ? Préparez vos armes, nous devons sortir de ce canyon !','',26972),
(63691,'frFR','Oh… on dirait que j’ai perdu mon épée.','',26972),
(63692,'frFR','Quand la Fracture a déchiré les continents d’Azeroth, nous autres Pandarens avons cru que le reste du monde avait été complètement détruit.','',26972),
(63693,'frFR','Mais au bout de plusieurs siècles, un jeune explorateur voulut savoir. Son nom était Liu Lang. Il partit à la découverte du monde… sur le dos d’une tortue !','',26972),
(63694,'frFR','Des statues et des chants sont dédiés à sa bravoure, mais si vous aviez été là sur la plage ce jour-là… eh bien, je pense qu’il avait l’air assez ridicule.','',26972),
(63695,'frFR','Oh, comme les Pandarens se sont moqués de lui. Mais Liu Lang était bien plus malin qu’on ne le pensait. Les tortues de mer reviennent toujours sur la plage qui les a vues naître. C’est ainsi que malgré les brumes qui enveloppaient notre patrie, il retrouvait toujours la Pandarie.','',26972),
(63696,'frFR','Toutes les quelques années, il revenait et parlait de mystérieuses cités des sables, de peuples nomades qui vivaient sur d’immenses plaines, d’un grand empire sous les glaces et d’un royaume magique tout recouvert d’or.','',26972),
(63697,'frFR','Chaque fois qu’il revenait, de plus en plus de Pandarens répondaient à son appel et le rejoignaient sur sa tortue, qui gagnait en taille. Tous étaient courageux : c’était des explorateurs. Des aventuriers.','',26972),
(63698,'frFR','Voilà ce que nous apprend Liu Lang, $gcher ami:chère amie;. On se moque toujours des explorateurs. On se moque toujours… jusqu’à ce qu’ils reviennent.','',26972),
(63699,'frFR','Les grandes actions ont souvent des débuts modestes. Pensez à un paisible étang. L’eau est comme le verre.','',26972),
(63700,'frFR','Jusqu’à ce que je lance une pierre. Une si petite chose, mais bientôt, c’est tout l’étang qui ondule !','',26972),
(63701,'frFR','Les jinyu ont aussi d’humbles origines. Autrefois très primitifs, ils ont eu la chance de se trouver près des bassins enchantés du val.','',26972),
(63702,'frFR','Les pouvoirs magiques de ces bassins ont développé leur intelligence et fait grandir leur corps, faisant d’eux l’une des grandes cultures de la Pandarie ancienne.','',26972),
(63703,'frFR','La sagesse des plus grands sages parmi les jinyu est remarquable. Ils parlent à leurs rivières comme vous et moi demandons conseil à nos aînés.','',26972),
(63704,'frFR','Dans le murmure des eaux, ils entendent l’avenir.','',26972),
(63705,'frFR','Les jinyu et leurs eauracles sont au cœur des plus grands évènements de l’histoire de la Pandarie.','',26972),
(63706,'frFR','Leurs visions ont bâti des empires, libéré des esclaves, et averti notre dernier empereur de la Fracture qui a brisé Azeroth il y a de cela dix mille ans.','',26972),
(63707,'frFR','Considérez ceci : la plus petite des voix peut changer le monde. Souvenez-vous-en, $gcher ami:chère amie;, la prochaine fois que vous décidez de commencer à lancer des pierres !','',26972),
(63708,'frFR','Oh, mon élève, vous souhaitez étudier les mantides ? Soyez prévenu : la frontière pandarène est parsemée des tombes d’anciens élèves.','',26972),
(63709,'frFR','Les mantides ne sont guère des enseignants indulgents.','',26972),
(63710,'frFR','À chaque génération, l’essaim des mantides assaillit le mur de l’Échine du Serpent en très grand nombre. Ils tuent de nombreux Pandarens, alors nous tuons plusieurs fois ce nombre des leurs en retour. Et pourtant à chaque génération, ils attaquent à nouveau. Pourquoi font-ils cela ?','',26972),
(63711,'frFR','Nous autres Pandarens ne le savons pas.','',26972),
(63712,'frFR','Nos écrits anciens disent que les mantides ont toujours été là. Ils remontent à encore plus loin que les mogu. D’où viennent-ils ?','',26972),
(63713,'frFR','Nous autres Pandarens ne le savons pas.','',26972),
(63714,'frFR','Peut-être que si vous arriviez à vous lier d’amitié avec les mantides et gagner leur estime, ils vous apprendraient leurs secrets. Mais je vous préviens :','',26972),
(63715,'frFR','Nul n’a jamais gagné l’amitié des mantides.','',26972),
(63716,'frFR','Voici en revanche ce que savent les Pandarens : en décimant notre peuple, en massacrant des dizaines de milliers de pandarens, génération après génération, ils nous ont enseigné la valeur de la vie. Un don précieux mais fugace. Si facilement éteinte… en un instant.','',26972),
(63717,'frFR','Voilà ce que les mantides nous ont appris.','',26972),
(63718,'frFR','Que craignez-vous le plus au monde ? Avez-vous vaincu votre peur… ou votre peur vous a-t-elle vaincu ?','',26972),
(63719,'frFR','Dans les jours anciens qui ont précédé la Fracture du monde, les empereurs mogu régnaient sur la Pandarie. Mon peuple a été asservi, et il avait peur.','',26972),
(63720,'frFR','Les mogu maniaient de main de maître la douleur et la torture, la magie noire, et des armes brutales. Aucun Pandaren, Hozen ou Jinyu ne pouvait résister au pouvoir qu’ils détenaient. Et mon peuple avait peur.','',26972),
(63721,'frFR','Ce furent les mogu qui construisirent l’Échine du Serpent. Les moins chanceux des esclaves furent envoyés le construire et le défendre. De la chair à mantides. Et mon peuple avait peur.','',26972),
(63722,'frFR','Alors que leur empire s’étendait, les mogu se lancèrent dans des expériences exploitant les secrets du val. Ils confectionnèrent de terribles armes vivantes de chair et de pierre. Et mon peuple avait peur.','',26972),
(63723,'frFR','Dans leur orgueil, les mogu ne virent jamais à quel point leur chute était proche, préparée non pas pas leurs ennemis, mais par ceux qu’ils opprimaient. Le jour où un esclave se leva…','',26972),
(63724,'frFR','… et n’eut plus peur.','',26972),
(63725,'frFR','Le feu ! C’est le plus magique des éléments. Il nous réchauffe, il cuit notre nourriture. C’est l’âtre qui fait d’une maison un foyer. Entre les bonnes mains, le feu peut changer le fer en épées ou en socs. Non maîtrisé, le feu peut détruire une ville.','',26972),
(63726,'frFR','Le feu est l’instrument du changement.','',26972),
(63727,'frFR','Il y a bien longtemps, un groupe de robustes chasseurs nomades parcourait le monde. Par un tour du destin, il se trouvait en Pandarie lorsque la Fracture sépara les continents d’Azeroth. Les nomades se retrouvèrent pris au piège dans les steppes de Tanglong, une terre rude et dangereuse.','',26972),
(63728,'frFR','Ces nobles chasseurs trouvèrent un moyen de survivre seuls. Le feu était la clé. Ils exploitèrent le naphte du sol. Ils s’en servirent pour chauffer leurs maisons, cuire leur nourriture, et brûler leurs ennemis. Ils devinrent FORTS.','',26972),
(63729,'frFR','Les yaungols naquirent des flammes du destin. Ils survivent au-delà du mur, car ils refusent de se soumettre à toute loi autre que la leur.','',26972),
(63730,'frFR','Le destin a-t-il été cruel envers les yaungols ? Autant se demander si le feu est bon ou mauvais.','',26972),
(63731,'frFR','Le destin est comme le feu. Il peut nous façonner comme nous détruire.','',26972),
(63732,'frFR','Tout ce qui compte, c’est ce que vous en faites.','',26972),
(63733,'frFR','Ah ! Vous souhaitez connaître l’histoire du dernier et du plus grand de nos empereurs, Shaohao ? Mon $gami:amie;, je n’ai pas le temps pour l’instant de vous conter toutes ses aventures, mais ses actes il y a dix mille ans se font encore sentir aujourd’hui même.','',26972),
(63734,'frFR','Nous savons qu’il s’est débarrassé de ses doutes dans la forêt de Jade. Qu’il s’est purifié du désespoir dans les terres sauvages de Krasarang. Qu’il a surmonté sa peur dans les steppes de Tanglong. Et qu’il a vaincu la colère, la haine et la violence dans les cimes des montagnes de Kun-Lai.','',26972),
(63735,'frFR','Cela est bien connu, et des temples honorent ces lieux sacrés parmi les sacrés.','',26972),
(63736,'frFR','Mais je veux que vous vous imaginiez dans cette même vallée le jour où il est revenu de son voyage. Imaginez que vous étiez là quand les portes se sont ouvertes pour lui. À ce moment, notre empereur était devenu un être de pure lumière. Dépourvu de doutes, de peurs, de haine…','',26972),
(63737,'frFR','On dit que tous les arbres du val ont fleuri à son arrivée, et sont encore en fleur aujourd’hui.','',26972),
(63738,'frFR','Si seulement nous pouvions tous vivre comme le plus saint de tous nos empereurs. Abandonner tous nos fardeaux et vivre en harmonie avec le cosmos. Voilà, je le crois, le message qu’il nous a laissé… avant de devenir un avec la terre et de protéger la Pandarie des terreurs de la Fracture.','',26972),
(63739,'frFR','Merci, cher empereur.','',26972),
(63740,'frFR','Un jour, un père en eut assez de la mauvaise conduite de son petit. « Tu te comportes comme un hozen ! », le grondait-il. Mais son fils continuait.','',26972),
(63741,'frFR','Pour lui donner une leçon, le père emmena son petit dans la forêt pour lui montrer comment vivaient les hozen. « Vois-tu comment sont les hozen ? » lui demanda-t-il. « Veux-tu vivre comme cela ? »','',26972),
(63742,'frFR','Les hozen sont en effet des plus turbulents. Ils ne vivent pas vieux, peu atteignent leur vingtième anniversaire. Leurs chefs ont tous quatorze ou quinze ans. Étiez-vous sage à quatorze ans ? Méditez là-dessus !','',26972),
(63743,'frFR','Le père demanda ensuite à son petit ce qu’il avait appris.','',26972),
(63744,'frFR','« J’ai appris que nous travaillons dur et nous échinons sur notre lopin de terre, alors que les hozen ont le monde entier pour jardin, répondit le petit. J’ai appris que nous plissons les yeux à la lumière d’une seule bougie, alors que les hozen ont la lumière des étoiles. J’ai appris que je vais à l’école tous les jours, alors que les hozen apprennent en faisant. »','',26972),
(63745,'frFR','Et le petit de conclure : « J’aimerais beaucoup vivre comme un hozen ! »','',26972),
(63746,'frFR','Qui, alors, était le plus sage ? Le père ou le fils ?','',26972),
(63747,'frFR','À vous de le décider, mon $gami:amie;.','',26972),
(64260,'frFR','Vous pensez pouvoir m’affronter ? La plupart des filles ont horreur des serpents, mais moi je les trouve mignons !','Vous pensez pouvoir m’affronter ? La plupart des filles ont horreur des serpents, mais moi je les trouve mignons !',26972),
(65087,'frFR','Ah, mon assassin préféré ! J’espérais bien vous retrouver en Pandarie.','',26972),
(65088,'frFR','Très bien. Nous devons parler.','',26972),
(65089,'frFR','Tong ! À boire, s’il vous plaît.','',26972),
(65090,'frFR','Mon père, Aile de mort, a tenté de détruire tout Azeroth.','',26972),
(65091,'frFR','Il s’était fourvoyé, évidemment, mais il avait raison sur un point : notre monde est… très fragile.','',26972),
(65092,'frFR','Nous sommes un point de lumière dans un univers d’ombres. Une flamme dans la tempête.','',26972),
(65093,'frFR','Parfois, je me dis que c’est la précarité même de notre monde qui a conduit mon père à la folie.','',26972),
(65094,'frFR','Ah. Merci, Tong.','',26972),
(65095,'frFR','Ce que je veux dire : je pense que nous courons droit vers notre perte. Et non, je ne parle pas du conflit actuel entre la Horde et l’Alliance.','',26972),
(65096,'frFR','Croyez-moi. Ce que Garrosh Hurlenfer a infligé à Theramore n’est rien en comparaison des horreurs qui se dirigent sur notre monde à l’instant même.','',26972),
(65097,'frFR','Mais la guerre me trouble profondément. Comprenez-vous mon inquiétude ?','',26972),
(65098,'frFR','Une Azeroth divisée ne peut se dresser d’un seul bloc contre les ténèbres.','',26972),
(65099,'frFR','Il faut mettre un terme à cette guerre. Et vite. Avant qu’elle n’engloutisse toutes nos forces !','',26972),
(65100,'frFR','Je veux que vous sachiez que l’Alliance a mon soutien inconditionnel dans cette campagne.','',26972),
(65101,'frFR','Soyez $gassuré:assurée; de ma loyauté envers la Horde.','',26972),
(65102,'frFR','Comment mettre un terme définitif à ce conflit ? Je pense que la réponse est détenue par des héros comme vous.','',26972),
(65103,'frFR','Assurons-nous que vous êtes à la hauteur… puis nous vous équiperons en conséquence.','',26972),
(65150,'frFR','Je dispose de deux cents bateaux, et mon fils se trouve sur le seul qui manque à l’appel !','',26972),
(65151,'frFR','Je suis désolé, mais je ne peux pas rentrer maintenant.','',26972),
(65152,'frFR','J’ai décidé de partir en quête du val… quête du val… vaaaal…','',26972),
(65153,'frFR','Emparez-vous de cette côte, et METTEZ CE NOUVEAU CONTINENT À FEU ET À SANG !','',26972),
(65214,'frFR','Ah, encore une créature d’au-delà des brumes.','',26972),
(65215,'frFR','Il y a dix mille ans, le dernier empereur pandaren vint requérir mes conseils. Lui aussi était tourmenté. Voyons si vous avez raison, Taran. Voyons comment cette personne supporte les tourments de l’âme.','',26972),
(65273,'frFR','Nous sommes d’accord. Combattre pour une bonne cause, défendre son foyer ou sa famille, est un geste noble. Mais que dire de la vengeance ? De la colère ? Ces émotions sont profondément ancrées dans cet être.','',26972),
(65326,'frFR','Bien parlé, Zhi. Ces étrangers d’au-delà des brumes ne manquent pas de passions, mais voyons s’ils peuvent les contrôler. Au-delà de la colère, il y a la haine, source de toute souffrance. Qu’est-ce donc… votre haine a un visage !','',26972),
(65350,'frFR','Cette créature a prouvé qu’elle contrôlait sa colère. Entre les paroles du jeune Humain et les actions de cette personne, je crois que je comprends. Ceux qui viennent d’au-delà des brumes ont été endurcis par les combats. Ils ont des cicatrices, mais ils ont appris beaucoup. Je leur fais confiance.','',26972),
(65352,'frFR','C’est décidé. Le val de l’Éternel printemps restera ouvert. Les transgressions des étrangers ont été considérables… mais je vois en eux le pouvoir de réparer le mal qui a été fait.','',26972),
(65354,'frFR','Je vais consulter les autres. Retrouvez-moi aux portes.','',26972),
(65404,'frFR','Vous arrivez trop tard.','',26972),
(65405,'frFR','Les restes du roi-tonnerre, ils sont partis sur l’île du Jugement…','',26972),
(65406,'frFR','Les anciens rites on les a accomplis…','',26972),
(65407,'frFR','Même maintenant, le vrai empereur de Pandarie, il vit et il respire à nouveau.','',26972),
(65409,'frFR','Malheur aux usurpateurs pandarens ! Les mogu ils vont régner de nouveau, et les Zandalari ils auront un nouveau foyer…','',26972),
(65410,'frFR','Les restes, récupérez-les, mes frères !','',26972),
(65411,'frFR','Le roi-tonnerre, il revivra…','',26972),
(65421,'frFR','Sous Kun-Lai, le tonnerre sommeille…','',26972),
(65422,'frFR','L’orage d’antan repose, fourbu…','',26972),
(65423,'frFR','Mais le sang du royaume, frère, veille…','',26972),
(65424,'frFR','Sur la vie des exclus…','',26972),
(65425,'frFR','Dans le sang zandalari, pour le subjuguer…','',26972),
(65426,'frFR','Par la voix zandalari, il va s’éveiller…','',26972),
(65970,'frFR','','Enfants de la Pandarie. Les brumes se sont levées. Pour le meilleur comme pour le pire, notre terre est ouverte au monde.',26972),
(65971,'frFR','','Rassemblons-nous pour reconstruire ce lieu sacré, ce sera la première étape pour soigner un monde déchiré par la guerre.',26972),
(65972,'frFR','J’ai foi en nos amis d’au-delà des brumes.','',26972),
(65973,'frFR','Leur force est source d’inspiration… et nous en avons grand besoin. Nous devons croire en la pureté de leur cœur.','',26972),
(65982,'frFR','Nous progressons dans cette brume depuis plusieurs heures, général. L’équipage commence à s’inquiéter…','',26972),
(65983,'frFR','Retournez à votre poste, soldat ! Nous trouverons cette terre, ou nous mourrons en la cherchant.','',26972),
(65984,'frFR','Un bateau de l’Alliance ! À bâbord toutes !','',26972),
(65985,'frFR','À l’attaque !','',26972),
(65986,'frFR','Vaisseau ennemi à tribord ! Tous aux canons ! Feu à volonté !','',26972),
(65989,'frFR','Ha ha, en plein dedans ! Ils tombent !','',26972),
(65990,'frFR','Terre en vue !','',26972),
(65995,'frFR','Heu, y’a un truc qui déconne, général… On perd de l’altitude ! Vite !','',26972),
(66179,'frFR','Grâce à vos actes, les hozen craignent votre peuple. Excusez-moi un instant…','',26972),
(66180,'frFR','Ah ! Le voilà. Il y a plus de quatorze mille ans, l’ensemble de cette terre était gouverné par un peuple de terrifiants seigneurs de guerre appelés « les mogu. »','',26972),
(66181,'frFR','Les mogu régnaient par la PEUR. Et c’est ce qui les a maintenus au pouvoir… jusqu’à ce que les premiers moines pandarens enseignent le COURAGE à mon peuple.','',26972),
(66182,'frFR','Ensuite, les mogu ont été renversés.','',26972),
(66183,'frFR','Vous voyez, ceux qui dirigent par la peur ne peuvent conserver le pouvoir que si leurs sujets manquent de courage.','',26972),
(66184,'frFR','Les hozen sont bien des choses, mais ce ne sont pas des couards… pas pour longtemps. Si vous ne voulez pas avoir à les combattre, vous devez… les inspirer !','',26972),
(66185,'frFR','Je vous aiderai, mais j’aimerais commencer par en apprendre un peu plus sur votre peuple. Accepteriez-vous de m’accompagner pendant un moment ?','',26972),
(66267,'frFR','3…','',26972),
(66423,'frFR','Quelle est la source de VOTRE pouvoir ? Réfléchissez bien avant de répondre. De nombreux aventuriers pensent à leurs armes, à leur équipement, ou à leurs tomes de puissance arcanique.','',26972),
(66424,'frFR','Il y a bien longtemps, quand les Pandarens étaient les esclaves de l’empire mogu, les armes nous étaient strictement interdites. Et nul ne pensait pouvoir affronter les mogu sans magie et sans acier.','',26972),
(66425,'frFR','Jusqu’à ce que Kang, le Poing de la Première Aube, nous ouvre les yeux.','',26972),
(66426,'frFR','Un jour, ce cher moine lança un défi aux autres esclaves. « Frappez-moi ! » demanda-t-il à ses frères.','',26972),
(66427,'frFR','Surpris, les esclaves pandarens tentèrent de le frapper. L’un après l’autre, ils échouèrent, car il interceptait leurs coups tel un danseur et esquivait leurs attaques tel un roseau sous le vent.','',26972),
(66428,'frFR','« Nos dos ont été durcis par les fouets des mogu », leur dit-il. « Nos bras sont devenus plus forts d’avoir construit leurs forteresses. Nos esprits sont aiguisés d’avoir travaillé aux côtés de notre ennemi. Vous croyez que les mogu sont plus forts ? Moi, je dis que nous sommes leur force ! »','',26972),
(66429,'frFR','Les fermiers, les maçons, les bergers et les forgerons… tous s’inclinèrent devant Kang. « Apprenez-nous, dirent-ils. Apprenez-nous à nous battre. »','',26972),
(66430,'frFR','Et quand ils se relevèrent… ils le firent en tant que guerriers.','',26972),
(66431,'frFR','Votre voix. Vos mains. VOILÀ les outils des vrais héros. Utilisez-les bien… et vous changerez le monde.','',26972),
(66454,'frFR','2…','',26972),
(66818,'frFR','Hahahahaha !','',26972),
(66916,'frFR','Vous aimez mes serpents ? J’ai l’impression qu’ils ne vous aiment pas !','Vous aimez mes serpents ? J’ai l’impression qu’ils ne vous aiment pas !',26972),
(67111,'frFR','','Mort à tous ceux qui osent défier mon empire !',26972),
(67162,'frFR','<Rugit.>','',26972),
(67227,'frFR','Plus jamais ça !','',26972),
(67347,'frFR','','Tel est le destin de qui s’oppose à l’autorité.',26972),
(67602,'frFR','Auriez-vous un moment à m’accorder ?','',26972),
(67623,'frFR','','Mes serpents sont mignons, n’est-ce pas ? … N’EST-CE PAS ?',26972),
(67624,'frFR','','Vous n’aviez aucune chance face à mes adorables serpents et moi !',26972),
(67625,'frFR','','Impossible ! Ça ne se passera pas comme ça la prochaine fois !',26972),
(67626,'frFR','','Essayez de battre celui-là, pour voir !',26972),
(67627,'frFR','','Dans les dents !',26972),
(67628,'frFR','','Nooooon ! Mes jolis serpents !',26972),
(67631,'frFR','','Je vais vous geler sur place !',26972),
(67632,'frFR','','Je vous l’ai dit, mon chou. Vous n’avez pas le sang assez chaud pour vous frotter à moi !',26972),
(67633,'frFR','','Ouille ! Ça brûle !',26972),
(67634,'frFR','','Faites une pause, détendez-vous. Ce sera bientôt votre tour.',26972),
(67635,'frFR','','Ça fait boule de neige, vous ne pouvez plus rien contrôler ! Vous n’avez plus aucune chance maintenant !',26972),
(67636,'frFR','','Han, j’l’ai cassé !',26972),
(67637,'frFR','','Vous supportez mieux le froid que je ne l’aurais cru.',26972),
(67638,'frFR','','Votre mascotte est un impitoyable tueur au sang froid !',26972),
(67639,'frFR','','Je ne vais pas vous laisser vous en tirer comme ça !',26972),
(67664,'frFR','… vous n’êtes que des fils de paysans.','',26972),
(67688,'frFR','','Cible verrouillée. Feu !',26972),
(67690,'frFR','','Réduisez-les en cendres !',26972),
(67691,'frFR','','Reçu cinq sur cinq. Montrons-leur de quel bois on se chauffe !',26972),
(67693,'frFR','','Bien reçu. Ça arrive.',26972),
(67694,'frFR','','Le transporteur est arrivé !',26972),
(67728,'frFR','','Ventenuit, au rapport ! Comment ça se passe de votre côté ?',26972),
(67729,'frFR','','Des troupes de la Horde nagent vers vous. Ouvrez le feu immédiatement.',26972),
(67730,'frFR','','Croyez-vous qu’ils hésiteraient à vous étrangler à mains nues ? DESCENDEZ-LES !',26972),
(67733,'frFR','Aucun signe du vaisseau, pas plus que de l’amiral Taylor ou du prince Anduin.','',26972),
(67734,'frFR','Amiral, je crois qu’ils veulent se rendre. Ils ne sont pas armés. Ils essaient juste de survivre !','',26972),
(67735,'frFR','Ce n’est pas juste… c’est un bain de sang… ils n’étaient pas armés. Beuh… Je ne… me sens pas bien…','',26972),
(67736,'frFR','Peut-être méritaient-ils de mourir.','',26972),
(67739,'frFR','Bande de sauvages ! Quelle est donc cette folie ?','',26972),
(67740,'frFR','Repos, soldats. C’est l’un des indigènes.','',26972),
(67741,'frFR','Nous sommes de l’Alliance, nous ne vous voulons aucun mal. Dites-moi, quelle est cette ombre qui me possédait ?','',26972),
(67742,'frFR','Ce n’est pas l’endroit pour en discuter. Pour faire court, vos doutes se sont concrètement manifestés, en conséquence de vos actes.','',26972),
(67743,'frFR','Vous ne comprenez pas… Nous sommes en guerre…','',26972),
(67744,'frFR','Oh, je comprends parfaitement. Je vois bien ce qui se passe. Mais la Pandarie n’est pas comme votre foyer. Cette terre vit, elle respire. Vous devriez faire attention aux énergies que vous apportez. Maintenant, éloignez ces armes !','',26972),
(67871,'frFR','Qu’est-ce… non… NON ! Ils avaient une base aérienne camouflée… mon vaisseau… mon… Hurlenfer va vouloir ma tête…','',26972),
(67872,'frFR','Ils doivent tous mourir.','',26972),
(67873,'frFR','Toi ! Homme-ours. Quelle était donc cette sorcellerie ?','',26972),
(67874,'frFR','Nous n’apportons qu’honneur, ainsi que le désir d’écraser nos ennemis. Votre peuple a-t-il aidé l’Alliance ?','',26972),
(67875,'frFR','$gÉtranger:Étrangère;, vos propres doutes se sont manifestés. La Pandarie n’est pas comme votre foyer. Cette terre vit, elle respire. Vous devriez faire attention aux énergies que vous apportez.','',26972),
(67876,'frFR','Nous ne souhaitons pas être impliqués dans votre bain de sang. Maintenant, baissez vos armes, ou vous aurez DEUX ennemis sur ce continent.','',26972),
(67877,'frFR','Vos doutes et votre haine ont semé le chaos dans ces ruines. Nettoyez derrière vous et retrouvez-moi au village en contrebas. Je vais faire de mon mieux pour vous expliquer.','',26972),
(67885,'frFR','Vous ne détruirez PAS ces terres comme vous avez souillé Kalimdor !','',26972),
(67926,'frFR','Trouillard !','',26972),
(68005,'frFR','Qu’est-ce que c’est que ce bordel ?','',26972),
(68006,'frFR','Amiral, nous constatons une forte présence indigène. Des bâtiments ouvragés…','',26972),
(68007,'frFR','Silence, tout le monde ! Tous sur la cible !','Silence, tout le monde ! Tous sur la cible !',26972),
(68008,'frFR','Vous avez entendu l’amiral. Concentrez vos tirs sur la base de la Horde.','',26972),
(68009,'frFR','Ils nous tirent dessus, commandant !','Ils nous tirent dessus, commandant !',26972),
(68010,'frFR','Utilisez vos torpilles sur ces vaisseaux.','',26972),
(68011,'frFR','Vaisseau détruit. Joli tir.','',26972),
(68012,'frFR','Bien joué. Aucune pitié !','Bien joué. Aucune pitié !',26972),
(68013,'frFR','Celui-là, c’est pour Theramore !','Celui-là, c’est pour Theramore !',26972),
(68014,'frFR','Des traces du vaisseau amiral ?','Des traces du vaisseau amiral ?',26972),
(68015,'frFR','Négatif, amiral. Aucun signe du capitaine Taylor ou de son vaisseau.','',26972),
(68016,'frFR','Arg ! On est touchés !','Arg ! On est touchés !',26972),
(68017,'frFR','Nous essuyons des tirs… Sully, plus haut !','',26972),
(68018,'frFR','On va pas y arriver ! Papa, on va bientôt se retrouver !','',26972),
(68019,'frFR','Ne les laissons pas s’en tirer ! Lancez-leur tout ce que vous avez !','Ne les laissons pas s’en tirer ! Lancez-leur tout ce que vous avez !',26972),
(68020,'frFR','Assez. Tous les postes au rapport. Préparez-vous à l’assaut terrestre.','Assez. Tous les postes au rapport. Préparez-vous à l’assaut terrestre.',26972),
(68022,'frFR','','Nous sommes au-dessus de la dernière position connue du bateau. Vous ne voyez rien ?',26972),
(68023,'frFR','Du brouillard… rien qu’un brouillard dense… Attendez ! À tribord ! Je vois des bateaux.','',26972),
(68025,'frFR','Après vous, $gmon bon monsieur:ma bonne dame;.','',26972),
(68026,'frFR','On dirait bien que j’accumule une nouvelle victoire !','',26972),
(68027,'frFR','Voilà qui est malencontreux.','',26972),
(68028,'frFR','Ah, mais est-ce que vous vous attendiez à ça ?','',26972),
(68029,'frFR','On dirait bien que je vais avoir une victoire facile, aujourd’hui !','',26972),
(68030,'frFR','Oh non, je perds !','',26972),
(68031,'frFR','Ici et maintenant, ou ailleurs et demain, c’est du pareil au même.','',26972),
(68032,'frFR','Je savais que j’avais fait le bon choix quand je m’y suis mis.','',26972),
(68033,'frFR','Peut-être que je pourrais retourner dans ma vieille ferme…','',26972),
(68034,'frFR','Je me suis rendu compte qu’il était parfois utile d’apporter quelques changements.','',26972),
(68035,'frFR','Si seulement ma femme pouvait voir ça. Je suis en train de gagner !','',26972),
(68036,'frFR','Il y en a plein d’autres là où je l’ai trouvé !','',26972),
(68037,'frFR','','Je ne vais pas vous ménager !',26972),
(68038,'frFR','','En pleine face !',26972),
(68039,'frFR','','Maman ! Maman ! $gLe méchant dompteur il:La méchante dompteuse elle; m’a pas laissé gagner !',26972),
(68040,'frFR','','Ah non, pas question !',26972),
(68041,'frFR','','Prends ça !',26972),
(68042,'frFR','','P… Pourquoi v… vous avez t… tué mon lapin… ?',26972),
(68043,'frFR','J’espère que vous êtes $gprêt:prête; à jeter vos mascottes en pâture à mes champions.','',26972),
(68044,'frFR','Je vous avais $gprévenu:prévenue; sur les dangers de ces bois.','',26972),
(68045,'frFR','Votre courage est impressionnant.','',26972),
(68046,'frFR','Vous sentez quelque chose ?','',26972),
(68047,'frFR','Quel spectacle !','',26972),
(68048,'frFR','Peu importe. Une vie contre une victoire, ce n’est pas un sacrifice vain.','',26972),
(68049,'frFR','En garde, des marins d’eau douce nous attaquent ! Tous aux harpons !','',26972),
(68050,'frFR','Tout le butin est pour moi ! Hic !','',26972),
(68051,'frFR','Pourquoi est-ce que vous avez fait ça ? … Hips !','',26972),
(68052,'frFR','Fais-les souffrir !','',26972),
(68053,'frFR','Çha… ça c’est du combat ! $gChelui:Chelle; qui contrôle ches mascottes, c’est quelqu’un… hips !','',26972),
(68054,'frFR','Une mascotte à terre !','',26972),
(68055,'frFR','On va vous écraser.','',26972),
(68056,'frFR','Là, ça c’est les choses sérieuses dont Zunta il parle !','',26972),
(68057,'frFR','C’est vous qui gagnez aujourd’hui. Profitez.','',26972),
(68058,'frFR','Et qu’est-ce que vous dites de vous mesurer à celui-là ?','',26972),
(68059,'frFR','Bonne bête. Zunta il te donnera une récompense après.','',26972),
(68060,'frFR','Pourquoi vous êtes méchant avec Zunta, hein ?','',26972),
(68061,'frFR','','Nous sommes en combat. Écrasez-les !',26972),
(68062,'frFR','','C’est notre jour de gloire.',26972),
(68063,'frFR','','Je vous aurai, un jour.',26972),
(68064,'frFR','','Je ne vous laisserai pas ce plaisir.',26972),
(68065,'frFR','','Continue ! Tue-le !',26972),
(68066,'frFR','','Peu importe. Ce n’est pas ça qui m’empêchera de gagner !',26972),
(68067,'frFR','','Ne vous laissez pas leurrer par mon calme. Je vais vous écraser.',26972),
(68068,'frFR','','La victoire est à nous, mes enfants !',26972),
(68069,'frFR','','Bien joué. Vous m’avez vaincue, et ce n’est pas donné à tout le monde.',26972),
(68070,'frFR','','Retournement de situation !',26972),
(68071,'frFR','','Victoire !',26972),
(68072,'frFR','','Comment avez-vous pu ?',26972),
(68073,'frFR','','Quand j’en aurai fini avec toi, tu auras mal comme tu n’as jamais eu mal auparavant.',26972),
(68074,'frFR','','Tu la sens, la douleur, mec ?',26972),
(68075,'frFR','','J’ai jamais vu quelqu’un se battre comme toi tu te bas.',26972),
(68076,'frFR','','Je parie que celle-là, tu l’avais pas vue venir.',26972),
(68077,'frFR','','Regardez comme elle souffre, cette petite chose !',26972),
(68078,'frFR','','Aïe, on dirait que celui-ci a eu mal !',26972),
(68079,'frFR','','Je vous préviens, je ne ploierai pas sous votre assaut.',26972),
(68080,'frFR','','Combattre la force de ces terres est inévitablement futile.',26972),
(68081,'frFR','','Vous combattez bien.',26972),
(68082,'frFR','','La terre ne ploiera jamais.',26972),
(68083,'frFR','','Le cycle continue.',26972),
(68085,'frFR','','Vous combattez une force irrésistible.',26972),
(68086,'frFR','Nous nous bat !','',26972),
(68087,'frFR','Moi gagne !','',26972),
(68088,'frFR','NON ! MOI GAGNE !','',26972),
(68089,'frFR','Non ! Pas mort ! Tape-lui plutôt !','',26972),
(68090,'frFR','Gentille petite chose ! Tu tues l’autre petite chose !','',26972),
(68091,'frFR','Pourquoi tu tapes pas ? J’ai dit « tape » !','',26972),
(68092,'frFR','','Commençons.',26972),
(68093,'frFR','','On dirait bien que je vous ai scotché au sol !',26972),
(68094,'frFR','','Vous nous avez descendus !',26972),
(68095,'frFR','','Bon travail. Repose-toi.',26972),
(68096,'frFR','','On va peut-être bien gagner.',26972),
(68097,'frFR','','Une magnifique créature est tombée.',26972),
(68098,'frFR','','Activation des modules d’aggression.',26972),
(68099,'frFR','','Vous n’aviez aucune chance face à mon équipe améliorée !',26972),
(68100,'frFR','','Échec système complet !',26972),
(68101,'frFR','','Puce d’auto-préservation enclenchée.',26972),
(68102,'frFR','','On n’abandonne pas. Pleine puissance.',26972),
(68103,'frFR','','Un coup de pinceau et il n’y paraîtra plus !',26972),
(68104,'frFR','Vous croyez que vous me faites peur ? J’ai affronté Onyxia !','',26972),
(68105,'frFR','Qui c’est l’chef ? C’est moi l’chef !','',26972),
(68106,'frFR','J’espère que vous vous ferez manger par un dragon !','',26972),
(68107,'frFR','OK, on arrête les frais. Échange !','',26972),
(68108,'frFR','Voilà ce qui arrive quand on descend dans le nid des dragons.','',26972),
(68113,'frFR','Je me suis fait écraser !','',26972),
(68117,'frFR','Vous ne pouvez pas comprendre les forces liguées contre vous.','',26972),
(68118,'frFR','Peut-être que maintenant vous verrez les choses à ma façon ?','',26972),
(68120,'frFR','Vous ne faites que nous retarder. Nous ne pouvons être arrêtés.','',26972),
(68122,'frFR','N’avez-vous jamais vu créature plus fabuleuse ?','',26972),
(68123,'frFR','','Des vaisseaux de la Horde. Tous à vos postes ! Remontons en altitude. Branlebas de combat ! Nous partons en guerre !',26972),
(68124,'frFR','Abandonnez maintenant, tant que vous le pouvez encore !','',26972),
(68125,'frFR','Un léger contretemps.','',26972),
(68168,'frFR','','Ce ne sera pas long.',26972),
(68170,'frFR','Personne ne peut arrêter les Totems-Sinistres !','',26972),
(68171,'frFR','','Votre impudence sera votre perte. Souvenez-vous de mes paroles !',26972),
(68172,'frFR','','Ce n’est pas terminé !',26972),
(68173,'frFR','','Si faible.',26972),
(68174,'frFR','','Vous allez payer pour ça.',26972),
(68177,'frFR','Ne vous inquiétez pas. Ce sera vite fini.','',26972),
(68178,'frFR','Alors, pas si mal, non ?','',26972),
(68179,'frFR','Peut-être que je devrais réévaluer le dosage pour les empêcher de mourir aussi vite.','',26972),
(68180,'frFR','Ne vous surestimez pas.','',26972),
(68181,'frFR','Ce ne sera plus très long.','',26972),
(68182,'frFR','Comme c’est malencontreux.','',26972),
(68183,'frFR','','Je vais vous montrer en direct la force de la non-mort.',26972),
(68184,'frFR','','Je savais que j’étais la plus forte !',26972),
(68185,'frFR','','Non… non…',26972),
(68186,'frFR','','Repose-toi, mon précieux.',26972),
(68187,'frFR','','Oui… rejoins-nous !',26972),
(68188,'frFR','','Non ! Nous ne serons pas vaincus !',26972),
(68189,'frFR','Vous voulez vraiment affronter la puissance des dragons ?','',26972),
(68190,'frFR','Il est temps de montrer à mon frère qui est le vrai maître dompteur de la famille !','',26972),
(68191,'frFR','Vous avez eu de la chance. C’est tout.','',26972),
(68192,'frFR','Assez !','',26972),
