(68246,'frFR','Vous devez vous concentrer.','',26972),
(68247,'frFR','Une manœuvre adroite, $gétranger:étrangère;.','',26972),
(68251,'frFR','Je vais vous écraser sous l’assaut de mon équipe !','',26972),
(68252,'frFR','J’espère que vous comprenez maintenant qu’il est vain d’espérer me battre.','',26972),
