(68685,'frFR','Vous n’avez aucune chance. Je vais vous vaincre !','',26972),
(68686,'frFR','Vous en avez assez ?','',26972),
(68687,'frFR','Vous ne faites pas le poids.','',26972),
(68688,'frFR','Vous avez eu de la chance.','',26972),
(68689,'frFR','Fini de jouer. Je vais vous écraser !','',26972),
(68690,'frFR','','Votre série de victoires s’arrête ici, $gdompteur:dompteuse;.',26972),
(68691,'frFR','','Peu sont capables de garder leur équilibre face à moi. Voyons si vous vous comportez différemment.',26972),
(68692,'frFR','','C’est ce que je pensais. Vous n’avez pas encore les compétences pour me vaincre.',26972),
(68693,'frFR','','Ne vous tracassez pas. Vous n’êtes qu’$gun:une; parmi tant d’autres que j’ai vaincus.',26972),
(68694,'frFR','','Une merveille de technicité dont vous faites preuve !',26972),
(68695,'frFR','','Votre victoire est méritée, $gdompteur:dompteuse;.',26972),
(68696,'frFR','','Nous n’en avons pas encore terminé.',26972),
(68697,'frFR','','Le val m’insuffle sa puissance.',26972),
(68698,'frFR','','Vous pouvez fuir le combat, si vous le souhaitez.',26972),
(68699,'frFR','','Fantastique !',26972),
(68700,'frFR','','Peut-être que vous avez quand même une chance contre moi, après tout.',26972),
(68701,'frFR','','Bien joué. Mais êtes-vous assez $gdéterminé:déterminée; pour aller jusqu’au bout ?',26972),
(68702,'frFR','Ainsi, nous nous affrontons enfin.','',26972),
(68703,'frFR','Je sais déjà que je vais gagner.','',26972),
(68704,'frFR','Comme les eaux l’avaient prédit.','',26972),
(68705,'frFR','La victoire m’appartient !','',26972),
(68706,'frFR','Pris comme un poisson hors de l’eau !','',26972),
(68707,'frFR','Vous êtes $gun sacré dompteur:une sacrée dompteuse; !','',26972),
(68708,'frFR','Vous ne me vaincrez pas par la force brute.','',26972),
(68709,'frFR','Que les eaux me guident.','',26972),
(68710,'frFR','Nous vous submergerons avant que vous n’ayez le temps de réagir.','',26972),
(68711,'frFR','Mes mascottes réclament une autre victime.','',26972),
(68712,'frFR','Il y en a plein d’autres là où je l’ai trouvé !','',26972),
(68713,'frFR','Ça ne se passe pas comme prévu…','',26972),
(68714,'frFR','Vous avez déjà perdu.','',26972),
(68715,'frFR','Je vais vous vaincre.','',26972),
(68716,'frFR','Le véritable maître en est sorti victorieux.','',26972),
(68718,'frFR','Tout ça fait partie de mon plan.','',26972),
(68719,'frFR','J’ai perdu face à votre maîtrise.','',26972),
(68720,'frFR','Je ne comprends pas. Comment ai-je pu perdre ?','',26972),
(68721,'frFR','Repose-toi, que le combat soit toujours en notre faveur.','',26972),
(68722,'frFR','Vous ne pouvez vaincre les sables changeants de ces terres.','',26972),
(68723,'frFR','Une autre mort cachée par les sables de ce désert.','',26972),
(68724,'frFR','Le combat tourne une fois de plus à mon avantage.','',26972),
(68725,'frFR','Un évènement fâcheux.','',26972),
(68726,'frFR','Peut-être ce combat ne sera-t-il pas aussi simple que je le croyais.','',26972),
(68727,'frFR','Vas-y, Smaragdus ! Montre-leur la sottise qu’ils commettent !','',26972),
(68728,'frFR','','Vas-y, Crochu ! Chope-les !',26972),
(68729,'frFR','Balaie-les, Faucheur 800 !','',26972),
(68730,'frFR','','Tu peux le faire, Pluchette !',26972),
(68731,'frFR','Achève-les, Sombre-Croc.','',26972),
(68732,'frFR','Envoie-les en enfer, Piko !','',26972),
(68733,'frFR','Épiquant, montre-leur ce dont tu es capable !','',26972),
(68734,'frFR','','Déchire-les, Étripeur !',26972),
(68735,'frFR','','À toi, monsieur Pincette !',26972),
(68737,'frFR','','Fais les souffrir, Constricteur.',26972),
(68738,'frFR','','Rochecuir, montre-leur ta force !',26972),
(68739,'frFR','Criss, tire !','',26972),
(68740,'frFR','','Saule, à toi de te lancer !',26972),
(68741,'frFR','','Personne ne peut battre Poulet-matic !',26972),
(68742,'frFR','Vas-y, Brûlo, rôtis-les !','',26972),
(68743,'frFR','Faites face à la fureur d’Ultramus !','',26972),
(68744,'frFR','','Cho’guane, donne-leur une bonne leçon.',26972),
(68745,'frFR','','Blanchette, glace-leur le sang !',26972),
(68746,'frFR','Peut-être que le sujet n° 142 sera meilleur que le sujet n° 141.','',26972),
(68747,'frFR','','Porte-Peste, montre-leur la puissance de la peste !',26972),
(68748,'frFR','Affrontez le courroux d’Obsidien !','',26972),
(68749,'frFR','Sors de là, Coacoa !','',26972),
(68750,'frFR','Ignéus, brûle-les pour moi, tu veux ?','',26972),
(68751,'frFR','','Chasse-les, Traque-Nuit.',26972),
(68752,'frFR','','Goliath connecté.',26972),
(68753,'frFR','Tu peux le faire, Fongor !','',26972),
(68754,'frFR','Pas-Lourd, montre à $gce dompteur:cette dompteuse; ce dont tu es capable !','',26972),
(68755,'frFR','Mâchouille, à toi de montrer ta force.','',26972),
(68756,'frFR','Arcanos, montre-leur ta puissance sans fin !','',26972),
(68757,'frFR','Je crois en toi, Gloubbels !','',26972),
(68758,'frFR','Couturé, tu veux bien montrer à $gce dompteur:cette dompteuse; comment nous aimons nous battre ?','',26972),
(68759,'frFR','Drogar, détruis-les !','',26972),
(68760,'frFR','Fend-la-Chair va vous tuer.','',26972),
(68761,'frFR','Grisou, fierté de Forgefer, viens sur le champ de bataille.','',26972),
(68762,'frFR','','Dor la Muraille, rejoins-nous sur le champ de bataille.',26972),
(68763,'frFR','Dos-Épineux va vous écraser !','',26972),
(68764,'frFR','','Personne ne peut te battre, Casse-Dent !',26972),
(68765,'frFR','Biquet, viens affronter cet ennemi.','',26972),
(68766,'frFR','Pinçon, viens te battre.','',26972),
(68767,'frFR','','Fouette-Tempête, gagne contre ces ennemis.',26972),
(68768,'frFR','Réduis-les en pièces, Fracture !','',26972),
(68769,'frFR','Je t’appelle, Kali.','',26972),
(68770,'frFR','Ne laisse aucune trace d’eux, Amythel. Détruis-les !','',26972),
(68771,'frFR','Vous n’avez aucune chance face à Pyth.','',26972),
(68772,'frFR','Frôleur, mon vieil ami, c’est à toi.','',26972),
(68902,'frFR','Et c’est parti.','',26972),
(68903,'frFR','Je vous en prie, profitez du temps qu’il vous reste à la foire. Ou peut-être vouliez-vous jouer une autre manche ?','',26972),
(68904,'frFR','Bien joué, bien joué.','',26972),
(68905,'frFR','Une autre manche peut-être… ?','',26972),
(68906,'frFR','C’est peut-être vraiment le fleuron de la foire, après tout.','',26972),
(68907,'frFR','Hélas ! Trop tôt.','',26972),
(68991,'frFR','Bon ! Je pense qu’on va avoir besoin de soutien aérien.','',26972),
(68992,'frFR','Des démolisseurs ? Rien qu’un peu d’ingéniosité gobeline ne peut surmonter. Envoyez les gyrocoptères !','',26972),
(68993,'frFR','Mmh. Ces démolisseurs semblent être particulièrement sensibles aux fusées. Envoyez les gyrocoptères !','',26972),
(68994,'frFR','Les Orcs sont dangereux, mais les Orcs montés le sont encore davantage. Lâchez les chiens !','',26972),
(68995,'frFR','Des loups en captivité ? On devrait libérer ces pauvres animaux.','',26972),
(68996,'frFR','Vous savez, j’ai souvent pensé à fabriquer un louveteau mécanique. On devrait pouvoir s’en servir pour étudier ces loups de plus près.','',26972),
(68997,'frFR','Ah ! Je vais avoir l’occasion de tester mon tunnel-o-tron Mk V ! Tenez-vous bien !','',26972),
(68998,'frFR','C’est le moment de vous faire entrer dans la forteresse. Accrochez-vous !','',26972),
(68999,'frFR','Le moment est venu de tester ma nouvelle amélioration « Aile creusante » ! Accrochez-vous !','',26972),
(69001,'frFR','Oups ! Désolé.','',26972),
(69002,'frFR','Mmhh. La télémétrie ne semble pas fonctionner.','',26972),
(69003,'frFR','Note pour plus tard : fabriquer un parascope.','',26972),
(69004,'frFR','C’était un mur, ça ? C’est ce que m’a évoqué le bruit en tout cas.','',26972),
(69005,'frFR','Ce serait beaucoup plus facile si je pouvais voir.','',26972),
(69021,'frFR','Des bombes gobelines. Elles ont un gros point faible : les autres bombes. Je reviens tout de suite.','',26972),
(69022,'frFR','Encore des bombes gobelines ? J’ai l’impression qu’hier encore je me débarrassais d’un tas de bombes gobelines. Attendez ici un instant.','',26972),
(69023,'frFR','C’est sûr, les Gobelins adorent leurs bombes. Allons-y et montrons-leur comment un Gnome fabrique une bombe. Je reviens tout de suite.','',26972),
(69351,'frFR','…J’ai lu la peur dans vos yeux, Jubeka.','',26972),
(69352,'frFR','','Que vouliez-vous me montrer ?',26972),
(69353,'frFR','Gul’dan a détruit ce monde dans sa poursuite du pouvoir… et vous avez peur que j’en fasse de même en Azeroth.','',26972),
(69354,'frFR','','Quoi… ? Non ! Je… Je n’ai… aucune idée…',26972),
(69355,'frFR','','Non ! Reculez… ! Vous… vous êtes dangereux. Je me contente d’invoquer des démons quand vous…',26972),
(69356,'frFR','','…vous tentez d’en devenir un vous-même !',26972),
(69357,'frFR','…','',26972),
(69358,'frFR','La démonologie est une science à deux visages…','',26972),
(69359,'frFR','… les menaces qui nous assiègent de l’extérieur…','',26972),
(69360,'frFR','… et celles que nous portons en nous.','',26972),
(69361,'frFR','Je vous ai choisie pour une raison.','',26972),
(69362,'frFR','… Si j’échoue, vous devez me bannir à tout jamais.','',26972),
(69363,'frFR','','Et quelle est donc cette obscure raison… ?',26972),
(69364,'frFR','Vos propos évasifs m’ennuient, garde funeste. Expliquez-moi pourquoi vos semblables et vous êtes versés dans les arts sacrificiels.','',26972),
(69365,'frFR','Mon contrat stipule que je dois combattre pour vous, pas vous révéler les secrets de la Légion, mortel.','',26972),
(69366,'frFR','N’essayez pas de me duper, démon !','',26972),
(69367,'frFR','Votre race existait bien avant la traîtrise de Sargeras. Qu’ÉTIEZ-vous ?','',26972),
(69368,'frFR','','Inutile de le savoir… Qu’espérez-vous donc faire, Kanrethad ?',26972),
(69369,'frFR','RESTEZ EN DEHORS DE ÇA ! Ce démon va répondre, MAINTENANT !','',26972),
(69370,'frFR','Quelle étrange requête. Même mon propre peuple ne se soucie pas de ses origines. Pourquoi cela vous intéresserait-il ?','',26972),
(69371,'frFR','Si vous ne vous en souciez pas, alors vous ne risquez rien à me le dire.','',26972),
(69372,'frFR','…avant que Sargeras nous libère, nous étions les chiens des titans, asservis à jamais pour réguler l’utilisation des Arcanes.','',26972),
(69373,'frFR','La magie sacrificielle était considérée comme la plus grande atteinte à la vie et nous étions programmés pour punir instantanément ceux qui s’adonnaient à cette… délicieuse sorcellerie.','',26972),
(69374,'frFR','Vous avez eu votre petit secret, Kanrethad. Maintenant je veux savoir une chose… pourquoi cela a-t-il de l’importance pour vous.','',26972),
(69375,'frFR','Il ne me semble pas que cela fasse partie de notre contrat. Nous en avons terminé.','',26972),
(69376,'frFR','Jubeka, terminez le rituel.','',26972),
(69379,'frFR','','Quelles étranges créatures. Pourquoi restent-elles alors que la Légion est partie depuis si longtemps ?',26972),
(69380,'frFR','…il y a une faille dans votre raisonnement.','',26972),
(69381,'frFR','Les observateurs étaient au service d’Illidan… pas de la Légion.','',26972),
(69382,'frFR','','Ah ?',26972),
(69383,'frFR','','Eh bien, lui aussi est parti… alors pourquoi restent-ils ?',26972),
(69384,'frFR','Comment le saurais-je ?','',26972),
(69385,'frFR','','Eh bien, j’ai passé des semaines à tenter de comprendre comment invoquer ces créatures, alors si vous savez quelque chose que j’ignore, j’apprécierais que vous le partagiez avec nous autres, pauvres créatures « inférieures ».',26972),
(69386,'frFR','Quel est le problème ? Vous avez maîtrisé le lien des diablotins gangrenés et des seigneurs du Vide sans effort.','',26972),
(69387,'frFR','','Mais ils étaient insignifiants en comparaison ! Ces choses ne sont jamais au même endroit.',26972),
(69388,'frFR','','Ils ont quelque chose… d’étrange. Quelque chose ne colle pas…',26972),
(69389,'frFR','','Oh bon sang…',26972),
(69436,'frFR','Pourrais-je discuter avec vous ? En privé… ?','',26972),
(69437,'frFR','Vous êtes un modèle pour la Horde. Vos faits d’arme en Norfendre et pendant le Cataclysme sont entrés dans la légende. C’est pourquoi je compte sur votre discrétion.','',26972),
(69438,'frFR','Je suis un forestier, pas un politicien. Mais bon gré mal gré, le rôle de dirigeant m’incombe aujourd’hui.','',26972),
(69439,'frFR','Mon peuple, qui a déjà traversé un grand nombre d’épreuves et subi moultes trahisons, se repose sur moi pour l’avenir.','',26972),
(69440,'frFR','Les Sin’dorei ont été poussés vers la Horde par le sectarisme et la méfiance de l’Alliance.','',26972),
(69441,'frFR','Mais aujourd’hui, je constate le même racisme chez notre chef de guerre. Il est prêt à sacrifier nos vies pour ses projets.','',26972),
(69442,'frFR','Je ne resterai pas oisif si les intérêts de la Horde entrent en conflit avec ceux de mon peuple. Je reconsidérerai peut-être d’anciennes alliances.','',26972),
(69443,'frFR','Gardez les yeux ouverts. Nous sommes tous dans le même bateau… pour l’instant.','',26972),
(69444,'frFR','Mon père ne demande pas au Kirin Tor de prêter allégeance à l’Alliance…','',26972),
(69445,'frFR','','Anduin, j’ai parfaitement compris ce qu’il demande. Oh… regardez qui voilà.',26972),
(69446,'frFR','','Personne ne déteste Garrosh autant que moi. Chaque jour, je ravale ma colère.',26972),
(69447,'frFR','','Venez avec moi et regardez autour de vous.',26972),
(69448,'frFR','','Après Theramore, ma première réaction a été de détruire Orgrimmar… de tuer chaque homme, femme et enfant de cette ville.',26972),
(69449,'frFR','','Je n’en suis pas fière. Depuis, nous avons longuement parlé de pouvoir avec Kalecgos, et de la façon dont il doit être utilisé.',26972),
(69450,'frFR','… Jaina !','',26972),
(69451,'frFR','','Plusieurs membres du Kirin Tor en ont déjà abusé. Kel’thuzad a perverti les Arcanes au service de la nécromancie.',26972),
(69452,'frFR','','Kael’thas Haut-Soleil a également étudié ici. Encore un des nôtres qui nous a trahis.',26972),
(69453,'frFR','','Anduin, vous savez mieux que quiconque qu’il faut distinguer la Horde des peuples qui la composent.',26972),
(69454,'frFR','','Chaque jour, je me demande quelle est la meilleure chose à faire.',26972),
(69455,'frFR','','Les Saccage-soleil œuvrent toujours dans cette ville. La Horde et l’Alliance collaborent.',26972),
(69456,'frFR','','Tant que nous évitons la guerre, il y a de l’espoir pour le reste du monde.',26972),
(69457,'frFR','','Cette ville doit être un phare qui montre la voie.',26972),
(69458,'frFR','','Si nous pouvons compter les uns sur les autres ici, alors il y a encore de l’espoir.',26972),
(69459,'frFR','','Cette ville doit être un phare qui montre la voie.',26972),
(69460,'frFR','','Si nous pouvons compter les uns sur les autres ici, alors il y a encore de l’espoir.',26972),
(69461,'frFR','','Merci, Anduin.',26972),
(69462,'frFR','Je comprends. Je parlerai à mon père.','',26972),
(69504,'frFR','Pendant des années, elle est resté latente, sa puissance augmentant peu à peu…','',26972),
(69505,'frFR','','C’est… c’est incroyable… une réserve d’énergie arcanique brute encore intacte.',26972),
(69506,'frFR','','Imaginez ce que nous pourrions invoquer ne serait-ce qu’avec une fraction de ce pouvoir !',26972),
(69507,'frFR','Invoquer… Ha, imaginez ce que nous pourrions devenir si nous fusionnions avec une telle puissance…','',26972),
(69508,'frFR','Les pouvoirs de cette pièce sont non sans rappeler le Puits d’éternité originel en Azeroth.','',26972),
(69509,'frFR','','C’est donc comme ça qu’Illidan a soumis tant de démons à sa volonté…',26972),
(69510,'frFR','Oui. En paiement de son service, le démon avait le droit d’absorber l’énergie de cet endroit.','',26972),
(69511,'frFR','En se nourrissant du pouvoir de ces lieux, ils étaient alors libérés de leur addiction à la magie de la Légion.','',26972),
(69512,'frFR','Je suppose que c’est la source de pouvoir originelle qu’il comptait offrir aux Elfes de sang pour les libérer de leur addiction au Puits de soleil… mais pour je ne sais quelle raison, il ne les a pas laissés s’en approcher…','',26972),
(69513,'frFR','','Quoi ?? Vous n’avez aucune preuve de ce que vous affirmez.',26972),
(69514,'frFR','Vous n’avez pas remarqué ? Les démons sous les ordres d’Illidan étaient libérés de toute forme de corruption entropique reconnaissable au vert gangrené qui pervertit habituellement la Légion.','',26972),
(69515,'frFR','','… pourquoi parlez-vous autant, Kanrethad ?',26972),
(69516,'frFR','J’y étais… à la fin…','',26972),
(69519,'frFR','','… oh non, vous n’allez pas encore me raconter l’une de vos horribles histoires ?',26972),
(69520,'frFR','… silence.','',26972),
(69522,'frFR','Je crois que je préférais quand vous n’aviez plus votre mâchoire.','',26972),
(69523,'frFR','','Avez-vous entendu ça ?! Ces chiens galeux cendrelangues reviennent. Dépêchons-nous de faire le rituel !',26972),
(69524,'frFR','Très bien. Nous reviendrons plus tard, quand le cristal sera complètement chargé.','',26972),
(69558,'frFR','Ton ingérence m’a coûté un grand guerrier, jeune prince. Tu vas le payer de ta vie.','',26972),
(69559,'frFR','C’est là que vous avez tort, Garrosh.','',26972),
(69560,'frFR','Crève, morveux !!','',26972),
(69561,'frFR','Les mogu ont créé la Cloche divine pour semer le chaos, mais les Pandarens ont fabriqué un maillet unique pour transformer les échos de ce chaos en parfaite harmonie. Le maillet est resté caché pendant des années, jusqu’à aujourd’hui.','',26972),
(69562,'frFR','Je ne vous laisserai pas faire, Garrosh. Vous, passez-moi le maillet !','',26972),
(69619,'frFR','Jaina ! Qu’est-ce qui se passe à Dalaran ? La ville a été attaquée ?','',26972),
(69620,'frFR','','Le Kirin Tor a été trahi de l’intérieur. Je m’en suis occupée.',26972),
(69621,'frFR','Comment ?','',26972),
(69622,'frFR','','J’ai expulsé la Horde de Dalaran. Vous avez obtenu gain de cause, votre majesté : le Kirin Tor appartient à l’Alliance.',26972),
(69623,'frFR','','Je sais ce que j’avais dit. Ma confiance a été bafouée.',26972),
(69624,'frFR','Mais vous aviez dit…','',26972),
(69625,'frFR','Qu’en est-il des Sin’dorei, les Saccage-soleil ?','',26972),
(69626,'frFR','','Ceux qui se sont rendus ont été envoyés au fort Pourpre. Je ne peux rien garantir pour ceux qui ont choisi de se battre.',26972),
(69627,'frFR','Jaina, vous devez en parler avec moi avant d’agir…','',26972),
(69628,'frFR','','Ma façon de diriger le Kirin Tor ne vous concerne pas.',26972),
(69629,'frFR','Je tentais de négocier avec les Sin’dorei. J’avais engagé des pourparlers pour les rallier à l’Alliance ! En attaquant leur peuple, vous leur avez forcé la main…','',26972),
(69630,'frFR','','Ils ont choisi leur propre voie.',26972),
(69631,'frFR','Vous les avez renvoyés vers la Horde.','',26972),
(69632,'frFR','','Vous vous leurrez. Dans la Horde un jour, dans la Horde toujours. Je rassemble le Kirin Tor.',26972),
(69633,'frFR','Jaina. Nous devons œuvrer ensemble. L’Alliance doit s’unir.','',26972),
(69634,'frFR','','Ne tentez pas de m’amadouer, Varian.',26972),
(69637,'frFR','Garrosh a attaqué mon fils… ? Où est-il ?','',26972),
(69638,'frFR','','Anduin !',26972),
(69639,'frFR','Anduin, à quoi pensais-tu ? J’aurais dû te renvoyer à Hurlevent !','',26972),
(69640,'frFR','Il est vivant. Mais ses os sont complètement brisés.','',26972),
(69641,'frFR','Allez chercher Velen. Qu’il vienne immédiatement !','',26972),
(69642,'frFR','Aethas ! Vous êtes en vie !','',26972),
(69643,'frFR','Grâce à cette personne, certains ont pu s’en sortir. Mais de nombreux autres ont été emmenés au fort Pourpre.','',26972),
(69644,'frFR','Anar’alash denal ! Est-ce que quelqu’un va me dire ce qui se passe à Dalaran ?','',26972),
(69645,'frFR','C’est Portvaillant ! Elle a expulsé les Saccage-soleil de la ville. Elle nettoie le Kirin Tor de tout membre de la Horde !','',26972),
(69646,'frFR','Elle est allée trop loin. Je parie que les mages de guerre de l’Alliance circulent librement. Satanée sorcière !','',26972),
(69647,'frFR','Quand comprendront-ils que la Horde existe À CAUSE de l’Alliance ?! À cause de leurs préjugés et de leur sectarisme ! Ils nous poussent encore un peu plus vers la Horde de Hurlenfer.','',26972),
(69648,'frFR','Mon seigneur…','',26972),
(69649,'frFR','Hal’duron, convoquez les forestiers. Rommath, rassemblez les mages de sang et joignez les troupes de Saccage-soleil aux vôtres.','',26972),
(69650,'frFR','Les Sin’dorei vont prendre leur avenir en main.','',26972),
(69651,'frFR','Et éloignez ça de ma vue ! Hurlenfer s’est emparé de son trésor en faisant couler le sang des miens. J’espère qu’il en mourra.','',26972),
(69652,'frFR','Mon seigneur. Vous feriez un parfait chef de guerre.','',26972),
(69653,'frFR','Mon seigneur. Vous feriez un parfait chef de guerre.','',26972),
(69654,'frFR','L’avenir nous le dira. Apportez mes lames. C’est à mon tour de jouer.','',26972),
(69686,'frFR','Est-ce qu’on en a fini avec les préparatifs ?','',26972),
(69687,'frFR','Oui, seigneur de guerre. Les pièges sont prêts. La Cloche divine sera en sécurité dans la crypte, jusqu’au retour du roi-tonnerre.','',26972),
(69688,'frFR','Nous n’avons plus qu’à évacuer les ouvriers et le reste de nos guerriers.','',26972),
(69689,'frFR','Très bien. Que les fantômes de nos frères gardent ces lieux pour l’éternité.','',26972),
(69690,'frFR','Nous n’avons pas le temps. Les pisteurs pandashan sont trop proches. Ils doivent pas savoir où est la cloche.','',26972),
(69691,'frFR','Ils ne seront pas morts pour rien.','',26972),
(69692,'frFR','Et vous non plus, Avartu.','',26972),
(69809,'frFR','Provocateurs de chaos… Invocateurs de démons… Brandisseurs d’ombres…','',26972),
(69811,'frFR','L’existence de votre caste ne nous a pas échappé, $c.','',26972),
(69812,'frFR','Tout comme Illidan, vous faites tout votre possible pour plier le chaos qui dévore tout à votre volonté.','',26972),
(69813,'frFR','Vous êtes à la frontière entre le pouvoir absolu et la corruption totale.','',26972),
(69815,'frFR','Tout comme Azeroth combattit la Légion et survécut, vous avez affronté les ténèbres qui vous hantent et avez réussi à les maîtriser.','',26972),
(69816,'frFR','Peut-être réussirez-vous là où Illidan a échoué… peut-être arriverez-vous à accepter le chaos de cet univers.','',26972),
(69818,'frFR','Votre peuple peut marcher là où cela nous est impossible. Il peut survivre là où d’autres périraient.','',26972),
(69819,'frFR','L’artéfact que Kanrethad a tenté de créer est incomplet.','',26972),
(69820,'frFR','Il donne la possibilité de lancer des sorts à très grande échelle… Mais le sorcier qui l’utilise perd rapidement le contrôle de toute cette puissance.','',26972),
(69822,'frFR','Je libérerai le pouvoir du cristal, mais vous $gseul:seule; pouvez décider comment l’utiliser.','',26972),
(69823,'frFR','Choisissez avec sagesse, $n.','',26972),
(70156,'frFR','Une cloche moulée dans la chair des faiseurs, sculptée dans le feu des étoiles et liée par le souffle de l’ombre la plus dense.','',26972),
(70157,'frFR','Quand l’airain résonnait, le monde tremblait et les cieux intervenaient.','',26972),
(70158,'frFR','En temps de guerre, la cacophonie de la cloche exaltait les guerriers de Lei Shen.','',26972),
(70159,'frFR','Elles emplissaient leur cœur de haine et de colère, leur conférant leur force sur le champ de bataille.','',26972),
(70160,'frFR','Les hurlements de la cloche insufflaient peur et doute dans le cœur des ennemis de l’empereur et les faisaient fuir.','',26972),
(70161,'frFR','Admiratif de sa puissance, le roi-tonnerre surnomma l’airain « la voix des dieux » et lui donna le nom de Cloche divine.','',26972),
(70162,'frFR','Mais le roi-tonnerre finit par tomber, et la Cloche changea de mains. Nombreux tentèrent de l’utiliser. Certains tentèrent de la réduire au silence. Tous échouèrent.','',26972),
(70163,'frFR','Finalement, les tisse-sorts korunes vinrent réclamer leur airain et le mirent à l’abri. Depuis, la Cloche n’est plus qu’une légende.','',26972),
(70184,'frFR','Eh les lokdus, je suis de retoooooouuuuur !','',26972),
(70261,'frFR','Il ne faut pas se fier aux apparences, Tyrande. Et mon fils affirme que c’est un lieu sacré.','',26972),
(70262,'frFR','Ils défendent une position fixe. Je ne rentrerai pas dans leur jeu. Nous allons les attirer à l’extérieur.','',26972),
(70299,'frFR','','Ils sont acculés dans le temple. Nous devons frapper tout de suite !',26972),
(70300,'frFR','','Raison de plus pour le purifier.',26972),
(70301,'frFR','','Vous perdez un temps précieux.',26972),
(70329,'frFR','Tong ! Apportez-moi à manger.','',26972),
(70330,'frFR','Le haut roi. Varian Wrynn, dirigeant de l’Alliance.','',26972),
(70331,'frFR','Vous saviez qu’il avait été gladiateur ? J’ai fait ma petite enquête.','',26972),
(70332,'frFR','Souffrant d’amnésie, il a combattu pour sa vie dans des arènes de la Horde.','',26972),
(70333,'frFR','Il y a gagné le nom de « Lo’Gosh », le « loup fantôme ».','',26972),
(70334,'frFR','C’est un combattant. Mais a-t-il l’étoffe d’un chef ?','',26972),
(70335,'frFR','Pensez-y ! Ses ennemis ont tiré avantage du Cataclysme provoqué par mon père.','',26972),
(70336,'frFR','Les soldats de la Horde ont balayé le royaume dans le sillage de la dévastation.','',26972),
(70337,'frFR','Varian Wrynn n’a pas utilisé ce désastre pour prendre l’avantage militaire.','',26972),
(70338,'frFR','Est-ce parce qu’il est faible…? Ou parce qu’il a des principes ?','',26972),
(70339,'frFR','D’où cette grande question : peut-on gagner une guerre avec des principes ?','',26972),
(70340,'frFR','Ne vous y trompez pas. La Pandarie mettra votre roi au défi.','',26972),
(70341,'frFR','Voyons ce dont il est vraiment capable.','',26972),
(70342,'frFR','Voyons si votre Alliance a l’étoffe pour gouverner Azeroth.','',26972),
(70343,'frFR','Garrosh Hurlenfer ! Chef de guerre de la Horde.','',26972),
(70344,'frFR','Il n’a pas toujours eu de si grands pouvoirs.','',26972),
(70345,'frFR','Sur Draenor, ce n’était qu’un pauvre hère tourmenté par les agissements de son père.','',26972),
(70346,'frFR','Je vous comprends, Garrosh. Je sais ce que c’est de vivre avec le poids des actes de son père.','',26972),
(70347,'frFR','Les guerriers comme Garrosh arrivent au pouvoir en ayant quelque chose à prouver.','',26972),
(70348,'frFR','Votre Horde vit un tournant majeur. Cette guerre définira qui vous êtes.','',26972),
(70349,'frFR','Qu’est-ce que la Horde ?','',26972),
(70350,'frFR','Un instrument de vengeance, voulant à tout prix forger un avenir pour son peuple ?','',26972),
(70351,'frFR','Un refuge pour ceux qui en ont besoin, une communauté d’opprimés rassemblés pour se soutenir mutuellement ?','',26972),
(70352,'frFR','Ou est-ce une alliance opportune, une association de partenaires mal assortis poursuivant des objectifs individuels ?','',26972),
(70353,'frFR','Voici ma question : qu’est-ce qui constitue l’ÂME de la Horde ?','',26972),
(70354,'frFR','C’est ici, en Pandarie, que nous trouverons les réponses.','',26972),
(70355,'frFR','Montrez-moi ce dont votre Horde est capable !','',26972),
(70356,'frFR','Prouvez-moi que votre Horde est digne de régner sur Azeroth.','',26972),
(70357,'frFR','Vous avez fait preuve d’un comportement exemplaire. Vous faites honneur à votre cause.','',26972),
(70358,'frFR','Vous rappelez-vous de notre précédente discussion ?','',26972),
(70359,'frFR','Nous avons discuté des mérites de votre haut roi. Je l’ai observé attentivement.','',26972),
(70360,'frFR','C’est vrai. Il possède l’esprit du loup. Il combat comme tel.','',26972),
(70361,'frFR','Je l’ai vu en action, et je sais maintenant ce que cela signifie.','',26972),
(70362,'frFR','Les loups sont des animaux de meute.','',26972),
(70363,'frFR','Votre roi appelle sa meute à lui, il rassemble l’Alliance dans le sens le plus pur de ce terme.','',26972),
(70364,'frFR','Son voyage sera long. Il vient à peine de l’entreprendre.','',26972),
(70365,'frFR','Mais avec des héros tels que vous dans sa meute, presque rien n’est impossible à l’Alliance.','',26972),
(70366,'frFR','Tong, rassemblez mes affaires !','',26972),
(70367,'frFR','Votre dévouement à votre cause mérite d’être récompensé.','',26972),
(70368,'frFR','Tout comme vous, je continue de peaufiner mes arts en Pandarie. Je pense que vous apprécierez le résultat.','',26972),
(70369,'frFR','Choisissez une récompense !','',26972),
(70370,'frFR','Restez à l’affut. Le retour du roi-tonnerre est tout autant une menace… qu’une opportunité !','',26972),
(70371,'frFR','Vous avez fait preuve d’un comportement exemplaire. Vous faites honneur à votre cause.','',26972),
(70372,'frFR','Vous rappelez-vous de notre précédente discussion ?','',26972),
(70373,'frFR','Nous avons discuté de votre chef de guerre, de ses conflits intérieurs et de ses conquêtes.','',26972),
(70374,'frFR','Je vous ai demandé ce qui constituait l’âme de la Horde.','',26972),
(70375,'frFR','Vos actes sur les rives australes et dans toute la Pandarie m’ont apporté la réponse.','',26972),
(70376,'frFR','C’est VOUS qui en êtes l’âme.','',26972),
(70377,'frFR','Vos actions dans les prochaines semaines feront de votre peuple ce qu’il est.','',26972),
(70378,'frFR','Je veux m’assurer que vous ayez l’équipement approprié aux épreuves qui vous attendent.','',26972),
(70379,'frFR','Content de vous revoir ! Comment se déroule le combat le long des côtes ?','',26972),
(70380,'frFR','L’avez-vous tué ? Garde-Sanglante servait dans les Tarides du Sud. Vous avez vengé un grand nombre de vies, aujourd’hui.','',26972),
(70381,'frFR','Content de vous revoir ! Comment se déroule le combat le long des côtes ?','',26972),
(70382,'frFR','Alors, le général Doublenattes est mort ? Il a joué un rôle majeur dans l’offensive de l’Alliance dans les Tarides du Sud. Impressionnant.','',26972),
(70409,'frFR','Y’avait une fois un pikk maillet sacré, brillant comme un miroir.','',26972),
(70410,'frFR','Mais la douk de cloche qu’allait avec, jamais je pouvais l’avoir.','',26972),
(70411,'frFR','Les mogu l’avaient volé, contre ça qu’est-ce qu’un hozen peut y faire ?','',26972),
(70412,'frFR','Vise le drame si ces doukacques volaient aussi le maillet, l’enfer.','',26972),
(70413,'frFR','Mais les mogu, pour voir la nature des trucs ils sont un peu miros.','',26972),
(70414,'frFR','Alors le roi-singe a cassé le maillet et bazardé les morceaux.','',26972),
(70415,'frFR','Mes hozen ils les ont pris, pour les planquer un peu partout.','',26972),
(70416,'frFR','Déguisés en « chouettes pucs », et pour les mogu : des clous.','',26972),
(70417,'frFR','La tête et puis le manche, ceux-là faut qu’on les rabiboche.','',26972),
(70418,'frFR','Avec le maléfice de l’onguent, pour défaire le mal de la cloche.','',26972),
(70419,'frFR','Si ce « Garrosh » a la cloche, alors faut arrêter le caquetage,','',26972),
(70420,'frFR','Je vais appeler mes hozen, le maillet faut en faire le montage.','',26972),
(70716,'frFR','Bon, voilà. Mes recherches ont révélé que ce seigneur de guerre de jade n’était pas un enfant de cœur. Soyez prêts à l’affronter.','',26972),
(70824,'frFR','Commençons.','',26972),
(70825,'frFR','Vous n’aviez aucune chance.','',26972),
(70826,'frFR','Quoi ? Comment est-ce possible ?','',26972),
(70827,'frFR','Donnons à quelqu’un d’autre une chance de faire des dégâts !','',26972),
(70828,'frFR','Vous pensiez vraiment que toutes vos mascottes survivraient ?','',26972),
(70829,'frFR','Non ! C’était ma mascotte préférée !','',26972),
(71016,'frFR','','Mon roi, je vous en fais le serment. Le Kirin Tor va faire payer Garrosh. Même ses ancêtres en trembleront. Le sang appelle le sang !',26972),
(71017,'frFR','Jaina…','',26972),
(71018,'frFR','Je vais anéantir Garrosh pour ce qu’il a fait. La Horde se désagrège. Nous allons lui porter le coup final.','',26972),
(71019,'frFR','Vous et Anduin avez contrecarré les plans du chef de guerre, et vous avez permis à l’Alliance de remporter une grande victoire.','',26972),
(71020,'frFR','Laissez-moi, maintenant. Je dois soigner mon fils… et préparer notre prochaine bataille.','',26972),
(71043,'frFR','Très bien, nous avons la poignée, la tête et la pommade que vous avez demandées. Pouvez-vous reconstituer le maillet ?','',26972),
(71044,'frFR','Ouip ! Mets le manche dans le trou, jeune écervelé. Et le maillet sera à nouveau entier.','',26972),
(71045,'frFR','Propre comme un nouveau sou ! Mais écoutez bien le roi-singe, pauvres fous. Vous n’avez de pommade que pour un coup.','',26972),
(71046,'frFR','Un seul coup ? Est-on sûr que ça suffira ? Il n’y a pas un moyen d’obtenir plus de pommade ?','',26972),
(71047,'frFR','Le roi-singe était là, quand le maillet a frappé juste pour la dernière fois. Il en a eu les larmes aux yeux, et l’harmonie a rempli la terre et les cieux. Mais plus jamais de pommade ne fut faite, car les mogu lancèrent leur raid. Utilisez ce que vous avez et contentez-vous-en. Car la cloche est bien dangereuse, donc soyez prudents.','',26972),
(71301,'frFR','Je n’aurais aucune pitié !','',26972),
(71737,'frFR','','Les charges sont en place, à vous l’honneur.',26972),
(71782,'frFR','Les indignes n’ont pas encore connaissance de ma puissance.','',26972),
(71783,'frFR','Dieu-guerrier Al’chukla, je joins ma force à la vôtre.','',26972),
(71798,'frFR','Faites de ces envahisseurs un exemple, que toutes les nations tremblent devant moi !','',26972),
(71799,'frFR','Tous tomberont devant nous !!','',26972),
(71800,'frFR','Shan Bu, sécurisez la cour intérieure. Quiconque entrevoit mon chantier doit mourir.','',26972),
(71801,'frFR','Il en sera fait selon votre volonté.','',26972),
(72052,'frFR','Mon seigneur.','',26972),
(72096,'frFR','On raconte que le dieu-roi Rastakhan, chef des Zandalari, régnait sur son puissant royaume depuis son trône sculpté dans l’or massif. ','',26972),
(72097,'frFR','Il y a plusieurs années, alors qu’il siégeait en ce haut lieu de puissance, il reçut la visite du sombre prophète Zul.','',26972),
(72098,'frFR','Zul avertit le roi Rastakhan d’un terrible cataclysme. Car Zul avait eu la vision d’un grand dragon cuirassé tenant le monde dans sa mâchoire cruelle.','',26972),
(72099,'frFR','Le roi Rastakhan ne fit rien.','',26972),
(72100,'frFR','Zul revint quelques mois plus tard, apportant de nouvelles visions encore plus sombres. Il avait vu une fissure béante s’ouvrir au fond de l’océan et déverser une légion de serpents.','',26972),
(72101,'frFR','Et pourtant, le roi Rastakhan ne fit rien.','',26972),
(72102,'frFR','Puis, quelques mois avant le cataclysme, Zul réapparut. Déchirant ses vêtements et jetant son bâton au sol, Zul fit allusion à de terribles séismes et raz de marée.','',26972),
(72103,'frFR','Il décrivit le lent engloutissement de la capitale dorée de Zandalar sous les eaux du cataclysme, son peuple prestigieux noyé, alors que la mer submergeait leurs œuvres grandioses à tout jamais.','',26972),
(72104,'frFR','Le roi Rastakhan se lassa de Zul et de ses cauchemars inquiétants. Afin de se débarrasser du prophète, il l’autorisa à utiliser ses plus grands navires : si ses visions se vérifiaient, ses disciples et lui pourraient alors chercher un nouvel asile.','',26972),
(72105,'frFR','Et ses visions se vérifièrent BEL ET BIEN.','',26972),
(72106,'frFR','Lorsqu’Aile de mort surgit du maëlstrom, des vagues sombres et vengeresses submergèrent la capitale des Zandalari. La terre s’ouvrit en deux, et la ville et toutes ses richesses commencèrent à plonger dans la mer avide.','',26972),
(72107,'frFR','Désespérés, les Zandalari se tournèrent vers leur roi, mais une seule personne était en mesure de les aider : le prophète Zul. Le prophète, ainsi que la puissante flotte qu’il avait réunie alors que son roi demeurait impassible.','',26972),
(72108,'frFR','Vous voyez, le VÉRITABLE pouvoir des rois et des empereurs réside dans leur capacité à aider leur peuple.','',26972),
(72109,'frFR','À partir du moment où ils échouent, ils cèdent leur pouvoir à la personne qui en est capable.','',26972),
(72110,'frFR','Une légende mogu parle de Lei Shen, le roi-tonnerre.','',26972),
(72111,'frFR','Ses sujets tombèrent à genoux devant lui et lui dirent : « Nous vous appellerons le roi-éclair ».','',26972),
(72112,'frFR','Elle dit qu’il arracha le cœur du dieu des mogu et que cet acte ignoble lui donna le pouvoir de commander aux vents et aux tempêtes.','',26972),
(72113,'frFR','Mais Lei Shen refusa.','',26972),
(72114,'frFR','« L’éclair frappe en un instant et disparaît aussitôt », dit-il.','',26972),
(72115,'frFR','« Mais le tonnerre… Le tonnerre ! Il annonce l’arrivée de la tempête. »','',26972),
(72116,'frFR','« Le tonnerre gronde dans le ciel bien avant que l’éclair frappe, et résonne dans les collines bien après que l’éclair s’est évanoui. »','',26972),
(72117,'frFR','« C’est le tonnerre qui terrorise les animaux et sème l’effroi dans le cœur des paysans. Qu’il soit mon héraut et annonce ma puissance sur ces terres. »','',26972),
(72118,'frFR','« Je serai… le roi-tonnerre. »','',26972),
(72119,'frFR','Oh, quel fracas effrayant. Génération après génération, le grondement du tonnerre terrorisa tous les Pandarens pendant des millénaires.','',26972),
(72120,'frFR','On dit qu’après la révolution, la grue rouge de l’espoir plaça un arc-en-ciel au-dessus des Pandarens pour qu’ils apprennent à ne plus craindre l’orage.','',26972),
(72121,'frFR','Je ne vois aucun arc-en-ciel aujourd’hui, et vous ?','',26972),
(72122,'frFR','De père en fils, de mère en fille. En tant que parents, nous transmettons un héritage à nos enfants.','',26972),
(72123,'frFR','Quelles valeurs décidons-nous d’inculquer à notre progéniture ?','',26972),
(72124,'frFR','Qu’apprendront nos enfants de nos propres erreurs ?','',26972),
(72125,'frFR','Quel monde souhaitons-nous créer et transmettre à nos fils et à nos filles ?','',26972),
(72126,'frFR','Les parents placent leurs enfants sur un chemin, mais ils ne savent pas toujours où il va les mener.','',26972),
(72127,'frFR','Les mogu étaient aussi des enfants. Ceux des titans. Ils furent jadis une armée de pierre, insensibles et dociles.','',26972),
(72128,'frFR','Sur ordre des titans, ils combattirent les terribles serviteurs des Dieux très anciens. Ils érigèrent les montagnes et creusèrent le lit des rivières.','',26972),
(72129,'frFR','Et ils façonnèrent un creuset de vie magique, dans une vallée cachée que nous appelons aujourd’hui le val de l’Éternel printemps.','',26972),
(72130,'frFR','Mais les titans finirent par tomber dans l’oubli. Et leurs créations furent frappées de la malédiction de la chair.','',26972),
(72131,'frFR','La rancœur s’amplifia chez les mogu. Bien des générations plus tard, quand le roi-tonnerre les unifia, ils reprirent leur œuvre !','',26972),
(72132,'frFR','Aujourd’hui, je suis convaincu que les mogu croyaient poursuivre l’entreprise des titans. Ils combattirent les mantides et utilisèrent les pouvoirs du val pour créer la vie.','',26972),
(72133,'frFR','Ah, mais quelles créations terrifiantes ! ','',26972),
(72134,'frFR','Les parents ne sont jamais certains de l’héritage qu’ils laisseront derrière eux.','',26972),
(72135,'frFR','Et c’est d’autant plus vrai quand les parents sont des dieux et leurs enfants, des monstres.','',26972),
(72306,'frFR','Détruisez-les, mes frères !','',26972),
(72311,'frFR','Le roi-tonnerre ! Quel individu grandiose.','',26972),
(72312,'frFR','Vous imaginez ce que serait devenu cet empire s’il n’avait pas été renversé et caché à la vue de tous par les Pandarens ?','',26972),
(72313,'frFR','Je ne peux imaginer tyran plus cruel. Il a asservi un continent tout entier.','',26972),
(72314,'frFR','La bienveillance est un luxe pour les forts, jeune prince. Aucun grand empire ne s’est construit avec bonté.','',26972),
(72315,'frFR','…Je n’en suis pas aussi sûr. Mais ce dont je suis certain, c’est qu’aucun grand empire n’a survécu à l’épreuve du temps en écrasant ses citoyens.','',26972),
(72316,'frFR','Les mogu ont été renversés, après tout ! C’est ÇA que devrait retenir le roi-tonnerre. Au fait, c’est à vous de jouer.','',26972),
(72317,'frFR','J’ai peur que vous soyez trop sensible pour porter votre couronne, prince Anduin. Vous devriez prendre exemple sur la fermeté de votre père.','',26972),
(72318,'frFR','Est-ce que vous me faites la leçon ? Vous avez quoi… deux ans ?','',26972),
(72319,'frFR','Deux ans de dragon. C’est à vous.','',26972),
(72320,'frFR','Hmmm.','',26972),
(72321,'frFR','…Pourquoi avoir joué cette pièce ?','',26972),
(72322,'frFR','C’est un jeu de plateau pandaren. Pour remplir l’objectif, les deux joueurs doivent gagner la partie.','',26972),
(72323,'frFR','Mais c’est ridicule ! Quel est l’intérêt de jouer, alors ?!','',26972),
(72324,'frFR','Retournez sur l’île du Tonnerre. Je vous retrouverai à la forge, nous y créerons un instrument d’une puissance légendaire.','',26972),
(72325,'frFR','Dans quel but ? Qu’est-ce que vous manigancez, tous les deux ?','',26972),
(72326,'frFR','… La paix dans le monde !','',26972),
(72327,'frFR','À l’aide d’une forge pour armes mogu dont vous ne comprenez pas les pouvoirs ?','',26972),
(72328,'frFR','Mon cher prince, vous et moi partageons les mêmes buts. Seul notre dévouement diffère.','',26972),
(72329,'frFR','Venez ! Forgeons la nouvelle Azeroth ensemble !','',26972),
(72330,'frFR','Je sais que nous sommes ennemis, mais si vous suivez aveuglément un dragon noir dans votre quête de puissance, vaudrez-vous mieux que votre chef de guerre ? Faites attention.','',26972),
(72331,'frFR','Mon $gami:amie;, si vous suivez aveuglément un dragon noir en quête d’une grande puissance, vaudrez-vous mieux que Garrosh Hurlenfer ? Agissez prudemment.','',26972),
(72332,'frFR','Tong, est-ce notre ami ?','',26972),
(72333,'frFR','Je n’arrive pas à croire que vous êtes en vie.','',26972),
(72334,'frFR','Rappelez-moi de vous raconter ce que notre ami et moi avons accompli ensemble à Ravenholdt. Un bon moment !','',26972),
(72335,'frFR','Qu’est-ce que je vous avais dit ? Peu de mortels ont ce courage et cette ténacité.','',26972),
(72336,'frFR','Retrouvez-moi comme l’autre fois au sommet de la Folie du maçon !','',26972),
(72337,'frFR','Qu’êtes-vous en train de comploter ?','',26972),
(72338,'frFR','Je n’ai aucun secret ! Vous pouvez nous accompagner, Anduin. Si votre blessure vous le permet.','',26972),
(72339,'frFR','Je prie notre ami de la Horde de ne pas vous pousser du haut de la falaise.','',26972),
(72340,'frFR','Quelle splendeur ! Avez-vous déjà vu pareil panorama, prince Anduin ?','',26972),
(72341,'frFR','C’est époustouflant.','',26972),
(72342,'frFR','Et vous n’avez pas tout vu.','',26972),
(72343,'frFR','Contemplez le fruit de votre labeur !','',26972),
(72344,'frFR','À l’aube du monde, les races mortelles étaient encore jeunes, elles ne possédaient pas le secret du feu.','',26972),
(72345,'frFR','Elles tremblaient dans le froid, sous la pluie, quand soudain, un éclair déchira le ciel !','',26972),
(72346,'frFR','Il fendit un arbre en deux et l’embrasa.','',26972),
(72347,'frFR','Les mortels se regroupèrent autour du feu, émerveillés. Le feu cuisait leur nourriture, réchauffait leurs foyers. Ils s’en emparèrent ! Le protégèrent !','',26972),
(72348,'frFR','Le feu était nourri jour et nuit. Les braises étaient transmises d’un camp primitif à l’autre. Vous comprenez ? La civilisation est née dans un éclair de lumière.','',26972),
(72349,'frFR','Les éclairs sont de véritables dons des dieux.','',26972),
(72350,'frFR','Les mogu, ah ! Les mogu ! Leur esprit était si étriqué ! Ils ont été conçus pour servir, et lorsqu’ils perdirent leurs maîtres, ils se servirent eux-mêmes.','',26972),
(72351,'frFR','Mais ils auraient pu devenir tellement plus.','',26972),
(72352,'frFR','Ils bâtirent un empire, quand ils auraient pu concevoir un nouveau monde.','',26972),
(72353,'frFR','NOUS ferons mieux. Regardez ! La Couronne des cieux ! C’est mon cadeau pour vous.','',26972),
(72354,'frFR','Vous êtes la braise. Vous êtes l’étincelle ! Vous êtes le feu qui va se répandre dans le monde. VOUS allez révéler le potentiel d’Azeroth !','',26972),
(72355,'frFR','Venez à moi.','',26972),
(72356,'frFR','Nous savons maintenant que les mogu sont liés aux titans. Mais de nombreux mystères demeurent. Pourquoi étaient-ils ici ? Pourquoi en Pandarie ?','',26972),
(72357,'frFR','Que devaient garder les mogu ? Ou que devaient-ils détruire ? Il nous manque les dernières pièces du puzzle. Mais vous allez m’aider à les découvrir !','',26972),
(72358,'frFR','Cette couronne sera comme un troisième œil. Elle nous reliera et je verrai par vos yeux. Ensemble, nous dévoilerons les secrets des titans.','',26972),
(72359,'frFR','Je vous observerai avec attention ! ','',26972),
(72360,'frFR','À votre place, j’hésiterais à me mettre cette chose sur la tête.','',26972),
(72361,'frFR','Selon cette rune, les mogu étaient des assemblages des titans, des créatures sans âme faites de pierre. Nous le supposions déjà.','',26972),
(72362,'frFR','Une autre pierre ! Qu’avons-nous appris ? La « malédiction de la chair » rendit les mogu mortels. Ah… mais plus tard, ils découvrirent un moyen d’inverser le processus. Une race intelligente.','',26972),
(72363,'frFR','Les mogu servaient un gardien titan. Son nom était « Ra ». En langue mogu, « Ra Den » signifie « Maître Ra ». Fascinant ! Je dois en apprendre plus !','',26972),
(72364,'frFR','Selon cette inscription, les mogu et leur maître furent envoyés en Pandarie. Ils poursuivaient de grandes ténèbres… ah, le fragment est incomplet. Nous devons trouver les autres.','',26972),
(72365,'frFR','Ici, il est fait mention d’un Dieu très ancien, « Y’Shaarj ». Une bête à sept têtes, qui insufflait les ténèbres. Je suppose que c’est ce qui est à l’origine des sha qui hantent la Pandarie aujourd’hui.','',26972),
(72366,'frFR','La rune parle d’un « berceau de la vie ». Un endroit où les titans pouvaient créer de nouvelles créatures. Mais bien sûr. Le val de l’Éternel printemps ! C’était un laboratoire, à la manière du cratère d’Un’goro et du bassin de Sholazar.','',26972),
(72367,'frFR','Les pièces du puzzle commencent à s’assembler. Les mogu ont été créés pour garder le val pour les titans. Mais le garder de quoi ? Les Dieux très anciens étaient-ils encore une menace ?','',26972),
(72368,'frFR','Là, le fragment parle des « légions ailées d’Y’Shaarj ». Des serviteurs d’un Dieu très ancien ? Est-ce qu’il parle des mantides ?','',26972),
(72369,'frFR','Cette rune est plus récente que les autres. Elle parle d’un « gardien endormi ». Je suppose qu’elle parle de Ra-Den. Mais pourquoi dormait-il ?','',26972),
(72370,'frFR','Une autre pièce du puzzle ! Elle a été gravée par les mogu. Ils étaient frustrés : mille ans sans ordres de leurs maîtres et leurs corps étaient devenus de chair. Les mogu ont commencé à se disputer les uns les autres.','',26972),
(72371,'frFR','Hmmm. Cette rune parle de la sauvagerie des mogu. Ils se sont séparés en clans. Mais l’un des rois était plus ambitieux que les autres. Lei Shen. Le roi-tonnerre. Lorsque le gardien titan plongea dans le silence, Lei Shen décida de parler en son nom.','',26972),
(72372,'frFR','Ah ! La pièce finale du puzzle. Le roi-tonnerre s’empara des pouvoirs de Ra-Den, de l’essence même des titans. Il unifia les mogu en un empire et tenta de poursuivre l’œuvre des titans. Il se prenait évidemment pour un dieu !','',26972),
(72373,'frFR','Vite, revenez me voir à l’escalier Dérobé. Nous devons discuter face à face.','',26972),
(72374,'frFR','J’attendais votre retour avec impatience.','',26972),
(72375,'frFR','Le roi-tonnerre s’est imprégné des pouvoirs d’un gardien titan. Nous devons les lui reprendre !','',26972),
(72376,'frFR','Apportez-moi son cœur noir et cruel. Nous ferons une fleur aux Pandarens, et les pouvoirs libérés seront de nouveau au service d’Azeroth.','',26972),
(72377,'frFR','J’en ai des frissons dans le dos !','',26972),
(72378,'frFR','Quelque chose me dit que notre camarade a triomphé.','',26972),
(72379,'frFR','Ahhh, le cœur du roi. Les pouvoirs d’un dieu.','',26972),
(72380,'frFR','Que faites-vous ? Vous ne pensez sérieusement pas à manger ce…','',26972),
(72381,'frFR','Il est rempli de la magie des titans, le langage même de la création…','',26972),
(72382,'frFR','Ah, je les vois… un million de mondes, qui scintillent, parfaits, mais il y en a un au-dessus des autres… oh…','',26972),
(72383,'frFR','OOH… NOUS SOMMES TOMBÉS. NOUS DEVONS REFORMER LE DERNIER TITAN. N’OUBLIEZ PAS.','',26972),
(72384,'frFR','Qu’essayez-vous d’attirer ?','',26972),
(72385,'frFR','C’est fini. Je ne me souviens de rien. Oh ! Aucun ne s’en souvient. Quelle ironie !','',26972),
(72386,'frFR','De quoi parlez-vous ? Je ne vous fais pas confiance.','',26972),
(72387,'frFR','Et vous avez bien raison.','',26972),
(72388,'frFR','J’ai besoin de… « digérer » ce que je viens d’apprendre. Mais nous agirons bientôt.','',26972),
(72417,'frFR','Content de vous revoir. Nous allons pouvoir commencer ?','',26972),
(72418,'frFR','Allons-y !','Allons-y !',26972),
(72419,'frFR','Merci de votre intervention. Nous allons vous aider de notre mieux à combattre les mogu.','',26972),
(72451,'frFR','','NON !',26972),
(72452,'frFR','Contemplez ma puissance ! Je suis parvenu à maîtriser les énergies gangrenées de ce monde ! Mon pouvoir démoniaque est indicible, illimité… OMNIPOTENT !','',26972),
(72453,'frFR','Vous croyez que j’ai été trop loin ? Certainement pas… La Moisson noire va réduire en esclavage les plus puissants d’entre les démons, drainer leurs forces et réduire nos adversaires à néant, que ce soit ici ou à la surface d’Azeroth ! Vous croyez pouvoir m’arrêter, misérable petite chose ?','',26972),
(72455,'frFR','Ma puissance défie l’imagination !','',26972),
(72456,'frFR','Ha… vos attaques sont au mieux… divertissantes. Voulez-vous que je vous présente l’un de mes nouveaux familiers ?','',26972),
(72457,'frFR','J’aimerais vous voir tenter votre chance.','',26972),
(72458,'frFR','Les Annihiléens sont des créatures incroyablement destructrices. Leur puissance est tout simplement inégalée.','',26972),
(72459,'frFR','QUOI ?! Bon, vous avez réussi à me mettre en colère.','',26972),
(72460,'frFR','Je vais pulvériser votre âme !','',26972),
(72461,'frFR','Vous n’êtes rien !','',26972),
(72462,'frFR','La puissance d’Aile de mort était incoercible. Désormais, elle est MIENNE.','',26972),
(72463,'frFR','Vous ne pouvez rien contre le cataclysme qui s’annonce !','',26972),
(72464,'frFR','Votre FIN est proche.','',26972),
(72465,'frFR','PUISSANCE CATACLYSMIQUE !','',26972),
(72466,'frFR','Brûlez.','',26972),
(72467,'frFR','Le… CHAOS… à l’état pur.','',26972),
(72468,'frFR','Le règne du Chaos approche.','',26972),
(72469,'frFR','L’énergie chaotique va vous anéantir.','',26972),
(72470,'frFR','L’horloge tourne…','',26972),
(72471,'frFR','NOOOOON !','',26972),
(72472,'frFR','ARGHHHH !','',26972),
(72473,'frFR','INIMAGINABLE !','',26972),
(72474,'frFR','Comment est-ce possible ?!','',26972),
(72475,'frFR','Vous allez brûler pour ça.','',26972),
(72476,'frFR','On ne bouge plus…','',26972),
(72477,'frFR','Pour le moment, ça n’a l’air de rien, mais attendez un peu… Bientôt, la douleur sera insoutenable.','',26972),
(72478,'frFR','Tordez-vous de douleur.','',26972),
(72479,'frFR','La douleur s’intensifie.','',26972),
(72480,'frFR','L’angoisse va se saisir de vous.','',26972),
(72481,'frFR','Du large, vermine !','',26972),
(72482,'frFR','Je suis invulnérable !','',26972),
(72483,'frFR','Prenez donc la fuite, lâche.','',26972),
(72484,'frFR','Des forces destructrices vont vous corrompre de l’intérieur.','',26972),
(72485,'frFR','Planter une graine et… la regarder pousser…','',26972),
(72486,'frFR','Je me demande à quoi cette graine donnera naissance ?','',26972),
(72487,'frFR','Je vous offre… la destruction !','',26972),
(72488,'frFR','Quand cette graine germera, vous connaîtrez le sens du mot destruction.','',26972),
(72489,'frFR','La magie du Chaos a le don d’aboutir à des résultats inattendus.','',26972),
(72490,'frFR','Archimonde a fait preuve de génie en employant les Ered’ruin. Ces derniers maîtrisent les énergies noires comme personne.','',26972),
(72491,'frFR','Depuis la mort d’Archimonde, les Ered’ruin n’avaient plus de maître. Désormais, ce sera moi.','',26972),
(72492,'frFR','Les gangrechiens ne sont pas des combattants hors pair, mais ils peuvent avoir leur utilité.','',26972),
(72493,'frFR','Les gangrechiens ont toujours faim de magie… ils la dévorent.','',26972),
(72494,'frFR','Si deux diablotins valent mieux qu’un, qu’est-ce qui vaut mieux que deux diablotins ? SOIXANTE DIABLOTINS !','',26972),
(72495,'frFR','Même les démons mineurs ont leur utilité, pour peu qu’ils soient suffisamment nombreux.','',26972),
(72496,'frFR','','C’est ce que vous m’avez ordonné de faire si nous en arrivions là un jour, Kanrethad. Rien de plus. Vous ne pouvez vous en prendre qu’à vous-même.',26972),
(72497,'frFR','','Merci pour votre aide. Vous avez sauvé le monde plus de fois qu’il ne le saura jamais. Nous devions arrêter Kanrethad. Je vais m’assurer qu’il demeure banni pour toujours.',26972),
(72498,'frFR','','Kanrethad s’est enveloppé d’une telle quantité d’énergie gangrenée qu’elle l’a totalement corrompu. Mais utiliser temporairement son pouvoir ne devrait pas trop vous affecter. Allez-y.',26972),
(72499,'frFR','','Allez-y et utilisez ce que vous avez appris. Si jamais vous souhaitez vous purger de toute l’énergie gangrenée, ou réabsorber celle de Kanrethad, venez me voir. Je serai à l’Autel de la damnation dans la Vallée d’Ombrelune, pour m’assurer qu’il reste banni.',26972),
(72500,'frFR','Ha ha ha… Vous pensiez pouvoir me vaincre ? Plus RIEN ne peut m’atteindre, misérable larve !','',26972),
(72501,'frFR','Maintenant, votre triste histoire touche à son terme.','',26972),
(72502,'frFR','Jubeka ?! Qu’est-ce que… ?!','',26972),
(72503,'frFR','… ARGHHHHHH !!!','',26972),
(72504,'frFR','Les diablotins sont trop nombreux ! Occupez-vous-en !','',26972),
(72534,'frFR','Le forgeron céleste va bientôt mourir !','',26972),
(72535,'frFR','Le défenseur céleste est sur le point de mourir !','',26972),
(72536,'frFR','Le défenseur céleste crée une zone d’ |cFFFF2222|Hspell:140068|h[énergie guérisseuse]|h|r !','',26972),
(72696,'frFR','Avancez ! Contemplez le don du roi-tonnerre !','',26972),
(72697,'frFR','J’ai été choisi. Sa puissance coule dans mes veines !','',26972),
(72698,'frFR','C’est trop… les esprits ne peuvent contenir sa puissance !','',26972),
(72699,'frFR','Vous serez puni ! Votre vie est une leçon de futilité !','',26972),
(72700,'frFR','Pour Zandalar !','',26972),
(72701,'frFR','Bloquez les portes. Les Zandalari n’ont pas réussi à protéger le mur.','',26972),
(72716,'frFR','','Les explosifs ont été placés contre le mur ! À vous l’honneur !',26972),
(72728,'frFR','Bloquez les portes. Les Zandalari n’ont pas réussi à protéger le mur.','',26972),
(72735,'frFR','','Pour la Horde !!',26972),
(72800,'frFR','La forge est sécurisée, et il est temps pour nous de partir. Puisse la chance rester à vos côtés tout au long de votre quête.','',26972),
(72938,'frFR','Non, arrêtez. Arrêtez ça tout de suite !','',26972),
(72981,'frFR','Oui, chargeons ce trillium !','Oui, chargeons ce trillium !',26972),
(72986,'frFR','Apportez le sha !','Apportez le sha !',26972),
(72991,'frFR','|TInterface\\Icons\\achievement_zone_cataclysm.blp:20|t%s commence à canaliser un gigantesque |cFFFF0000|Hspell:138564|h[Cataclysme]|h|r !','',26972),
(72992,'frFR','|TInterface\\Icons\\ability_warlock_chaosbolt.blp:20|t%s commence à canaliser un gigantesque |cFFFF0000|Hspell:138559|h[Trait du chaos]|h|r !','',26972),
(72995,'frFR','Le maître-forge Vul’kon s’équipe de son bâton et commence à canaliser la puissance de la foudre !','',26972),
(72996,'frFR','Le maître-forge Vul’kon s’équipe de son marteau et commence à le balancer avec beaucoup de force !','',26972),
(73016,'frFR','Êtes-vous $gprêt:prête; ? Je vais lancer la forge du Tonnerre. On pourrait avoir quelques sueurs froides.','',26972),
(73017,'frFR','Commençons !','Commençons !',26972),
(73093,'frFR','HOZEN-FU de l’EXTRÊME !','',26972),
(73220,'frFR','Il était une fois… Il y a très peu de temps, en fait. Un grand roi vint chercher de l’aide auprès de trois puissants nains : le conseil des Trois marteaux.','',26972),
(73221,'frFR','Les éclaireurs du roi avaient découvert que des Trolls zandalari menaçaient la capitale des nains.','',26972),
(73222,'frFR','Bien sûr, le roi pensait que s’il les aidait avec leur problème de Trolls, ils pourraient lui confier davantage de troupes pour sa campagne contre la Horde.','',26972),
(73223,'frFR','Mais le roi ignorait que les nains ne se faisaient même pas confiance entre eux !','',26972),
(73224,'frFR','« Nous ne pouvons pas vous aider », dit le Nain barbe-de-bronze, « car si nous ne surveillons pas les Sombrefers, ils battront les Marteaux-Hardis et s’empareront de Forgefer ! »','',26972),
(73225,'frFR','« Nous ne pouvons pas vous aider », dit le Nain marteau-hardi, « car si nous ne surveillons pas les Sombrefers, ils battront les Barbe-de-Bronze et s’empareront de Forgefer ! »','',26972),
(73226,'frFR','Le roi était furieux. « Si aucun de vous ne m’aide, alors Forgefer sera assiégée ! »','',26972),
(73227,'frFR','Seule une naine offrit son aide au roi. « Nous vous prêterons main-forte », dit Moira des Sombrefers. « Nous ferons confiance à nos frères nains, et nous leur montrerons ce qu’est la loyauté ! »','',26972),
(73228,'frFR','Et ainsi Moira et le haut roi partirent dans la neige pour sauver la ville, laissant les autres réfléchir sur le sens de leurs actes.','',26972),
(73229,'frFR','Qu’est-ce qui arrive ensuite ? Je dois le découvrir !','',26972),
(73230,'frFR','Le haut roi, ses champions et les nains sombrefers œuvrèrent ensemble pour sauver Forgefer.','',26972),
(73231,'frFR','Les autres chefs des nains eurent honte de leur comportement et jurèrent de ne plus jamais laisser la peur ou la méfiance affecter leur jugement.','',26972),
(73232,'frFR','C’est ainsi qu’un roi humain permit de réunir les clans nains divisés depuis si longtemps.','',26972),
(73233,'frFR','Libres de se faire confiance, les trois chefs des nains vouèrent toute leur armée à la cause de l’Alliance.','',26972),
(73234,'frFR','Pendant ce temps, à Orgrimmar, le chef de guerre Garrosh Hurlenfer envoyait des équipes de sapeurs gobelins sur tout le continent de Pandarie.','',26972),
(73235,'frFR','Il avait promis monts et merveilles à quiconque découvrirait les secrets enfouis qui emplissent ces contrées d’une énergie si sombre et puissante.','',26972),
(73236,'frFR','À ma grande surprise, ils ont trouvé quelque chose ! Ici même, dans le val sacré ! Que va-t-il se passer maintenant ?','',26972),
(73237,'frFR','L’histoire s’écrit sous nos yeux…','',26972),
(73238,'frFR','Bon ! Alors même que l’Alliance resserre ses liens, la Horde se déchire de l’intérieur.','',26972),
(73239,'frFR','Les choses ne vont pas tarder à se précipiter. J’aimerais pouvoir vivre le prochain chapitre de cette histoire, mais hélas, je n’en suis que le narrateur.','',26972),
(73240,'frFR','Mais vous, vous êtes assez brave et héroïque pour plonger au cœur des évènements à l’instant où ils adviennent.','',26972),
(73241,'frFR','Allez-y ! Allez à Durotar ! Laissez votre trace dans l’histoire qui va s’écrire autour de vous !','',26972),
(73299,'frFR','Ah, nous y voilà. Oh, que mes vieux os sont fatigués. Plus que vous ne pouvez l’imaginer.','',26972),
(73300,'frFR','Vous m’avez surpris. Je m’attendais à ce que quelqu’un d’aussi héroïque que vous renâcle à porter un vieillard sur une montagne. ','',26972),
(73301,'frFR','Je pensais vous donner une leçon, mais en fait c’est vous qui m’avez instruit. Quand j’étais jeune, voyez-vous, quand j’étais jeune…','',26972),
(73302,'frFR','J’étais… EMPEREUR.','',26972),
(73303,'frFR','Le royaume que vous voyez tout autour de vous était soumis à ma volonté.','',26972),
(73304,'frFR','J’ai vaincu mes doutes, mes peurs, ma colère… et je les ai enfouis dans la terre de mon royaume.','',26972),
(73305,'frFR','Mais il y a un vice que j’ai gardé. Le seul sha que je n’ai jamais vaincu. L’ORGUEIL.','',26972),
(73306,'frFR','Mon orgueil a couvert ce pays de brumes ! Je pensais que nous valions mieux que le reste du monde.','',26972),
(73307,'frFR','Je croyais que nous pouvions régler nous-mêmes nos problèmes. Mais pendant dix mille ans, nous avons stagné, avec nos doutes et nos peurs enfouis dans le sol, prêts à ressurgir à la moindre occasion.','',26972),
(73308,'frFR','L’orgueil. C’est le plus insidieux des sha. Il est bénéfique jusqu’à ce qu’il tourne mal. Et alors il devient plus dangereux que tous les autres combinés.','',26972),
(73309,'frFR','Gardez-vous de l’orgueil ! Soyez humble ! Le monde plonge dans le chaos. Les anciens ennemis doivent s’allier. Les peuples fiers doivent admettre qu’ils ont besoin d’aide.','',26972),
(73310,'frFR','Les choses vont empirer avant de pouvoir s’améliorer. Ce n’est qu’en travaillant ensemble que nous pourrons repousser les ténèbres.','',26972),
(73311,'frFR','Et notre seul obstacle… c’est l’orgueil.','',26972),
(73352,'frFR','$gTauren:Taurène; ! Quelle folie s’est emparée des vôtres ? Vous avez ouvert une plaie béante dans notre vallée sacrée !','',26972),
(73353,'frFR','Seigneur Zhu, vous devez comprendre… Le « chef de guerre » orc qui a donné cet ordre ne peut plus être considéré comme un représentant officiel de la Horde. Nombre de voix se sont élevées contre lui.','',26972),
(73354,'frFR','Ces querelles intestines ne font aucune différence à mes yeux. Votre Horde a profané cet endroit. Vous n’êtes désormais plus les bienvenus… Partez !','',26972),
(73355,'frFR','Donnez-nous un peu de temps, seigneur Zhu. Laissez-nous une chance de traduire Hurlenfer en justice.','',26972),
(73356,'frFR','Marche-soleil, j’ai beaucoup de respect pour votre peuple. Vous nous avez été d’une aide précieuse au cours de notre campagne contre le sha et le roi-tonnerre. Si tel n’était pas le cas, j’aurais déjà demandé aux Pandashan de vous chasser de ce sanctuaire… mais ma patience a des limites. La Horde doit partir.','',26972),
(73357,'frFR','Je vous en prie, nous ne demandons qu’à laver cet affront.','',26972),
(73358,'frFR','Taran Zhu regarde au loin, l’air sombre.','',26972),
(73359,'frFR','Très bien… Je vous laisse jusqu’à la fin de la saison. Pas un jour de plus.','',26972),
(73360,'frFR','Nous autres pandarens avons l’habitude de lutter contre la tyrannie. Le combat qui nous attend mettra nos âmes à l’épreuve. Puissent les Astres vous guider.','',26972),
(73369,'frFR','Regardez-nous tous les trois. De nouveau sur le sable de Durotar ! Comme dans le bon vieux temps.','',26972),
(73370,'frFR','Pas tout à fait, mon vieil ami. Les temps ont changé. La différence entre les alliés et les ennemis n’est plus aussi claire.','',26972),
(73371,'frFR','Ils arrivent ! Hurlenfer il croit que son peuple il va tous nous écraser.','',26972),
(73372,'frFR','Il est temps de montrer au chef de guerre la fureur des Sombrelances !','',26972),
(73373,'frFR','Arrêtez ! Laissez-les filer. Hurlenfer il les fera exécuter pour lâcheté s’ils rentrent. Le village de Sen’jin il est en sécurité !','',26972),
(73374,'frFR','Regroupez-vous ! Le clou on va l’enfoncer. Avant que le chef de guerre il fortifie Tranchecolline, nous on va la prendre pour la révolution, et lui fermer la route des Tarides.','',26972),
(73375,'frFR','Tous ceux qui peuvent encore combattre, qu’ils viennent avec moi !','',26972),
(73376,'frFR','Attends, Vol’jin. Voir la Horde verser le sang de la Horde, ça me déchire le cœur.','',26972),
(73377,'frFR','On a besoin de toi, mon ami.','',26972),
(73378,'frFR','Je le sais. Et je compte sur toi pour mener le siège. Ma présence est requise ailleurs.','',26972),
(73379,'frFR','Je refuse de croire que tous mes frères soutiennent Garrosh.','',26972),
(73380,'frFR','Si toi tu poses un pied à Orgrimmar, Hurlenfer il va te planter un couteau dans le dos !','',26972),
(73381,'frFR','Je vais aller à Orgrimmar. Seul. Eitrigg, Saurcroc… ils sont forcément opposés à Garrosh. Je dois en trouver d’autres.','',26972),
(73382,'frFR','Ça je veux pas t’entendre le dire.','',26972),
(73383,'frFR','Je devais le dire. Vol’jin. Si nous n’en sortons pas, je veux que tu le saches. Tu as toujours été mon ami. Mon frère.','',26972),
(73384,'frFR','Pour la Horde.','',26972),
(73385,'frFR','Pour la Horde.','',26972),
(73386,'frFR','Sombrelances, avec moi ! En selle ! Pas de repos jusqu’à Orgrimmar !','',26972),
(73407,'frFR','Eh bien, quelle force ! Plus jeune, j’aurais probablement douté de notre réussite. Mais maintenant, je ne doute plus de rien.','',26972),
(73408,'frFR','Si froid et venteux ! Autrefois, cela aurait affligé mes vieux os. Mais aujourd’hui, je suis rempli d’espoir.','',26972),
(73409,'frFR','Hé, ne vous en prenez pas aux éléments. La violence est dans leur nature. J’ai vaincu ma propre colère il y a bien longtemps.','',26972),
(73410,'frFR','Quelle patience ! Quand j’étais jeune, j’aurais détesté cette tâche. Aujourd’hui, je ne suis qu’amour.','',26972),
(73411,'frFR','Ne craignez pas les hauteurs, j’ai eu ce tort quand j’étais plus jeune. La peur nous amène à faire des choses effroyables. Ah, mais comme moi, vous avez appris les leçons du courage !','',26972),
(73733,'frFR','Grand Serpent de jade ! Entendez notre appel.','',26972),
(73734,'frFR','Mon agent et moi-même souhaitons recevoir votre bénédiction de sagesse.','',26972),
(73746,'frFR','Faire ce qui est juste, quel qu’en soit le prix. Voilà ce qu’est la sagesse.','',26972),
(73747,'frFR','Comment peut-on juger sage de ne pas agir pour le bien commun ?','',26972),
(73792,'frFR','Je vais briser ce monde !','',26972),
(73884,'frFR','%s vous remet une corde d’escalade.','',26972),
(73895,'frFR','C’est un risque que je dois prendre. Mais si cela devait arriver, je te prie de veiller sur Aggra et sur mon fils.','',26972),
(73903,'frFR','Matez un peu ça… ces bâtards de l’Alliance débarquent de Theramore. Tuez-les !','',26972),
(73931,'frFR','Le Serpent de jade est l’incarnation de la sagesse en Pandarie. Voyons ce qu’il a à nous dire.','',26972),
(73972,'frFR','Des intrus ont été repérés ! Il faut défendre la forge du Tonnerre !','',26972),
(73973,'frFR','La forge du Tonnerre est à nous ! Nous sommes prêts à donner nos vies pour elle !','',26972),
(74018,'frFR','Je vous retrouverai à chacun des quatre sanctuaires.','',26972),
(74019,'frFR','Souvenez-vous, nous devons nous rendre dans les quatre sanctuaires, mais nous ne devons remporter qu’UN défi.','',26972),
(74020,'frFR','Choisissez le défi le plus adapté à vos propres talents.','',26972),
(74021,'frFR','Bonne chance !','',26972),
(74091,'frFR','Parlez-moi encore du roi et du conseil…','Parlez-moi encore du roi et du conseil…',26972),
(74094,'frFR','Parlez-moi encore du chef de guerre et des ténèbres…','Parlez-moi encore du chef de guerre et des ténèbres…',26972),
(74130,'frFR','Mon œuvre n’est pas terminée. Cette cape vous donnera la puissance des Astres vénérables.','',26972),
(74131,'frFR','Très bientôt, nous pourrons imprégner votre cape de mes propres pouvoirs draconiques.','',26972),
(74132,'frFR','Continuez d’aider vos alliés à préparer leur guerre. Je vous recontacterai.','',26972),
(74133,'frFR','Le voyant Hao Pham Roo vous tend l’extrémité de sa corde d’escalade. Attachez-la au prochain point d’ancrage et aidez-le dans son ascension de la montagne !','',26972),
(74160,'frFR','Auriez-vous la bonté d’aider un vieil homme à reconstituer l’histoire du dernier empereur ?','',26972),
(74161,'frFR','Je suis prêt à vous aider à reconstituer le passé.','Je suis prête à vous aider à reconstituer le passé.',26972),
(74184,'frFR','Zéphyr augmente votre vitesse de déplacement : vous partagez cet effet avec le voyant Hao Pham Roo en marchant à ses côtés.','Zéphyr augmente votre vitesse de déplacement : vous partagez cet effet avec le voyant Hao Pham Roo en marchant à ses côtés.',26972),
(74261,'frFR','Hatock, fils du Loup de Fer ! Je viens chercher ta tête.','',26972),
(74272,'frFR','Un peu de calme, $gpetit:petite;. À cette distance, votre armure ne résisterait pas à grand-chose.','',26972),
(74273,'frFR','Ga’nar, on tient le pisteur de Durotan.','',26972),
(74274,'frFR','La vermine n’en finit plus de venir envahir nos terres sacrées.','',26972),
(74275,'frFR','Durotan doit avoir une bonne raison de nous l’avoir $genvoyé:envoyée;.','',26972),
(74276,'frFR','Bah. Je vais vous montrer ce que je pense du « message » de mon frère.','',26972),
(74277,'frFR','Un peu de calme, démon. À cette distance, votre armure ne résisterait pas à grand-chose.','',26972),
(74278,'frFR','Ga’nar, on tient l’orc vert pisteur de Durotan qui était à nos trousses.','',26972),
(74279,'frFR','Encore de la vermine corrompue. Comme si cette invasion de Scorpars ne suffisait pas.','',26972),
(74280,'frFR','Votre peau verte montre bien à quel point vous êtes une aberration. Vous n’êtes pas plus un orc que la crasse qui tapisse cette fosse.','',26972),
(74288,'frFR','L’impatience de Ga’nar risque de diviser les Loups-de-Givre. Mon frère a toujours fait passer ses propres intérêts avant ceux du clan.','',26972),
(74316,'frFR','Ga’nar ! Il était temps que tu reviennes. Quels sinistres trophées nous rapportes-tu là ?','',26972),
(74317,'frFR','J’ai tué les fils du Loup de Fer. Puisse-t-il se noyer dans le sang des siens.','',26972),
(74318,'frFR','Ta folie nous a exposés dangereusement. Beaucoup sont morts.','',26972),
(74319,'frFR','Tu n’es pas mon chef, frère. En tant que second fils de la famille, et au nom de la justice que j’ai rendue aujourd’hui, j’invoque mon droit au mak’gora.','',26972),
(74320,'frFR','Puisque nous devons en arriver là…','',26972),
(74322,'frFR','','Vous ne pouvez pas faire ça ! Vous êtes du même sang !',26972),
(74323,'frFR','Dans une famille, on compte les uns sur les autres. Moi seul ai veillé à ce que notre père soit vengé !','',26972),
(74324,'frFR','La vengeance ne nourrit pas et ne protège pas notre clan. C’est pour ça que notre père m’a nommé chef.','',26972),
(74325,'frFR','Notre père a fait le mauvais choix. Ce clan a besoin de force !','',26972),
(74326,'frFR','Achève-moi.','',26972),
(74327,'frFR','Oui, chef.','',26972),
(74328,'frFR','Sa présence souille l’honneur des Loups-de-Givre. Les autres clans vont nous mépriser.','',26972),
(74329,'frFR','Si vous n’êtes pas capable de tenir debout… vous ne méritez pas… de… vivre !','',26972),
(74330,'frFR','La vengeance ne rend pas notre clan plus fort, mon frère.','',26972),
(74331,'frFR','Lève-toi, mon frère. J’ai besoin de toi. Notre clan a besoin de toi.','',26972),
(74332,'frFR','La puissance qu’on acquiert en protégeant les êtres qui nous sont chers.','',26972),
(74333,'frFR','Nous formons une seule et même famille, Ga’nar. Et une famille se serre les coudes.','',26972),
(74334,'frFR','C’est ÇA qui fait la toute-puissance des Loups-de-Givre.','',26972),
(74335,'frFR','Venez vous battre à nos côtés, mon frère. Allions nos forces. Nous avons fort à faire.','',26972),
(74340,'frFR','J’ai perdu ? Comment est-ce possible ?','',26972),
(74341,'frFR','Eh oui, mon frère. Je vous accueillerais à bras ouverts.','',26972),
(74342,'frFR','Toujours en vie, $gpetit:petite; ? C’est bien, comme ça je n’aurai pas à vous sauver. Venez, nous avons à parler.','',26972),
(74346,'frFR','J’ai ma fierté, mais je veux bien reconnaître ma défaite, mon cher frère. J’espère en apprendre plus sur votre puissance. Nous acceptons de nous joindre à vous.','',26972),
(74351,'frFR','Donnez-moi de l’argent pour m’acheter de super trucs.','',26972),
(74352,'frFR','Fusilier','Fusilier',26972),
(74366,'frFR','Ton père pourra PEUT-ÊTRE identifier ce qu’il reste de ton crâne de piaf.','',26972),
(74368,'frFR','Mes frères ! Aujourd’hui, nous accomplissons ce que Durotan se refuse à faire !','',26972),
(74369,'frFR','Les Scorpars sont tenus à distance et nos montures sont prêtes, mon vieil ami.','',26972),
(74370,'frFR','Aujourd’hui, nous allons nous venger de la bête qui a tué Garad !','',26972),
(74395,'frFR','Bienvenue à Givrevent.','',26972),
(74404,'frFR','Type magique','Type magique',26972),
(74405,'frFR','Type à dégâts de zone','Type à dégâts de zone',26972),
(74406,'frFR','Type à ralentissements','Type à ralentissements',26972),
(74416,'frFR','En avant, mes frères et mes sœurs ! Traversez le campement et regroupez-vous à la combe Sauvage !','',26972),
(74417,'frFR','Lok’tar ogar !','',26972),
(74439,'frFR','Mon frère, ma mascotte va vous réduire en cendres !','',26972),
(74440,'frFR','Ma ménagerie va vous ronger jusqu’à l’os.','',26972),
(74442,'frFR','Le moment est donc venu.','',26972),
(74443,'frFR','Quant à vous, $gétranger:étrangère;…','',26972),
(74446,'frFR','À vous la monture empruntée. Ha ha ha !','',26972),
(74447,'frFR','Vous avez gagné votre place dans ce raid. Et puisque vous ne vous êtes encore $glié:liée; à aucun Loup-de-Givre…','',26972),
(74625,'frFR','Voyons si vous apprécierez ma nouvelle contribution à l’arsenal du chef de guerre : l’Étoile de Fer !','',26972),
(74626,'frFR','Regardez-moi ça. C’est vous qui avez détruit mon mastodonte.','',26972),
(74656,'frFR','Aggron ! Montre-leur qui est l’boss !','',26972),
(74689,'frFR','','Drek’Thar ! Je ne sais pas ce que tu fabriques là-haut, mais ça commence sérieusement à énerver les gorens.',26972),
(74738,'frFR','','Attention, les lieux sont sacrés ; autant dire que c’est dangereux. Ce que je m’apprête à faire pourrait bien nous attirer de gros ennuis.',26972),
(74739,'frFR','','Grands esprits du vent, entendez mon appel ! Faites-moi part de la source de vos tourments.',26972),
(74740,'frFR','','Je vous aiderai de mon mieux à l’aide de mes totems, si le besoin s’en fait sentir.',26972),
(74741,'frFR','Je suis venu supplier les éléments de nous soutenir au cours de la bataille qui nous attend.','',26972),
(74742,'frFR','Mais dans le tumulte des vents mordants qui cinglent les montagnes, j’ai entendu les hurlements d’une Fureur. Exurotus.','',26972),
(74743,'frFR','Malmenée, brisée par une magie ancienne et partiellement anéantie, cette Fureur s’est retrouvée prisonnière de Kron, le magnaron.','',26972),
(74744,'frFR','La Fureur s’est fragmentée, et les éclats qui n’ont pas été emportés par les vents ont fait la joie de pilleurs en tous genres.','',26972),
(74783,'frFR','','Attendez, $p ! Par ici, vite, avant que le géant ne vous voie.',26972),
(74784,'frFR','Akama ! Pourquoi épargner leur ville ? Pourquoi leur donner une seconde chance ?','',26972),
(74785,'frFR','La parole des Orcs ne vaut rien. Ils cherchent juste à gagner du temps.','',26972),
(74786,'frFR','Assez parlé de combat, Hogo. Ombrelune peut enfin profiter de la paix.','',26972),
(74787,'frFR','Ou pas…','',26972),
(74788,'frFR','MES PAUVRES OREILLES !','',26972),
(74828,'frFR','','J’entends un esprit… une entité puissante ! Vous allez devoir repousser ces gorens encore un petit moment.',26972),
(74829,'frFR','','J’ai encore besoin de quelques instants.',26972),
(74842,'frFR','','Du calme, chaman. Repose-toi un peu. Notre camarade va nous ouvrir la voie et nous rattraperons notre retard quand tu seras prêt.',26972),
(74907,'frFR','','Esprits du vent, conférez-nous votre vélocité.',26972),
(74908,'frFR','','Les Sire-Tonnerre sont pour la plupart des imbéciles, mais quand il s’agit de combattre les géants, ils connaissent leur affaire.',26972),
(74909,'frFR','','On dit aussi qu’ils ont pour habitude de graver le nom de leurs tactiques préférées sur leurs brassards. Certainement de la vantardise, à moins qu’ils n’aient une mémoire défaillante.',26972),
(74910,'frFR','','Les esprits me protègent, mais le froid est mordant. J’ai les poumons en feu.',26972),
(74911,'frFR','','Voilà, c’est la carcasse. Je… je ne pense pas pouvoir vous accompagner. Mon bras tremble comme une feuille, et mon esprit est envahi par les hurlements de la terre.',26972),
(74931,'frFR','','Je vous retrouverai à l’intérieur, $p. Puissent les esprits vous guider. Orgrock, aidez-moi, voulez-vous.',26972),
(75008,'frFR','','Là-dedans.',26972),
(75014,'frFR','Notre travail est d’une importance vitale.','',26972),
(75045,'frFR','Ah ! Voilà mon agent !','',26972),
(75046,'frFR','Mais bien sûr ! Une vieille connaissance de la forêt de Jade !','',26972),
(75047,'frFR','Un instant… je veux être sûr d’avoir bien tout suivi.','',26972),
(75050,'frFR','Les Pandarens raconteront ce récit de génération en génération !','',26972),
(75052,'frFR','Cela commence avec cette personne !','',26972),
(75054,'frFR','Venue d’au-delà des brumes !','',26972),
(75056,'frFR','Pour conquérir de nouvelles terres mystérieuses !','',26972),
(75058,'frFR','Est-il nécessaire d’utiliser le verbe conquérir ?','',26972),
(75059,'frFR','Et s’aventurer dans des caveaux perdus…','',26972),
(75061,'frFR','Mantides et mogu se sont agenouillés devant tant de fureur.','',26972),
(75064,'frFR','Leur puissance et leur sagesse au service d’une plus grande gloire !','',26972),
(75066,'frFR','Quand la guerre frappa les rives de la Pandarie, sa contribution fut grande.','',26972),
(75067,'frFR','Un modèle pour sa faction, adulé par ses alliés et craint par ses ennemis.','',26972),
(75068,'frFR','Même le redoutable roi-tonnerre ne put rien face à sa puissance.','',26972),
(75069,'frFR','Un par un, les secrets d’un antique empire furent révélés.','',26972),
(75070,'frFR','Oui, un savoir dévoilé pour que le monde puisse en bénéficier.','',26972),
(75071,'frFR','Un POUVOIR acquis pour la GUERRE et la CONQUÊTE !','',26972),
(75074,'frFR','Un moment… de quel genre de héros parlons-nous, au juste ?','',26972),
(75078,'frFR','Un agent destructeur, forgé par ma volonté pour changer la face d’Azeroth à tout jamais.','',26972),
(75083,'frFR','Je vous en conjure, réfléchissez bien à l’héritage que vous souhaitez laisser derrière vous.','',26972),
(75085,'frFR','Admirez mon œuvre ! La puissance sous-jacente des titans, imprégnée de ma propre essence draconique, et tempérée par la sagesse des Astres pandarens.','',26972),
(75089,'frFR','Une puissance phénoménale ; utilisez-la pour guérir ou détruire, protéger ou annihiler !','',26972),
(75093,'frFR','Venez à moi ! Venez recevoir votre juste récompense !','',26972),
(75105,'frFR','Comment l’histoire finira-t-elle ?','',26972),
(75111,'frFR','Il n’y a qu’un moyen de le savoir.','',26972),
(75115,'frFR','Une légende pandarène est née ! Gloire à notre nouvelle légende !','',26972),
(75148,'frFR','C’est ridicule, j’avais la situation en main. Cette attaque me laisse de glace. ','',26972),
(75150,'frFR','','Je le savais. Vous auriez dû rester à l’abri dans le fief, archimage.',26972),
(75320,'frFR','Racontez mon histoire…','Racontez mon histoire…',26972),
(75351,'frFR','Je vais l’anéantir ! (Les Blafards... les Blafards sont la clé…)','',26972),
(75374,'frFR','Contrairement à vous, vos mascottes sont adorables.','',26972),
(75375,'frFR','J’ai été programmé pour me gausser et jubiler. Ha ha… Ha ha… Ha ha.','',26972),
(75376,'frFR','C’est vraiment pas de chance.','',26972),
(75378,'frFR','Quel effet ça fait, $r ?','',26972),
(75379,'frFR','Quand bien même je ressentirais des émotions, tout cela ne me tirerait pas une larme.','',26972),
(75395,'frFR','Votre serviteur est terrassé.','',26972),
(75396,'frFR','Mes capteurs olfactifs détectent une odeur de brûlé.','',26972),
(75397,'frFR','Dommage… et maintenant, une mascotte digne de ce nom.','',26972),
(75398,'frFR','Vous allez payer pour ça.','',26972),
(75502,'frFR','Une opportunité se présente ! Je suis persuadé que l’île du Temps figé est la clé pour décupler la puissance de votre cape.','',26972),
(75503,'frFR','Une île figée dans le temps, où le soleil ne se couche jamais. Qu’est-ce que cela veut dire ?','',26972),
(75504,'frFR','Puissance ! Gloire ! Richesse !','',26972),
(75505,'frFR','À nous la prospérité ! Retrouvez-moi sur l’île du Temps figé.','',26972),
(75507,'frFR','Moi aussi, j’aimerais voir cette île de mes propres yeux. Je vous y retrouverai peut-être.','',26972),
(75595,'frFR','','|cFFFF8040Ki l’assassin donne un |r|cFF71D5FF|Hspell:145427|h[Coup de pied]|h|r|cFFFF8040 à $n.|r',26972),
(75596,'frFR','','|cFFFF8040Kavan l’Arcaniste lance |r|cFF71D5FF|Hspell:145530|h[Contresort]|h|r|cFFFF8040 sur $n.|r',26972),
(75629,'frFR','On est ce que l’on boit, $n. J’espère que vous avez bu un truc fort.','',26972),
(75630,'frFR','Vous avez bien combattu, mais vous n’avez pas de stratégie. Prenez un verre et réfléchissez-y.','',26972),
(75631,'frFR','Eh bien, on dirait bien que j’ai été battu ! Je vais devoir me concocter quelques idées pour la prochaine fois !','',26972),
(75632,'frFR','Pourquoi se battait-il ? Pour mourir, apparemment.','',26972),
(75633,'frFR','Le vent souffle en ma faveur.','',26972),
(75634,'frFR','Une attaque chanceuse !','',26972),
(75635,'frFR','Je savais que ça allait se produire.','',26972),
(75636,'frFR','Une glorieuse défaite !','',26972),
(75637,'frFR','Reposez-vous, $gmon:ma; jeune $gami:amie;.','',26972),
(75638,'frFR','Vous êtes peut-être $gprêt:prête; pour… hum… une leçon ayant pour thème le chaos ?','',26972),
(75639,'frFR','Vous vous demandiez tellement si vous pouviez gagner, que vous ne vous êtes pas $gposé:posée; la question de savoir si c’était judicieux.','',26972),
(75640,'frFR','Bah, le manque d’humilité dont certains font preuve vis-à-vis de la nature est… hum… ahurissant.','',26972),
(75641,'frFR','Qu’y a-t-il de si grandiose dans la victoire ? Elle est toujours synonyme de violence et de meurtrissures. Ce que vous appelez victoire… bah, laissez tomber.','',26972),
(75642,'frFR','Mort ? Vous voulez dire… disparu, non ?','',26972),
(75643,'frFR','Votre mascotte a eu sa chance, mais la nature a jugé bon de mettre fin à son existence.','',26972),
(75644,'frFR','Je… je dis simplement que la vie n’a pas… hmm… trouvé sa voie.','',26972),
(75645,'frFR','C’est… c’est la théorie du chaos.','',26972),
(75646,'frFR','Alors, qu’avez-vous dans votre équipe, roi Mukla ?','',26972),
(75647,'frFR','Dinos… vaincu ? Vaincu ?','',26972),
(75648,'frFR','Vous faites face à Patience, Sagesse et Connaissance ! Et vous, quelles vertus possédez-vous, $n ?','',26972),
(75649,'frFR','Aujourd’hui, vous avez perdu… mais qu’avez-vous appris ?','',26972),
(75650,'frFR','Vous m’avez enseigné beaucoup, $r. Il semblerait que le maître soit redevenu élève.','',26972),
(75651,'frFR','Un sacrifice utile.','',26972),
(75652,'frFR','Les feuilles d’automne doivent tomber pour laisser place aux bourgeons du printemps.','',26972),
(75653,'frFR','La défaite n’est qu’une leçon qui avance masquée par la déception.','',26972),
(75654,'frFR','Comme lorsque le torrent rencontre la falaise, on peut trouver de la beauté dans la chute, si on sait l’observer.','',26972),
(75655,'frFR','Mourir serait une aventure merveilleuse.','',26972),
(75656,'frFR','Quand une vertu est perdue, accrochez-vous à celles qui restent.','',26972),
(75657,'frFR','Un sacrifice utile ?','',26972),
(75658,'frFR','','Oh, j’espère que vous aimez les surprises.',26972),
(75659,'frFR','','Vous avez de la chance : seules vos mascottes ont souffert… pour cette fois.',26972),
(75660,'frFR','','On ressort du tournoi des Astres vénérables en vainqueur… ou les pieds devant.',26972),
(75661,'frFR','','Il suffit d’éliminer le bon adversaire, et le reste se fait tout seul.',26972),
(75662,'frFR','','Oh, c’était une de vos mascottes préférées ? Désolée.',26972),
(75663,'frFR','','C’est tellement facile que c’en serait presque ennuyeux… si ce n’était pas aussi jubilatoire, en même temps.',26972),
(75664,'frFR','','Espèce de vermine… ma mascotte ne remarchera peut-être plus jamais !',26972),
(75665,'frFR','','Ce sont les choses que nous aimons qui nous font le plus de mal, $c. Souvenez-vous-en.',26972),
(75666,'frFR','','Continuez de tuer mes mascottes et vous trouverez du poison dans votre chope, ce soir.',26972),
(75667,'frFR','','La peur peut faire plus de dégâts qu’une épée.',26972),
(75668,'frFR','Vous avez de la chance que Bidule ne soit pas là, mais je vais quand même vous transformer en serpillière, $c.','',26972),
(75669,'frFR','Cette victoire, elle est pour toi, Bidule !','',26972),
(75670,'frFR','Bah… à bien regarder, je ne sais pas si c’est vraiment devenu mon truc, les animaux. Bon… comment ça marche, ces bandages ?','',26972),
(75671,'frFR','Ha ! Je ne m’attendais pas à ce que ça se passe aussi bien !','',26972),
(75672,'frFR','Oh, désolé… ce petit machin va avoir besoin d’affection et de réconfort.','',26972),
(75673,'frFR','Pendant un moment, j’ai bien cru qu’on était dans le pétrin.','',26972),
(75674,'frFR','Non ! Encore ?!','',26972),
(75675,'frFR','Pour un Nain, j’ai vraiment pas de bol !','',26972),
(75676,'frFR','Ha… vous allez me payer ça… oh que oui !','',26972),
(75677,'frFR','Ne vous laissez pas tromper par leur petite taille, $n, ils sont aussi vifs que disciplinés.','',26972),
(75678,'frFR','L’impatience ne mène qu’à la défaite. Vous devez apprendre à sentir le rythme du combat.','',26972),
(75679,'frFR','Il faut de véritables qualités de stratège pour venir à bout de mes moines. Bien joué, $n.','',26972),
(75680,'frFR','Tout s’est passé comme je l’avais prévu.','',26972),
(75681,'frFR','Vous manquez cruellement de discipline.','',26972),
(75682,'frFR','Vous pensez pouvoir survivre avec ce qui vous reste ?','',26972),
(75683,'frFR','Il a combattu et il est mort honorablement.','',26972),
(75684,'frFR','La victoire nécessite souvent des sacrifices.','',26972),
(75685,'frFR','Quand un Pandashan tombe au combat, un autre vient prendre sa place.','',26972),
(75686,'frFR','Tout comme l’eau finit par ronger la roche, vous aussi vous coulerez bientôt.','',26972),
(75687,'frFR','L’esprit des rivières avait prédit ce triomphe.','',26972),
(75688,'frFR','L’esprit des rivières avait prédit cette défaite.','',26972),
(75689,'frFR','Et voilà l’adversaire balayé par les eaux sans laisser de trace.','',26972),
(75690,'frFR','Le roc se croit inamovible, jusqu’au jour où l’eau emporte la terre qui lui tient lieu de socle.','',26972),
(75691,'frFR','L’eau purifie tout sur son passage !','',26972),
(75692,'frFR','Ma créature a été défaite… mais elle reviendra à moi en temps et en heure.','',26972),
(75693,'frFR','Un simple écueil n’empêche pas la rivière de couler.','',26972),
(75694,'frFR','Il n’est pas de bataille qu’une armée puisse mener sans perte.','',26972),
(75696,'frFR','Quelle que soit leur taille, les dragons sont dangereux… vous n’allez pas tarder à le découvrir.','',26972),
(75697,'frFR','Si je peux remporter un combat de ce genre, j’ai peut-être ma chance face aux Astres vénérables.','',26972),
(75698,'frFR','Bien joué, $n. Vous avez choisi vos alliés avec soin, et sous vos ordres, ils se sont battus de manière exemplaire.','',26972),
(75699,'frFR','Comme je vous le disais, les attaques des dragons sont foudroyantes, d’où leur réputation.','',26972),
(75700,'frFR','Même le plus solide des alliés peut faillir face à la magie draconique.','',26972),
(75701,'frFR','Un canon en verre a de bonnes chances de se briser avant même de pouvoir faire feu.','',26972),
(75702,'frFR','J’ai sous-estimé votre force.','',26972),
(75703,'frFR','Voilà qui est inattendu.','',26972),
(75704,'frFR','Il sera difficile de se remettre d’une telle perte.','',26972),
(75706,'frFR','Ne laissez pas les dégâts que cette terre a subis vous désespérer.','',26972),
(75707,'frFR','Il y a longtemps, cette terre était hantée par les ombres du doute, de la peur et de la haine.','',26972),
(75708,'frFR','L’une après l’autre, je les ai vaincues, et je les ai enfouies au plus profond de la terre.','',26972),
(75709,'frFR','Elles y sont restées…','',26972),
(75710,'frFR','Pendant dix mille ans… cachées aux yeux de tous par la brume qui recouvrait alors la Pandarie.','',26972),
(75711,'frFR','Lorsque le Cataclysme se produisit, je décidai qu’il était temps de nous séparer de la brume… et d’aider à la guérison de notre monde brisé.','',26972),
(75712,'frFR','Mais quand vos vaisseaux de guerre se sont échoués sur nos côtes, mes doutes et mes craintes ont ressurgi, la terre allait souffrir une nouvelle fois.','',26972),
(75713,'frFR','Vous avez triomphé des ténèbres que j’avais refoulées.','',26972),
(75714,'frFR','Vous avez montré à la Pandarie la puissance des vrais héros.','',26972),
(75715,'frFR','Mais la question reste posée… Pourquoi nous battons-nous ?','',26972),
(75716,'frFR','Affrontez vos peurs. Apaisez vos haines.','',26972),
(75717,'frFR','Trouvez la paix intérieure, pour que vous puissiez la partager avec le monde qui vous entoure.','',26972),
(75718,'frFR','Ce sont là les plus grands trésors de la vie.','',26972),
(75719,'frFR','Et ils valent certainement… la peine de se battre.','',26972),
(75726,'frFR','J’ai rapporté vos faits d’arme au chroniqueur, $gchampion:championne;. Voulez-vous entendre votre histoire ?','',26972),
(75772,'frFR','Votre majesté, c’est chose faite. Les ténèbres contre lesquelles vous luttiez autrefois ont été chassées de la Pandarie pour toujours.','',26972),
(75773,'frFR','Mais à quel prix… à quel terrible prix.','',26972),
(75776,'frFR','Ces étrangers ont semé le chaos sur nos terres. Pouvons-nous leur en confier la cicatrisation ?','',26972),
(75791,'frFR','','Avec les compliments de Gul’dan.',26972),
(75797,'frFR','Vous le savez désormais : se battre par peur ou par colère, c’est livrer une guerre sans fin.','',26972),
(75813,'frFR','Hé hé hé ha ha ha ha !','',26972),
(75814,'frFR','Allez les gars, montrons-leur comment se bat la compagnie Boîte-Noire !','',26972),
(75821,'frFR','CONTEMPLEZ MON GLORIEUX DESTIN !','',26972),
(75872,'frFR','','Désolée, je dois y aller !',26972),
(75873,'frFR','','Ils font de leur mieux, Kavan. Ne sois pas méchante.',26972),
(75874,'frFR','','Sooli, ÉCARTE-TOI !',26972),
(75875,'frFR','','Notre premier ennemi ! Les éventreurs illusoires ne sont que des combattants ordinaires. Occupons-nous-en !',26972),
(75876,'frFR','','Des mande-flammes illusoires ! Faites attention où vous marchez ! Ne restez pas dans la lave !',26972),
(75877,'frFR','','Je suis vaincue ! … Réessayons !',26972),
(75878,'frFR','','Oh non ! Vous avez oublié de vous soigner ?',26972),
(75879,'frFR','','Les illusions ne retiendront pas leurs coups, cette fois. Leurs attaques seront sans pitié. Préparez-vous à utiliser vos meilleurs sorts de soins.',26972),
(75880,'frFR','Oh aïe… Bip-Bip, à l’aide !','',26972),
(75881,'frFR','Hein ? … OH !','',26972),
(75882,'frFR','Ah, des tunneliers illusoires. Nous en avons déjà affronté, Bip-Bip et moi. Méfiez-vous d’eux, ils peuvent s’enterrer, ressurgir soudainement sous une nouvelle cible et CRAC ! Ha ha !','',26972),
(75883,'frFR','Aaaargh… Promettez-moi… Prenez soin de… Bip-Bip.','',26972),
(75884,'frFR','Ces illusions n’en finissent pas, mais nous tiendrons aussi longtemps que nous pourrons !','',26972),
(75885,'frFR','Ha ha ! Tout le monde a fait de l’excellent travail ! Vous, allez donc voir Rotun pour passer à l’épreuve suivante.','',26972),
(75933,'frFR','Il y a bien longtemps, le Serpent de jade m’apprit à purifier mon esprit et à ne faire qu’un avec la terre, et mes doutes furent vaincus.','',26972),
(75934,'frFR','Lorsque mon périple débuta, je n’avais pas conscience de ma force. Le Tigre blanc m’enseigna comment la contrôler, et ma haine, ma colère et ma violence furent vaincues.','',26972),
(75935,'frFR','La Grue rouge vit l’espoir en moi, et m’apprit l’introspection. Malgré l’abattement qui se lisait sur mon visage, je trouvai l’espoir, et le désespoir fut vaincu.','',26972),
(75936,'frFR','Face à une grande peur, le Buffle noir m’enseigna la robustesse. Elle persista malgré la terreur et les ténèbres, et la peur fut vaincue.','',26972),
(75937,'frFR','Vous avez enduré l’épreuve de la sagesse, et suivi la voie du Serpent de jade. J’espère que vous aurez appris cette leçon, tout comme moi.','',26972),
(75938,'frFR','Vous avez enduré l’épreuve de la force, et suivi la voie du Tigre blanc. Retenez cette leçon, toujours.','',26972),
(75939,'frFR','Vous avez enduré l’épreuve de l’espoir, et suivi la voie de la Grue rouge. Qu’elle guide chacun de vos pas.','',26972),
(75940,'frFR','Vous avez enduré l’épreuve de la robustesse, et suivi la voie du Buffle noir. Qu’il bénisse votre passage.','',26972),
(75956,'frFR','','À l’aide ! Débarrassez-moi de ces choses !',26972),
(75957,'frFR','','Ne restez pas là ! Éloignez-vous du feu !',26972),
(75958,'frFR','','Des éventreurs illusoires approchent. Ils ne devraient pas poser trop de problèmes, ce ne sont que des sbires sans cervelle.',26972),
(75959,'frFR','','Préparez votre défense, voilà un conquérant illusoire ! Quand ils sont enragés, ils deviennent très fort et rien ne peut plus les arrêter !',26972),
(75960,'frFR','','Un nouvel ennemi, des mande-flammes illusoires. Ils lancent des boules de feu et crachent de la lave. Utilisez leur lave à votre avantage, elle peut brûler les autres illusions !',26972),
(75961,'frFR','','Faites attention, les gardes ailés illusoires peuvent vous renverser grâce à leurs ailes. Quand vous serez par terre, ils se tourneront contre moi !',26972),
(75962,'frFR','','Des embusqués illusoires ! Attirez vite leur attention et tenez-les éloignés de moi pour qu’ils ne puissent pas m’atteindre avec leurs bananes dévastatrices !',26972),
(75963,'frFR','','Des fourrageurs illusoires nous attaquent ! Ne vous laissez pas leurrer par leur joli minois, ils peuvent infliger de terribles dégâts quand ils sont coordonnés.',26972),
(75964,'frFR','','Rha, je ne peux pas soigner une si grande quantité de dégâts ! C’est bien votre armure la plus lourde ?!',26972),
(75965,'frFR','','Je suis au tapis ! Peut-être que je devrais apporter plus d’herbes de soins la prochaine fois.',26972),
(75966,'frFR','','Bonjour, je suis Sikari, maîtresse de l’éclair de jade, du chi et des brumes de soin. Lors de cette épreuve, vous devrez me protéger des illusions qui attaquent pendant que je vous soigne et que je détruis les ennemis.',26972),
(75967,'frFR','','Je vous salue de nouveau. Notre prochaine épreuve sera plus difficile. Préparez-vous à me défendre !',26972),
(75968,'frFR','','Une fois de plus, vous allez devoir me défendre. Rotun, donnez-nous une vraie épreuve, cette fois !',26972),
(75969,'frFR','','Même si notre fin est inévitable, essayons d’entraîner autant d’ennemis que nous pouvons dans notre chute. Soyez sur vos gardes !',26972),
(75976,'frFR','','Un assassin !',26972),
(76063,'frFR','Merci… empereur. Merci.','',26972),
(76100,'frFR','','Khadgar, il y a quelqu’un !',26972),
(76139,'frFR','Reposez en paix, noble mère. Vous serez vengée.','Reposez en paix, noble mère. Vous serez vengée.',26972),
(76148,'frFR','La curiosité est un vilain défaut…','',26972),
(76149,'frFR','L’œil, qu’est-ce que tu regardes comme ça ?','',26972),
(76150,'frFR','Razuun, tu resteras ici. J’ai d’autres projets pour… qu’est-ce que c’est ?','',26972),
(76151,'frFR','J’ai seulement besoin de son énergie illimitée.','',26972),
(76152,'frFR','Ce sera fait, seigneur Gul’dan.','',26972),
(76154,'frFR','Vous savez ce qu’il vous reste à faire.','',26972),
(76155,'frFR','Retrouvez-moi à l’Escalier dérobé quand votre tâche sera accomplie… si vous êtes toujours en vie après ça.','',26972),
(76178,'frFR','','Ah ! Sacrée chevauchée !',26972),
(76179,'frFR','','Salutations, héros. Une chose infecte est cachée dans le sous-sol de cette ville.',26972),
(76180,'frFR','','Ah, ça m’a l’air dangereux. Allons-y, les gars, et montrons-leur ce dont on est capable.',26972),
(76181,'frFR','','C’est une terrible machine que voilà. Faites attention à vous, héros.',26972),
(76182,'frFR','Eh bien, qu’avons-nous là ?','',26972),
(76183,'frFR','Alors comme ça, Garrosh pense pouvoir rouler Geignard dans la farine, hein ?','',26972),
(76184,'frFR','Allons-y, les gars, c’est pas de l’ingénierie gobeline, ça vaut rien, ça.','',26972),
(76185,'frFR','C’est pas si nul, en fait. Je devrais aller voir, hum, comment vont les autres.','',26972),
(76547,'frFR','J’adore les shorts ! C’est idéal, par ce temps !','J’adore les shorts ! C’est idéal, par ce temps !',26972),
(76549,'frFR','N’y allez pas trop fort avec moi !','',26972),
(76550,'frFR','Votre mascotte est tombée !','',26972),
(76551,'frFR','Boouuh ! C’est injuste !','',26972),
(76552,'frFR','Ouais ! Je suis le meilleur !','',26972),
(76877,'frFR','Levez-vous, mes vieux amis. Il est temps de passer à la prochaine étape du plan.','',26972),
(76878,'frFR','Teron’gor, infiltre les Auchenaï et prends le contrôle d’Auchindoun. Saigne-les à blanc.','',26972),
(76879,'frFR','Cho’gall, nous allons conclure ensemble nos affaires sur la crête de Givrefeu.','',26972),
(76881,'frFR','Je t’envoie en Nagrand pour asservir le naaru d’Oshu’gun.','',26972),
(76904,'frFR','Hurlenfer !','',26972),
(76905,'frFR','L’attaque que vous avez lancée contre Karabor était aussi lâche qu’injustifiée.','',26972),
(76906,'frFR','Qui plus est, sur le champ de bataille, nous avons fait du petit bois de vos Orcs.','',26972),
(76907,'frFR','J’aurais donc tous les droits de vous décapiter et de faire raser cette ville…','',26972),
(76908,'frFR','… mais je m’abstiendrai. Aujourd’hui, nous serons magnanimes. Remballez vos engins de guerre et quittez les lieux.','',26972),
(76975,'frFR','Teron’gor, nous allons nous occuper ensemble d’Ombrelune.','',26972),
(76976,'frFR','Va en Talador. Infiltre-toi parmi les Auchenaï. Prends le contrôle d’Auchindoun. Saigne-les à blanc.','',26972),
(76979,'frFR','Cho’gall, je t’envoie en Nagrand.','',26972),
(76982,'frFR','Tu vas asservir le naaru mourant qui se trouve au cœur d’Oshu’gun.','',26972),
(76983,'frFR','Giselda, toi tu restes ici. J’ai d’autres projets pour… Qu’est-ce que c’est, dans mon dos ?','',26972),
(77104,'frFR','Faites passer le mot au reste de la meute : nous avons trouvé les fils du Loup de Fer. Lok’tar ogar !','',26972),
(77105,'frFR','Mon… père… me venger…','',26972),
(77107,'frFR','Ton père versera des larmes aussi amères que les miennes.','',26972),
(77140,'frFR','','La Horde de Fer approche. Pas de mouvements brusques.',26972),
(77148,'frFR','','Throm-Ka, commandant Vorka. Le clan Ombrelune est honoré de votre présence.',26972),
(77149,'frFR','Des chamans, des femmes… <crache>. Je n’ai pas de temps à perdre avec des voyants et des mystiques.','',26972),
(77150,'frFR','Où sont vos véritables guerriers ? À moins que la réputation des Ombrelunes soit fondée ?','',26972),
(77151,'frFR','N’êtes-vous donc qu’une bande de pleutres terrés derrière leur magie ?','',26972),
(77153,'frFR','Écartez-vous, mes frères. Nous devons parler à Hurlenfer.','',26972),
(77154,'frFR','Personne ne peut entrer dans la ville. Pas même vous, chaman.','Personne ne peut entrer dans la ville. Pas même vous, chaman.',26972),
(77155,'frFR','Thrall ? Varok ? Que venez-vous faire par ici ?','',26972),
(77156,'frFR','Force et honneur, général. Nous sommes venus parler à Garrosh. Nous espérons toujours que la paix est possible.','',26972),
(77157,'frFR','Mais…','Mais…',26972),
(77158,'frFR','Kor’krons ! Vous êtes requis au front !','',26972),
(77159,'frFR','MAINTENANT !','',26972),
(77160,'frFR','Vous savez que je ne peux garantir votre sécurité… ou la réponse de Garrosh.','',26972),
(77161,'frFR','Lok’tar Ogar, mes frères.','',26972),
(77163,'frFR','','Quoi ? Je vais vous en donner, moi, du pleutre !',26972),
(77164,'frFR','Attendez. Je ne tiens pas à faire couler votre sang aujourd’hui, Hara.','',26972),
(77165,'frFR','Je vois que votre clan n’a rien perdu de sa fierté, ni de l’esprit guerrier qui l’anime !','',26972),
(77166,'frFR','','<Plisse un peu les yeux, mais se détend.>',26972),
(77167,'frFR','','Fort bien. Vorka, fils de Vorash, le clan Ombrelune accepte de rejoindre la Horde de Fer.',26972),
(77168,'frFR','','Lok-Regar. Quels sont les ordres ?',26972),
(77169,'frFR','Rassemblez votre clan. La Horde de Fer écrasera bientôt définitivement Karabor !','',26972),
(77170,'frFR','','Zog-zog.',26972),
(77192,'frFR','','Our paths diverge here. Good luck, champion.',26972),
(77193,'frFR','[VO6.0.1] Hatock, fils du Loup de Fer ! Je viens chercher votre tête.','',26972),
(77194,'frFR','Regardez un peu ça, les gars… Le fils bâtard de Garad nous revient d’entre les morts.','',26972),
(77195,'frFR','Har har har ! Tu aurais dû continuer à faire le mort, Ga’nar. T’aurais survécu plus longtemps.','',26972),
(77196,'frFR','Si Garad avait rejoint la Horde de Fer comme nous le lui avions demandé, votre papa chéri serait encore là pour vous sauver la mise.','',26972),
(77197,'frFR','[VO6.0.1] Choisissez vos derniers mots avec soin, Hatock. Aucun Sire-Tonnerre ne sera jamais à ma hauteur.','',26972),
(77198,'frFR','C’est vrai que vos loups font de bons combattants dehors, mais voyons comment vous vous en sortez à l’ombre d’un gronn.','',26972),
(77199,'frFR','Sire-Tonnerre… LÂCHEZ LA BÊTE !','',26972),
(77200,'frFR','Ne lâchez pas ces chaînes.','',26972),
(77201,'frFR','Il arrive à bouger son bras ! Ne lui laissez pas de mou, ou il vous enverra tous dans le décor.','',26972),
(77202,'frFR','Allez, on y met toutes ses forces !','',26972),
(77203,'frFR','Nous avons des délais à tenir.','',26972),
(77215,'frFR','Hatock, fils du Loup de Fer ! Je viens chercher ta tête.','',26972),
(77232,'frFR','Un problème, Ga’nar ? C’est le gronn qui t’inquiète ?','',26972),
(77233,'frFR','Et moi qui prenais les Loups-de-Givre pour des combattants d’exception.','',26972),
(77234,'frFR','Pas facile de combattre un Sire-Tonnerre, pas vrai ?','',26972),
(77236,'frFR','Les chevaucheurs de chiens ne font pas le poids contre moi !','',26972),
(77237,'frFR','Si tu avais rejoint la Horde de Fer, je ne serais pas obligé de te tuer.','',26972),
(77240,'frFR','Hatock ! Tu ne peux pas m’échapper !','',26972),
(77327,'frFR','Loups-de-Givre, déployez-vous et cernez les Sire-Tonnerre. L’heure de la vengeance a sonné !','',26972),
(77375,'frFR','Honorables frères et sœurs ! Aujourd’hui, nous avons accompli l’exploit que Durotan refusait même d’envisager !','',26972),
(77376,'frFR','Ne vous y trompez pas. Nous sommes en guerre. C’est un chef de guerre qu’il nous faut !','',26972),
(77377,'frFR','Ceux d’entre vous qui ont assez de courage pour me suivre, venez ! Nous allons montrer au monde la puissance des Loups-de-Givre !','',26972),
(77378,'frFR','Nous… sommes… les… LOUPS-DE-GIVRE !','',26972),
(77398,'frFR','','This is the Arbitum.',26972),
(77399,'frFR','','The Prophet foresaw a time in our future when our people would come into grave danger.',26972),
(77400,'frFR','','This shrine holds the power to save us from destruction.',26972),
(77401,'frFR','','I pray that the day of judgment shall never come. Power like this can only come at great cost.',26972),
(77402,'frFR','','Activation of The Arbitum requires an incredible amount of energy - energy of a kind that can\'t be found on this world.',26972),
(77403,'frFR','','Luckily, Iris Crystals do not originate from Draenor. We think three should be enough to supply the energy we need.',26972),
(77404,'frFR','','Five Iris Crystals have fallen from the skies around Shadowmoon Valley.',26972),
(77405,'frFR','','Unfortunately, it looks like the Shadowmoon are collecting them as well. We cannot allow them to succeed.',26972),
(77406,'frFR','','This is the Prophet\'s vision of what will come to pass.',26972),
(77407,'frFR','','Do you know the workings of our magic, traveler?',26972),
(77408,'frFR','','See this hammer? In my hands, it strikes with magical force against enemies. But used by an inexperienced trainee, it is no more than a blunt rock.',26972),
(77409,'frFR','','The Arbitum is only as powerful as the one who uses it.',26972),
(77410,'frFR','','In the right hands, it restores hope for this world. In the wrong ones, it is a weapon of absolute destruction.',26972),
(77478,'frFR','Esprits de l’eau, montrez-moi le chemin. Esprits de la terre, faites-moi don de votre force.','',26972),
(77479,'frFR','Je… j’entends la voix d’une Fureur !','',26972),
(77489,'frFR','Volons ensemble. Nous les aiderons depuis les airs !','',26972),
(77490,'frFR','La lumière purificatrice des naaru sera notre marteau et notre bouclier.','',26972),
(77491,'frFR','Ils sont devant les portes du temple… Approchons-nous ! Vite !','',26972),
(77492,'frFR','Poursuivons. Nous devons libérer les marches.','',26972),
(77493,'frFR','[VO6.0.1] Méfiez-vous des embusqués. Surveillez vos flancs !','',26972),
(77494,'frFR','[VO6.0.1] En avant ! Par la Lumière des naaru !','',26972),
(77495,'frFR','Jamais plus vos hordes d’Orcs ne feront vaciller la Lumière de Karabor !','',26972),
(77496,'frFR','Intensifiez l’attaque. Par la Lumière des Naaru !','',26972),
(77498,'frFR','','Attention ! Des gorens !',26972),
(77502,'frFR','Esprits du feu, donnez-moi la férocité… Aaaaaah !','',26972),
(77503,'frFR','Attendez ! Ce n’est pas notre ennemi.','',26972),
(77504,'frFR','','Drek’Thar ! Couvre-moi.',26972),
(77505,'frFR','','Eh bien entends-la plus vite ! On se fait submerger en bas.',26972),
(77548,'frFR','','Laissez votre loup vous guider, Drek’Thar, et restez près de moi si vous le pouvez. $p, quand vous en aurez fini, retrouvez-nous à la Forgeglace. Lok’tar ogar !',26972),
(77569,'frFR','','Pendant bien des années, Rulkan était la plus fidèle conseillère de Ner’zhul. La force et l’ambition du chef régissaient nos vies, mais la sagesse et la perspicacité de Rulkan inspiraient nos esprits.',26972),
(77570,'frFR','','Ner’zhul emploie des méthodes brutales et directes. Il terrasse ses ennemis par la force.$B$BRulkan est sage et rusée. Elle est capable de retourner les propres armes de l’ennemi contre lui-même.',26972),
(77571,'frFR','','Le clan Ombrelune n’existe plus. Même s’il en reste quelques vestiges, son esprit a été corrompu.',26972),
(77572,'frFR','','Nous nous sommes exilés de nous-mêmes, après avoir refusé la magie de l’Étoile noire de Ner’zhul.',26972),
(77573,'frFR','','Nul ne sait ce que l’avenir nous réserve, mais une chose est certaine. Ma loyauté envers Rulkan est infaillible.',26972),
(77586,'frFR','Draka, aide-moi à me lever. Nous dev… hrraarh !','',26972),
(77587,'frFR','Mon enfant, n’oubliez pas que l’un de nous est aveugle et ne peut plus invoquer les esprits.','',26972),
(77588,'frFR','','Bah ! Ça rendra juste le combat un peu plus équitable. Debout, vieil homme.',26972),
(77589,'frFR','Quelles sont nos chances face à un adversaire capable de réduire jusqu’aux éléments à néant ?','',26972),
(77590,'frFR','','Il y a longtemps de cela, vous m’avez enseigné que les éléments avaient toujours été là pour nous. Aujourd’hui, c’est à nous d’être là pour eux. La victoire ou la mort… Nous leur devons bien ça.',26972),
(77593,'frFR','%s grogne en signe d’assentiment.','',26972),
(77595,'frFR','$C ! Vous avez libéré mes enfants et m’avez rendu mon intégrité. Avec ma bénédiction, vous allez pouvoir déchaîner la Fureur de Givrefeu contre vos ennemis.','',26972),
(77596,'frFR','Vous seul vous êtes montré suffisamment maître de votre art pour entendre mon appel, chaman, et vous avez su quoi faire. Donnez-moi votre totem.','',26972),
(77602,'frFR','Que rayonnent les flammes de la fureur !','',26972),
(77604,'frFR','On a toujours cru qu’Exurotus était une légende ; un conte symbolisant la nature d’un véritable esprit élémentaire, qui se transmettait entre chamans.$b$bVoir une entité aussi vénérable asservie de la sorte est un crachat à la face des Orcs, du chamanisme, et un affront personnel.','',26972),
(77609,'frFR','Les relents de la roche mise au supplice m’agressent les narines, Draka. Que voyez-vous ?','',26972),
(77610,'frFR','Je sens la présence de gorens par centaines, en train de creuser. Ça ne va pas être simple.','',26972),
(77612,'frFR','','Des gorens… en grand nombre. Nous allons faire diversion pour vous permettre de vous infiltrer dans la Forgeglace.',26972),
(77613,'frFR','Votre idée devrait effectivement permettre de soumettre un forgeron, mais pas plus de quelques secondes à la fois.','',26972),
(77681,'frFR','Esprits du vent, entendez mon appel ! Nous avons besoin de votre sagesse.','',26972),
(77705,'frFR','Ce n’est pas le genre d’endroit que les Loups-de-Givre ont l’habitude de fréquenter. Méfiez-vous des ombres qui vous entourent.','',26972),
(77750,'frFR','','J’ai prêté serment. Nous sommes toujours là où le devoir nous appelle. Redresseurs de torts, avec moi !',26972),
(77751,'frFR','','Hmmm… oui, c’est un argument imparable. Redresseurs de torts, avec moi !',26972),
(77754,'frFR','Viens, mon enfant. Réfugie-toi près de mon totem.','',26972),
(77757,'frFR','Tout ce monde ? Fort bien. Quand le prophète lance un appel, les Rangari y répondent. Suivez-moi, soldats ! Velen a besoin de notre aide !','',26972),
(77758,'frFR','J’ai foi en la sagesse de Velen. Après tout, il est quand même le prophète de mon peuple. Suivez-moi, soldats !','',26972),
(77764,'frFR','C’est fait ? Fort bien. Quand cette bataille touchera à son terme, nous devrons songer à remettre en état les véritables défenses de Karabor.','',26972),
(77769,'frFR','Les anachorètes vous sont très redevables, $gétranger:étrangère;. Nous nous reverrons au point de ralliement.','',26972),
(77792,'frFR','Portez ce témoignage de ma gratitude au combat, et le feu qui l’habite se joindra au vôtre pour vous aider à réduire vos ennemis en cendres.','',26972),
(77793,'frFR','Nous sommes seuls en mesure de récupérer ces fragments et de libérer la Fureur.','',26972),
(77840,'frFR','Ta vigilance s’est relâchée, chef. J’ai surpris ces espions rangari entre tes murs.','',26972),
(77841,'frFR','Ils arrivent trop tard. Les prisonniers sont déjà en route pour la forteresse de l’Angoisse.','',26972),
(77842,'frFR','Leur sang me permettra d’invoquer l’Étoile noire et m’élèvera au rang de dieu parmi la Horde de Fer !','',26972),
(77843,'frFR','Le chef de guerre récompense les actes, exhalombre, pas les mots.','',26972),
(77844,'frFR','Bloquez les sorties du village ! Aucun Draeneï ne doit sortir d’ici vivant.','',26972),
(77848,'frFR','Sire-Tonnerre… J’ai échoué…','',26972),
(77855,'frFR','','Mon époux…',26972),
(77856,'frFR','Ça suffit ! Gardez donc votre temple, vermines de Draeneï… ce n’est que partie remise.','',26972),
(77857,'frFR','La Horde de Fer reviendra !','',26972),
(77858,'frFR','Je vais me mettre en route et trouver un point adéquat pour y organiser notre contre-attaque.','',26972),
(77881,'frFR','Ces Orcs ont profané le sol sacré de Karabor. Leur attaque doit cesser SUR l’HEURE !','',26972),
(77882,'frFR','Puisse la Lumière éclairer notre chemin !','',26972),
(77883,'frFR','Karabor ki’le !','',26972),
(77884,'frFR','Karabor ki’le !','Karabor ki’le !',26972),
(77885,'frFR','Aréphéon ! Nous avons besoin d’un tir de couverture !','',26972),
(77886,'frFR','Rangari ! Préparez-vous à tirer…','',26972),
(77887,'frFR','FEU À VOLONTÉ !','',26972),
(77888,'frFR','Artificiers, occupez-vous de ces chars !','',26972),
(77889,'frFR','Fort bien, grand prophète.','',26972),
(77890,'frFR','Akama, Taalo ! Montrez-leur de quel bois les Draeneï se chauffent !','',26972),
(77895,'frFR','$n, vous venez avec moi.','',26972),
(77999,'frFR','[VO6.0.1] Yes... Very good. Around Shadowmoon Valley are four arkonite crystals, ancient wreckage from our vessel.','',26972),
(78000,'frFR','[VO6.0.1] I thought we would never need their power, but the time has come. Take my staff, and gather their energy for me.','',26972),
(78001,'frFR','[VO6.0.1] All right, give me one moment...','',26972),
(78005,'frFR','Des ennemis sont encore infiltrés parmi nous. TOUS AUX ARMES !','',26972),
(78061,'frFR','Vous devez vaincre le commandant Vorka. C’est lui, là-bas, au pied des marches du temple.','',26972),
(78062,'frFR','Avec plaisir ! Redresseurs de torts, suivez-moi ; on passe à l’action !','',26972),
(78090,'frFR','Voilà un petit orc bien en colère !','',26972),
(78091,'frFR','Tellement aveuglé par la rage qu’il s’en prend seul à mes ogres.','',26972),
(78092,'frFR','Ils vont te massacrer, petit loup solitaire.','',26972),
(78093,'frFR','Ton clan remplira bientôt mes enclos à esclaves…','',26972),
(78113,'frFR','Je te noierai dans le sang de ta misérable armée !','',26972),
(78142,'frFR','Je vais conduire ces Orcs en sûreté et je vous retrouverai dehors avec Gol’kosh.','',26972),
(78159,'frFR','Libérez-moi et j’irai parler à votre chef-loup.','',26972),
(78160,'frFR','Allons-y.','Allons-y.',26972),
(78161,'frFR','Je me sens… mieux ! Vous avez fait le bon choix ! Voyons maintenant ce que votre chef-loup a à dire.','',26972),
(78180,'frFR','Le siège est brisé ! Maintenant, mes frères et mes sœurs, il est temps de chasser ces Orcs de Karabor !','',26972),
(78221,'frFR','Ce jour ne sera pas celui où Karabor est tombée.','',26972),
(78226,'frFR','Vous ne mourrez pas aujourd’hui !','Vous ne mourrez pas aujourd’hui !',26972),
(78227,'frFR','La Lumière guérira vos blessures !','La Lumière guérira vos blessures !',26972),
(78228,'frFR','La Lumière protège ses champions.','La Lumière protège ses champions.',26972),
(78229,'frFR','Merci, noble défenseur. Je vous attendrai à la clairière Crépusculaire.','Merci, noble défenseur. Je vous attendrai à la clairière Crépusculaire.',26972),
(78273,'frFR','Attention ! Au feu !','Attention ! Au feu !',26972),
(78297,'frFR','Aaarrrghh !','Aaaaaargh !',26972),
(78298,'frFR','Non, Ga’nar. Nous sommes encerclés et à découvert. Nous devons renforcer notre position.','',26972),
(78299,'frFR','Toujours aussi téméraire…','',26972),
(78301,'frFR','O’re atal’sha ! Pour la Lumière !','O’re atal’sha ! Pour la Lumière !',26972),
(78302,'frFR','Nous ne nous soumettrons pas !','Nous ne nous soumettrons pas !',26972),
(78303,'frFR','Chargez ! Pour Karabor !','Chargez ! Pour Karabor !',26972),
(78336,'frFR','Il y a beaucoup à faire. Taalo, veillez à ce que les soldats reçoivent des soins et prennent du repos.','',26972),
(78391,'frFR','','Argh ! Il a essayé de me planter ! J’avais pourtant bien dit qu’on ne pouvait pas se fier aux Crânes-Ricanants.',26972),
(78392,'frFR','Fouettard a oublié ses bonnes manières. J’ai vu joulie petite Orque. J’ai voulu voir si elle savait danser. Désolé… désolé.','',26972),
(78393,'frFR','Je suis venu chasser la Horde de Fer. Je pourrais détruire ce qui reste de ton village, ou nous pourrions nous entraider.','',26972),
(78394,'frFR','Oui, les loups et les crânes ont besoin les uns des autres. Vous, vous voulez savoir où est la grosse arme de la Horde de Fer. Et nous, on veut votre $p.','',26972),
(78396,'frFR','Vous avez prouvé votre loyauté envers mon clan ainsi que votre efficacité.','',26972),
(78397,'frFR','Notre emprise sur la forteresse de Flèchelame est fragile et certains de mes meilleurs guerriers sont partis avec mon frère.','',26972),
(78398,'frFR','J’ai été très impressionné par votre talent au combat face à Dorogg le Brutal.','',26972),
(78399,'frFR','Je serais honoré si vous acceptiez de continuer à vous battre à nos côtés.','',26972),
(78464,'frFR','Je vais faire en sorte que le temple ne subisse plus de dégâts.','',26972),
(78465,'frFR','Allez-y, $n. Je me charge de tenir les portes du temple !','',26972),
(78487,'frFR','Attention !','',26972),
(78574,'frFR','','Dispersez-vous ! Tuez tout ce qui bouge !',26972),
(78809,'frFR','Alors, allons-y !','',26972),
(78810,'frFR','Laissez-moi juste faire chauffer un peu le moteur.','',26972),
(78811,'frFR','Allez, mon bébé…','',26972),
(78812,'frFR','Et voilà !','',26972),
(78813,'frFR','Par ici. Il y a un endroit sûr plus loin, juste en dehors des installations de la Horde de Fer.','',26972),
(78814,'frFR','J’imagine que la priorité, c’est de s’occuper de cet affreux canon géant ?','',26972),
(78815,'frFR','Quelqu’un a dit « canon géant » ?','',26972),
(78816,'frFR','C’est prévu. Mais la priorité, c’est de retrouver Yrel. Elle est là, quelque part.','',26972),
(78817,'frFR','D’kaan, vous et votre $gchampion:championne; êtes partis en reconnaissance, tout à l’heure. Qu’avez-vous trouvé ?','',26972),
(78818,'frFR','…Rien de concluant, redresseur de torts.','',26972),
(78819,'frFR','Je vois. Eh bien, nous n’avons qu’à…','',26972),
(78839,'frFR','Je vais envoyer des artificiers sécuriser les cristaux au nord.','',26972),
(78840,'frFR','[VO6.0.1] And what of Ner\'zhul? Will we let him take our people without retribution?','',26972),
(78841,'frFR','[VO6.0.1] Patience, Maraad. A rescue will require planning - do not rush into danger until we know where our people are.','',26972),
(78842,'frFR','[VO6.0.1] We made the wrong choice once before. I won\'t let it happen again. I can\'t leave our people to die.','',26972),
(78843,'frFR','','[VO6.0.1] I will keep an eye on him, teacher.',26972),
(78850,'frFR','','Lorsque la Horde de Fer est arrivée, elle a offert un choix à notre clan : la rejoindre, ou mourir.',26972),
(78851,'frFR','','Mon mari, Ner’zhul, a décidé de sauver son peuple. Il a rejoint la Horde de Fer, mais a dû en payer le prix fort.',26972),
(78852,'frFR','','Ils lui ont dit :',26972),
(78853,'frFR','','Alors Ner’zhul s’est tourné vers le Néant. Il a enfreint les anciennes lois et invoqué l’Étoile noire.',26972),
(78854,'frFR','','Je l’ai supplié d’arrêter, mais il a refusé de m’écouter.',26972),
(78855,'frFR','','En brisant cette pierre, il a trahi nos ancêtres et renié notre histoire.',26972),
(78856,'frFR','','Je n’ai qu’une chose à vous demander, $gétranger:étrangère;.',26972),
(78857,'frFR','','Vous devez réussir là où j’ai échoué. Arrêtez Ner’zhul. Mettez un terme à sa folie, avant qu’il ne soit trop tard.',26972),
(78935,'frFR','','Beau travail, $p ! Retrouvez-nous à l’endroit convenu. On va voir comment contrôler cette bête.',26972),
(79155,'frFR','Que valent les étoiles et les visions face à l’acier et à la poudre ? Fais une offrande intéressante, ou ton peuple mourra.','',26972),
(79164,'frFR','','La forteresse d’Ombrelune est impénétrable en temps normal, mais cette clé vous permettra d’y entrer. Bonne chance.',26972),
(79229,'frFR','Ner’zhul ! Ton armée est en déroute, ta forteresse en ruines.','',26972),
(79230,'frFR','Ton « Étoile noire » est tombée et sert maintenant les Draeneï. Tu es la honte de notre race !','',26972),
(79231,'frFR','Hurlenfer, nous pouvons continuer de servir la Horde de Fer. Notre magie est encore…','',26972),
(79232,'frFR','TU N’AS PAS TA PLACE DANS MA HORDE DE FER ! Retourne dans ton misérable village, Ner’zhul, et regarde les étoiles pendant que la Vague de Fer déferle sur toi.','',26972),
(79233,'frFR','Retourne dans ton misérable village, Ner’zhul, et regarde les étoiles pendant que la Vague de Fer déferle sur toi.','',26972),
(79234,'frFR','Korhol, Zhakta, Trokar… déployez-vous. Gargrak, pour l’instant, tiens ta position.','',26972),
(79235,'frFR','ZHAKTA… NON… je jure de te venger !','',26972),
(79237,'frFR','NOOON ! Gargrak, vas-y… le chaman aveugle doit mourir.','',26972),
(79239,'frFR','REPLI ! NOUS REVIENDRONS, LOUPS-DE-GIVRE !','',26972),
(79317,'frFR','Kalandrios, j’aimerais assister de nouveau au rituel du Lien.','Kalandrios, j’aimerais assister de nouveau au rituel du Lien.',26972),
(79319,'frFR','','De la magie de lâche !',26972),
(79335,'frFR','La Horde de Fer se dirige vers le temple de Karabor. L’attaque a com--','',26972),
(79336,'frFR','Attendez… C’est quoi, cette lumière ?','',26972),
(79377,'frFR','Reculez !','',26972),
(79379,'frFR','Il semble que les éléments ne me répondent pas de la même manière sur Draenor que sur Azeroth…','',26972),
(79380,'frFR','Partez devant. Durotan vous attend. Je dois reprendre mon souffle.','',26972),
(79388,'frFR','À Flèchelame ! Aux armes !','',26972),
(79389,'frFR','Il n’y a pas de temps à perdre ! Nous devons frapper MAINTENANT !','',26972),
(79397,'frFR','Dorogg est tombé ! Ne laissez pas la victoire vous ramollir, mes frères !','',26972),
(79400,'frFR','Intensifiez l’attaque !','',26972),
(79401,'frFR','Les Loups-de-Givre triompheront.','',26972),
(79402,'frFR','Cette forteresse tombera.','',26972),
(79403,'frFR','N’abandonnez pas !','',26972),
(79404,'frFR','Rassemblez vos forces…','',26972),
(79406,'frFR','Faites rayonner la Lumière, mes frères et sœurs !','',26972),
(79408,'frFR','Ce n’est qu’une égratignure. Je serai vite remis.','',26972),
(79435,'frFR','À vous de jouer maintenant. Je vais rester ici et m’occuper des esclaves blessés que vous avez sauvés.','',26972),
(79437,'frFR','','Ce qui vaut la peine n’est jamais simple.',26972),
(79443,'frFR','Drek’Thar, mon vieil ami, tu es en vie !','',26972),
(79445,'frFR','Je sais que tu as perdu la vue, chaman, mais celui-ci a la peau verte.','',26972),
(79446,'frFR','Hmpff… oui. Ga’nar est déjà en train de faire des siennes.','',26972),
(79447,'frFR','Fort bien, étrangers. Vous avez gagné la confiance de notre chaman. Je ne cracherai pas sur votre aide.','',26972),
(79448,'frFR','Je tiens à peine debout, mais sans l’aide de ces héros, je ne serais plus de ce monde.','',26972),
(79449,'frFR','Des champions venus d’une terre lointaine, et qui ont fait le serment de combattre la Horde de Fer.','',26972),
(79450,'frFR','Je n’ai pas besoin d’yeux pour percevoir la noblesse de leur âme. Ils ont sauvé les nôtres… y compris ton frère.','',26972),
(79451,'frFR','Venez, mes amis. Si vous souhaitez combattre au côté de notre clan, vous êtes dignes de recevoir nos bénédictions.','',26972),
(79452,'frFR','Touchez la pierre chamanique. Acceptez la sagesse de cette terre, et celle de nos glorieux ancêtres.','',26972),
(79458,'frFR','Guerriers ! Aujourd’hui, nous allons renverser la vapeur.','',26972),
(79459,'frFR','Nous allons prendre la citadelle de Flèchelame.','',26972),
(79460,'frFR','Combattez comme un seul orc. Nous allons vaincre… ensemble !','',26972),
(79461,'frFR','Ga’nar est un grand combattant, mais la patience lui fait défaut. Il est parti avec certains de nos meilleurs éléments.','',26972),
(79462,'frFR','Il ne m’écoute jamais. Sa témérité finira par nous attirer des problèmes.','',26972),
(79463,'frFR','Là… la tour de Gor’mas. Nous en ferons notre base. Ne laissez aucun survivant ! LOK’TAR OGAR !','',26972),
(79465,'frFR','Les ogres de Flèchelame m’ont jeté dans ce trou sordide. Je leur fendrai le crâne, jusqu’au dernier ! J’obtiendrai vengeance !','',26972),
(79466,'frFR','[VO6.0.1] La citadelle de Flèchelame ! Pour me venger de ces ogres, je suis prêt à la démonter pierre après pierre.','',26972),
(79468,'frFR','Étrangers, vous méritez d’être accueillis en héros. Je vais vous mener au chef des Loups-de-Givre.','',26972),
(79470,'frFR','Je suis peut-être aveugle, mais il est bon de pouvoir humer cet air familier.','',26972),
(79472,'frFR','Ah, oui. Le fils cadet de Garad : une noble âme du nom de Durotan.','',26972),
(79473,'frFR','Il est sage, mais encore jeune. J’ai peur qu’il ne se soit jeté dans la gueule du gronn… Notre peuple court un grave danger.','',26972),
(79475,'frFR','Tu as parlé du chef des Loups-de-Givre…','',26972),
(79476,'frFR','Durotan !','',26972),
(79482,'frFR','','Le minerai de fomium est plus solide que l’acier durci. Vous aurez besoin de ma pioche en dents de gorens pour briser la roche.',26972),
(79483,'frFR','','Les esprits ont eu la bonté de vous guider jusqu’à moi à point nommé.',26972),
(79484,'frFR','','C’est fait ! La lame est forgée.',26972),
(79487,'frFR','','Vous vous adressez à Na’Shra ! Armurière du clan Loup-de-Givre. Pour vous remercier de votre aide, je vous accorde la mienne.',26972),
(79495,'frFR','Tu es blessé. Ta peau est pâle.','',26972),
(79500,'frFR','La bataille fait rage. Lok-Narash !','',26972),
(79501,'frFR','Des renforts en provenance du sud-ouest. À l’attaque !','',26972),
(79502,'frFR','Ça pue le sanglier. Gare à ses défenses… Chargez !','',26972),
(79503,'frFR','La tour est à nous ! Regroupez-vous et intensifiez l’assaut !','',26972),
(79504,'frFR','Je prends les devants. Loups-de-Givre, tenez la tour. Igrimar, avec moi !','',26972),
(79505,'frFR','Je vais m’arranger pour les ralentir. Lok’tar ogar !','',26972),
(79533,'frFR','Baisse les armes, chef de guerre. C’est fini.','',26972),
(79536,'frFR','… Fenris ?','',26972),
(79579,'frFR','Aucun esclave ne se bat avec la volonté d’un homme libre.','',26972),
(79584,'frFR','Les Sire-Tonnerre battent en retraite ! Ils tentent de rejoindre la Horde de Fer en empruntant le passage du Tonnerre.','',26972),
(79585,'frFR','Ils vont lancer une contre-attaque. Nous devons nous tenir prêts.','',26972),
(79588,'frFR','Je ne comprends pas…','',26972),
(79595,'frFR','Non, je ne serais jamais d’accord avec cela.','',26972),
(79596,'frFR','En route pour le passage du Tonnerre ! Nous sommes cinquante fois moins nombreux qu’eux… Mais ils n’ont aucune chance !','',26972),
(79597,'frFR','[VO6.0.1] Thank you, child. I can always count on you.','',26972),
(79603,'frFR','[VO6.0.1] There! Is this what you seek, Prophet?','',26972),
(79609,'frFR','','Kron approche ! Venez avec moi !',26972),
(79619,'frFR','Si je tente de libérer Exurotus, nous sommes certains de nous attirer le courroux de Kron.','',26972),
(79621,'frFR','Nous avons de la compagnie, maître.','',26972),
(79622,'frFR','Tagar, occupe-toi de $gcet intrus:cette intruse;.','',26972),
(79624,'frFR','Loups-de-Givre ! La Horde de Fer approche. À l’heure où je vous parle, elle marche sur le passage du Tonnerre.','',26972),
(79625,'frFR','Mais le clan Loup-de-Givre est réunifié ! Ensemble, nous protégerons cette terre !','',26972),
(79626,'frFR','Lok-Narash, Loups-de-Givre ! Préparez-vous pour la bataille !','',26972),
(79627,'frFR','Tu me connais, mon frère. Je suis toujours prêt à me battre.','',26972),
(79638,'frFR','Loups-de-Givre, tenez votre position ! Laissez-les venir à vous !','',26972),
(79640,'frFR','À vos haches ! Ils reviennent à la charge !','',26972),
(79641,'frFR','Impossible de combattre sous ces tirs d’artillerie. Occupez-vous de ce char !','',26972),
(79653,'frFR','Drek’Thar a des problèmes. Ga’nar, va lui prêter main-forte.','',26972),
(79655,'frFR','Vous, allez-y aussi et faites en sorte qu’il ne se fasse pas tuer.','',26972),
(79659,'frFR','On se regroupe ! Préparez-vous pour l’attaque suivante !','',26972),
(79661,'frFR','Des lances ! Tenez vos positions !','',26972),
(79665,'frFR','Si besoin, venez près de mon totem !','',26972),
(79667,'frFR','Je t’attends.','',26972),
(79676,'frFR','Loups-de-Givre ! Tenez bon ! La bataille touche à son terme !','',26972),
(79677,'frFR','Drek’Thar ! Combien de temps te faut-il encore ?','',26972),
(79679,'frFR','Nous comptons sur toi, chaman !','',26972),
(79681,'frFR','Oui… quelque chose d’énorme approche.','',26972),
(79683,'frFR','UN GRONN !','',26972),
(79684,'frFR','Loups-de-Givre… chargez ! Abattez ce monstre !','',26972),
(79691,'frFR','Draka, rends-toi dans la grotte que l’éclaireur a repérée. Je vais retrouver le commandant au village côtier.','',26972),
(79692,'frFR','Nous nous retrouverons plus tard, lorsque vous aurez terminé votre mission.','',26972),
(79698,'frFR','','Il faut l’éloigner de Drek’Thar !',26972),
(79706,'frFR','Exurotus est trop faible. Au mieux, je peux le libérer de ses liens, mais la mort ne tardera pas à venir le prendre.','',26972),
(79707,'frFR','Si seulement j’étais plus fort…','',26972),
(79708,'frFR','','Tu peux certainement faire quelque chose.',26972),
(79709,'frFR','La fureur est en train de mourir. Il nous reste peu de temps.','',26972),
(79710,'frFR','Il existe peut-être une solution. Exurotus, j’ouvre mon esprit au tien et lui offre l’asile. Rejoins-moi, et sauvons le feu sacré qui t’anime.','',26972),
(79712,'frFR','MON ÂME… S’EMBRASE !','',26972),
(79713,'frFR','','Drek’Thar, qu’est-ce qu’il t’a fait ?',26972),
(79714,'frFR','Il a fusionné avec la Fureur. Leurs deux esprits ne font plus qu’un.','',26972),
(79716,'frFR','Je… je peux voir. Je perçois le flux des éléments, les mouvements des esprits autour de moi. C’est… c’est magnifique.','',26972),
(79718,'frFR','Les ogres vont nous payer leur dette ; ils vont souffrir !','',26972),
(79736,'frFR','Nous allons sécuriser nos frontières !','Nous allons sécuriser nos frontières !',26972),
(79757,'frFR','Des fleurs ? Noooon !','',26972),
(79758,'frFR','Pas des fleurs… Pitié…','',26972),
(79759,'frFR','Pas à moi ! Pas maintenant !','',26972),
(79760,'frFR','Pas comme ça…','',26972),
(79761,'frFR','Ainsi, les légendes disent vrai…','',26972),
(79762,'frFR','Tout sauf des fleurs !','',26972),
(79764,'frFR','Des fleurs ?','',26972),
(79782,'frFR','','Ainsi, les loups veulent jouer avec les crânes ? Je parlerai à Durotan, mais j’ai peu d’espoir. Ses loups sont faibles et manquent d’ardeur.',26972),
(79788,'frFR','Haaaa ! Pitié ! Laissez-moi mourir !','',26972),
(79820,'frFR','Vous n’avez aucune excuse, Kor’gall. Nous sommes en GUERRE avec un autre monde. Motivez vos troupes, mettez la main à la pâte, je m’en fiche. Soit vous atteignez le quota, soit votre clan servira de cible pour nos prochains tirs d’essai.','',26972),
(79821,'frFR','Voilà, laissez-moi faire quelques réglages.','',26972),
(79822,'frFR','Et voilà.','',26972),
(79843,'frFR','Durotan ? Draka ? Qu’est-ce que vous faites là ?','',26972),
(79845,'frFR','Orgrim Marteau-du-Destin ! Vous allez répondre de votre attaque envers mon peuple !','',26972),
(79849,'frFR','Du calme. Il me le faut en vie.','',26972),
(79851,'frFR','Je ne l’ai ni oublié, ni pardonné. Mais fut un temps où Orgrim était un Orc honorable, en plus d’être mon meilleur ami. Il faut que je l’aide à regagner même un peu de son honneur perdu. Je lui dois au moins cela.','',26972),
(79852,'frFR','Toujours aussi sentimental, à ce que je vois. Je suis aussi loyal à mon peuple que tu l’es au tien. Ne va pas penser que je fais cela de gaieté de cœur. Il est des choses plus importantes encore que l’honneur.','',26972),
(79853,'frFR','','Durotan ? Ce sont ses hommes qui ont tué ton frère.',26972),
(79873,'frFR','Tant pis pour la subtilité. Les Crânes-Ricanants vont tous nous faire tuer.','',26972),
(79874,'frFR','Peuh. Dans mon souvenir, l’architecture ogre était plus imposante.','',26972),
(79892,'frFR','Je n’ai jamais donné cet ordre. Je voulais que votre peuple se joigne au nôtre, afin que l’on protège ce monde de ceux qui viennent de la porte.','',26972),
(79901,'frFR','Vous êtes mon avant-garde.','',26972),
(79902,'frFR','Ces rives sont à nous !','',26972),
(79903,'frFR','Ne laissez aucun survivant !','',26972),
(79904,'frFR','Volonté de fer, sang de fer.','',26972),
(79905,'frFR','Vers la victoire !','',26972),
(79909,'frFR','Il n’y a pas si longtemps, les Orcs étaient divisés en d’innombrables clans, se disputant des miettes dans un monde qui ne demandait qu’à être dompté.','',26972),
(79910,'frFR','Réunis sous une même bannière, nul ne peut espérer se dresser face à la Horde de Fer !','',26972),
(79911,'frFR','Nous écraserons leurs os sous nos bottes. Nous réduirons leurs villes en cendres !','',26972),
(79912,'frFR','La Vague de Fer les emportera !','',26972),
(79914,'frFR','La catastrophe qui arrive nous anéantira tous. Si les Orcs n’arrivent pas à s’unir pour prendre les devants, ces étrangers déchaîneront une vague de feu et de mort qui aura raison de nous.','',26972),
(79915,'frFR','Parce que je l’ai vu ! Et que je continue à le voir ! Chaque nuit ! Chaque nuit depuis des mois, maintenant. Mes rêves se changent en cauchemars dans lesquels je regarde, impuissant, la terre se corrompre sous mes pieds et le ciel prendre feu.','',26972),
(79916,'frFR','Vous pouvez dire ce que vous voulez, mais voilà ce qui approche. Et ce sont ces créatures, celles de la porte, qui l’apporteront avec elles.','',26972),
(79917,'frFR','Et comment pouvez-vous en être aussi certain ?','',26972),
(79918,'frFR','','Je n’aurais jamais cru que le grand Marteau-du-Destin puisse avoir peur de quelque chose.',26972),
(79919,'frFR','Cho’gall ! Je t’ai envoyé ici pour asservir cette chose.','',26972),
(79930,'frFR','','Oui ! Libérons TOUS les crânes ! Apprenons-leur à ricaner ! Brûlez ces esclavagistes jusqu’au dernier !',26972),
(79949,'frFR','RICANANTS !','RICANANTS !',26972),
(79987,'frFR','Aaaaaaaaaaahhhhhhhh ! Aaaah ! Aaaah !','',26972),
(79988,'frFR','Au feu ! Au feu ! Aaaaaaaarrh ! Arh !','',26972),
(80024,'frFR','Retrouvez-moi dans la clairière Crépusculaire. Nous devons sauver les prisonniers.','',26972),
(80039,'frFR','','Brûle, brûle, brûle, feu et torche et braise et brûle et brûle et FEU !',26972),
(80106,'frFR','Merci, $gchampion:championne;. J’ai toujours su que mon destin était intimement lié à celui de l’Étoile noire.','',26972),
(80107,'frFR','Lumière. Lumière pure. Viens nous galvaniser et nous donner espoir en nos heures les plus sombres.','',26972),
(80108,'frFR','Le rituel de Ner’zhul… débute ! Le temps joue contre nous !','',26972),
(80109,'frFR','Nous devons arrêter le chef ombrelune.','',26972),
(80110,'frFR','Ce qui devait être fait, mon enfant.','',26972),
(80111,'frFR','Faites vite, $gchampion:championne;. Je me rendrai sur place aussitôt que je le pourrai.','',26972),
(80112,'frFR','Faites votre possible pour retarder Ner’zhul…','',26972),
(80113,'frFR','','Prophète ! Que vous êtes-vous infligé là !?',26972),
(80120,'frFR','Crâne-Ricanant ! Crâne-Ricanant ! Crâne-Ricanant !','',26972),
(80121,'frFR','','Hahahahahahahaha ! …ha ?',26972),
(80147,'frFR','Cette forêt est à nous !','',26972),
(80165,'frFR','Yrel ! Allons verser le sang des Orcs…','',26972),
(80166,'frFR','Je suis ton chef ; tes guerriers et toi allez rentrer dans le rang.','',26972),
(80167,'frFR','NOTRE - PÈRE - AURAIT - HONTE - DE - CE - QUE - TU - ES - DEVENU !','',26972),
(80168,'frFR','Nous sommes forts parce que nous agissons ensemble.','',26972),
(80169,'frFR','[VO6.0.1] [PH] Temporary cut-scene with my brother? Let’s do it!','',26972),
(80191,'frFR','Yrel, prenez le temps de marcher avec nous un moment…','',26972),
(80230,'frFR','Je… vous l’ai dit… je sais que…','',26972),
(80268,'frFR','La Horde de Fer n’hésitera pas à se servir de ce canon sur notre base. Nous devrions opter pour un emplacement plus stratégique.','',26972),
(80269,'frFR','Tout le monde va bien ?','',26972),
(80270,'frFR','J’crois que je me suis fait dessus…','',26972),
(80271,'frFR','J’avais laissé ma BIÈRE là-bas… !','',26972),
(80272,'frFR','Oui, on dirait que tout le monde va bien.','',26972),
(80273,'frFR','Très bien. Nous établirons notre camp plus loin, avant de nous occuper de ce canon.','',26972),
(80274,'frFR','Yrel va devoir attendre.','',26972),
(80296,'frFR','Allez, tout le monde dans le char. Yrel est retenue dans le camp d’esclaves des ogres cognepierres.','',26972),
(80297,'frFR','Yrel serait déjà libre sans ce fourbe de rangari.','',26972),
(80298,'frFR','J’ai fait ce que je pensais être juste, redresseur de torts. La disparue semble vous détourner de notre mission.','',26972),
(80299,'frFR','Ouais, et qu’est-ce qu’elle a de si spécial, au juste ?','',26972),
(80300,'frFR','Je l’ai perdue une fois. Je refuse de la perdre encore.','',26972),
(80301,'frFR','Pour ça, je suis avec vous.','',26972),
(80302,'frFR','Qui plus est, les ogres vendent des esclaves à la Horde de Fer. On pourrait en profiter pour leur taper un peu dessus, et ça, ça rentre parfaitement dans le cadre de notre mission.','',26972),
(80303,'frFR','Vous allez vous faire écraser.','',26972),
(80304,'frFR','Justement, cher ogre, c’est là que tu te trompes. Vois-tu, c’est nous qui allons vous écraser, aujourd’hui. Thaelin ?','',26972),
(80305,'frFR','Oui, cap’taine !','',26972),
(80306,'frFR','Voilà notre chance ! En avant, Thaelin, et vite !','',26972),
(80307,'frFR','Quoi ça…?','',26972),
(80308,'frFR','Silence, vous tous ! Toi, l’ogre, si jamais tu l’ouvres, même pour grogner, tu vas comprendre ta douleur.','',26972),
(80309,'frFR','On peut s’installer ici.','',26972),
(80310,'frFR','Ok’mok pas faire de bruit du tout. Vous pas besoin taper Ok’mok.','',26972),
(80311,'frFR','Oh, j’ai l’impression que tu vas quand même en prendre une.','',26972),
(80312,'frFR','Une attaque directe. Audacieux.','',26972),
(80313,'frFR','Rassembler des renforts. Sage décision.','',26972),
(80314,'frFR','En formation, tout le monde. Nous partons pour l’Entrepôt Crache-Fumée.','',26972),
(80315,'frFR','[VO6.0.1] Form up, everyone. We are headed to the Planteau. [TEMP NAME]','',26972),
(80316,'frFR','','Il vous reste de la place sur cet elekk ?',26972),
(80317,'frFR','Pour vous mon amour, toujours.','',26972),
(80318,'frFR','Yrel, avez-vous appris quoi que ce soit au sujet du canon Goliath avant votre capture ?','',26972),
(80319,'frFR','','Oui. Le canon que vous avez détruit n’était qu’un prototype. Les vrais sont construits dans la fonderie, au nord.',26972),
(80320,'frFR','','J’ai entendu l’un des chefs orcs dire qu’ils prévoyaient de s’en servir sur Shattrath.',26972),
(80321,'frFR','Shattrath ? Ha ! Ils ne pourraient jamais l’atteindre d’ici, même avec un tel morceau.','',26972),
(80322,'frFR','Ils pourraient, s’ils le chargeaient à bord d’un bateau.','',26972),
(80323,'frFR','C’est ce dont j’ai peur. Ils doivent prévoir d’embarquer les canons sur des barges à la base navale, au nord-est.','',26972),
(80324,'frFR','Notre petit groupe ne survivrait jamais à une attaque de la base navale. Elle est trop bien défendue.','',26972),
(80325,'frFR','Nous continuerons à attaquer leurs lignes de ravitaillement.','',26972),
(80326,'frFR','','D’kaan, cela fait longtemps que vous êtes éclaireur en Gorgrond ?',26972),
(80327,'frFR','Très longtemps. Vous n’étiez même pas née, ni même vos parents d’ailleurs.','',26972),
(80328,'frFR','Vous n’vous sentez jamais seul ?','',26972),
(80329,'frFR','Il n’y a que dans la solitude qu’un rangari peut faire son devoir.','',26972),
(80330,'frFR','Mouais, ça m’a pas l’air génial comme boulot. La vie vaut pas la peine d’être vécue sans des amis et une dame pour vous attendre à la maison.','',26972),
(80331,'frFR','','Vous êtes marié, Hansel ?',26972),
(80332,'frFR','Ah… les Rochenoires l’ont enlevée.','',26972),
(80333,'frFR','C’est aussi pour ça que je suis là : veiller sur Thaelin et retrouver ma femme.','',26972),
(80334,'frFR','Nous allons la retrouver, Hansel. Et nous allons faire des dégâts. Les Orcs vont payer pour ce qu’ils ont fait à nos familles.','',26972),
(80335,'frFR','Vous savez, c’est la chose la plus noire et la plus froide que j’aie jamais entendu dire un paladin. La plus exaltante, aussi.','',26972),
(80336,'frFR','On a fini ici. Maintenant, en avant vers l’entrepôt Crache-Fumée.','',26972),
(80337,'frFR','On a fini ici. Maintenant, en avant vers le plateau.','',26972),
(80338,'frFR','','Thaelin, tout va bien là-dedans ?',26972),
(80339,'frFR','Très bien, madame. J’suis juste content d’être retourné bien à l’abri dans mon char.','',26972),
(80340,'frFR','','<soupir> La guerre gangrène cette terre. Pensez-vous vraiment retrouver la paix de votre foyer, une fois notre mission terminée ?',26972),
(80341,'frFR','J’sais pas ce qu’on vous a dit sur Azeroth, madame, mais, niveau guerre, on a déjà donné.','',26972),
(80342,'frFR','Dès que j’aurai retrouvé mon Ellie, je repartirai pour la gorge des Vents brûlants, ça n’fait aucun doute.','',26972),
(80343,'frFR','Et vous, ma grande ? Vous allez rentrer chez vous ?','',26972),
(80344,'frFR','','Maintenant que Velen est mort, je n’ai plus l’impression d’avoir de chez moi.',26972),
(80345,'frFR','Nous sommes des Draeneï, Yrel. C’est dans notre nature de ne pas avoir de foyer.','',26972),
(80346,'frFR','','Je me disais que je pourrais traverser la porte avec vous, mon amour.',26972),
(80347,'frFR','Oui, Yrel, un foyer vous attend en Azeroth.','',26972),
(80348,'frFR','Mais d’abord, nous allons faire payer ces Orcs pour ce qu’ils vous ont fait. Leurs péchés ne peuvent rester impunis.','',26972),
(80349,'frFR','','Maraad, vous me faites peur.',26972),
(80350,'frFR','Les lignes de ravitaillement de la Horde de Fer sont à présent coupées, même si ce n’est que temporaire. Nous voilà alliés avec les sculpteurs.','',26972),
(80351,'frFR','C’est le moment ou jamais. Partons pour la base navale et vengeons-nous de la Horde de Fer !','',26972),
(80352,'frFR','','Quel est le plan, Maraad ?',26972),
(80353,'frFR','En tuer autant que possible. Puis nous brûlerons leurs maisons et leur montrerons ce qu’est la peur.','',26972),
(80354,'frFR','Ils vont savoir ce que j’ai ressenti quand je vous ai perdue, Yrel.','',26972),
(80355,'frFR','','Maraad… Je suis flattée…',26972),
(80356,'frFR','','… mais peut-être allez-vous trop loin. Avez-vous oublié ce que le Prophète nous a appris ?',26972),
(80357,'frFR','Le Prophète est MORT, Yrel. Ses enseignements ne l’ont pas mené bien loin.','',26972),
(80358,'frFR','Vous dépassez les bornes, Maraad.','',26972),
(80359,'frFR','La Lumière vous a abandonné. Même moi, j’peux le voir.','',26972),
(80360,'frFR','Ce n’est pas que j’apprécie particulièrement la Lumière, mais je suis d’accord. N’oubliez pas les valeurs que vous défendez, redresseur de torts.','',26972),
(80361,'frFR','Vous vous croyez plus sacrés que moi ? C’est moi le chef de cette expédition, et je refuse de supporter vos remarques une seconde de plus !','',26972),
(80362,'frFR','La Lumière ne m’a pas abandonné, Thaelin. Non… mais elle se montre enfin sous son vrai jour.','',26972),
(80363,'frFR','Vengeance.','',26972),
(80364,'frFR','J’ai vu comment s’étaient vengés les naaru lors de la purge de Grommar. J’étais là quand K’ara lui-même a déchaîné la mort sacrée sur les hordes impures.','',26972),
(80365,'frFR','[VO6.0.1] And now that these hordes have taken, broken, and defiled my angel Yrel, I intend to unleash my own...','',26972),
(80366,'frFR','','Maraad, mon amour. Ça suffit.',26972),
(80367,'frFR','Yrel…','',26972),
(80368,'frFR','','Vous en avez trop vu, Maraad. Votre soif de vengeance ne fera que nous mener à notre perte.',26972),
(80369,'frFR','','[VO6.0.1] Yes, I was taken, but I am not defiled, and I am not broken.',26972),
(80370,'frFR','','Reposez-vous. Je vais mener l’assaut contre la base navale.',26972),
(80371,'frFR','Je suis avec vous, Yrel.','',26972),
(80372,'frFR','J’en suis aussi.','',26972),
(80373,'frFR','Moi aussi.','',26972),
(80374,'frFR','Très bien.','',26972),
(80375,'frFR','Merci, Yrel. Je ne sais pas ce qui me prend.','',26972),
(80492,'frFR','Peu importe. Ces âmes sont à moi. Mon pouvoir grandit.','',26972),
(80493,'frFR','Auchindoun sera à moi ! Je dévorerai jusqu’à la dernière âme et plongerai les cendres dans les flammes infernales !','',26972),
(80533,'frFR','','Oui, Tuulani. Maintenant, tu vois.',26972),
(80534,'frFR','','Tes efforts étaient admirables. Je ne pensais pas les anachorètes capables d’alimenter les défenses avec un seul cristal.',26972),
(80535,'frFR','','Mais rien n’arrêtera mes plans, ni ceux de mes maîtres. Et tout ce qui se dresse sur notre route…',26972),
(80536,'frFR','','Protecteur ! Détruis ces intrus !',26972),
(80537,'frFR','Courez, sauvez vos vies !','Courez, sauvez vos vies !',26972),
(80544,'frFR','Waouh ! Merci ! Maintenant je vais pouvoir mettre les bouts. Et pas question de me faire capturer une nouvelle fois. À bientôt !','',26972),
(80553,'frFR','Je crains que même avec le cœur intact, les défenses d’Auchindoun ne suffisent pas. Le Conseil des ombres a des yeux partout.','',26972),
(80632,'frFR','','Maman ?',26972),
(80637,'frFR','','Maudites soient ces protections ! J’ai beau invoquer la Lumière pour les dissiper, encore et encore, on dirait qu’elles neutralisent mon pouvoir.',26972),
(80641,'frFR','Les runes sont détruites.','Les runes sont détruites.',26972),
(80642,'frFR','Prête à affronter Revaan ?','Prête à affronter Revaan ?',26972),
(80646,'frFR','Mon enfant ! Quittez les lieux. Ces protections étaient là pour votre sécurité. Vous ne devez pas rester ici.','',26972),
(80647,'frFR','Oui… et jamais elle ne vous appartiendra.','',26972),
(80701,'frFR','','Tuulani, allez à Telmor et trouvez la lieuse d’âme Aedraa. Elle a retrouvé le dernier cristal et l’a transporté là-bas.',26972),
(80702,'frFR','','Tout de suite.',26972),
(80850,'frFR','Vos esclaves sont prêts, chef.','',26972),
(80851,'frFR','Parfait… leurs esprits me serviront bien mieux que leurs pitoyables enveloppes corporelles ne l’ont jamais fait !','',26972),
(80852,'frFR','Silence, espèce d’imbécile !','',26972),
(80853,'frFR','Ahhhh… bien ; le Broyeur-d’âmes bourdonne de puissance ! Plus rien ne pourra plus nous arrêter !','',26972),
(80870,'frFR','','On dirait qu’il n’y a qu’une seule sortie, $ghéros:héroïne;. EN HAUT !',26972),
(80871,'frFR','Vous ne comprenez rien au grand œuvre.','',26972),
(80872,'frFR','Vous ne pourrez pas arrêter le grand œuvre.','',26972),
(80873,'frFR','Tout ceci était écrit. Vous ne pourrez pas l’empêcher.','',26972),
(80874,'frFR','Vous ne comprenez pas… Vous ne pouvez pas savoir…','',26972),
(80880,'frFR','Ouais ! Nous sommes invincibles ! Invincibles !','',26972),
(80881,'frFR','Je dois retourner dans le monde des esprits pour continuer mes recherches. Gardez cette salle et veillez à ce que PERSONNE ne touche au portail !','',26972),
(80888,'frFR','Viens, Broyeur-d’âmes ! Dévore les âmes que nous t’avons apportées !','',26972),
(80890,'frFR','Baissez vos haches, mes frères ! Vous ne reconnaissez donc plus les membres de votre propre clan ?','',26972),
(80896,'frFR','On est chez nous !','',26972),
(80913,'frFR','','Que comptez-vous faire, Thrall ?',26972),
(80914,'frFR','Cette chose poussiéreuse pue la haine, Choluna. J’ai peur que sa présence mette le fief en danger.','',26972),
(80915,'frFR','Elle serait plus dangereuse encore entre les mains de la Horde de Fer.','',26972),
(80916,'frFR','Nous devrions la détruire.','',26972),
(80917,'frFR','Peut-être… mais nous devons d’abord comprendre à quoi l’utilise Main-Noire.','',26972),
(80918,'frFR','Choluna, tâchez d’intensifier nos activités en Gorgrond. Quels que soient les projets de la Horde de Fer, nous devons nous tenir prêts.','',26972),
(80927,'frFR','Et vous, qu’est-ce que vous êtes ?','',26972),
(80928,'frFR','Je suis grandiose.','',26972),
(80933,'frFR','Vous êtes sur le territoire des Loups-de-Givre, mais ce plateau est désormais vôtre. Considérez-le comme une récompense pour avoir sauvé mon peuple.','',26972),
(80934,'frFR','Merci, chef. Nous allons immédiatement établir une base.','',26972),
(80955,'frFR','Même nos wyvernes ont du mal à supporter ce froid glacial.','Même nos wyvernes ont du mal à supporter ce froid glacial.',26972),
(80956,'frFR','On dirait bien qu’il va falloir se passer de soutien aérien cette fois.','On dirait bien qu’il va falloir se passer de soutien aérien cette fois.',26972),
(80957,'frFR','Il faut trouver un meilleur moyen de protéger nos wyvernes du froid.','Il faut trouver un meilleur moyen de protéger nos wyvernes du froid.',26972),
(80958,'frFR','Pour les voyages aériens, il faudra compter sur les rylaks du coin.','Pour les voyages aériens, il faudra compter sur les rylaks du coin.',26972),
(80967,'frFR','Nan.','',26972),
(80968,'frFR','Que comptez-vous faire, Yrel ?','',26972),
(80969,'frFR','','Cette chose empeste la haine et la poussière, Omnuron. Je n’aime pas ça du tout.',26972),
(80970,'frFR','Nous devrions détruire la chose.','',26972),
(80996,'frFR','Ce terrain est idéal pour construire un bastion.','',26972),
(80997,'frFR','Je peux ouvrir un portail vers Orgrimmar, mais il ne durera pas longtemps. Les renforts se tiennent prêts, j’espère ?','',26972),
(80998,'frFR','Les meilleurs.','',26972),
(80999,'frFR','Quelqu’un a demandé un réparateur ?','',26972),
(81000,'frFR','… Vous avez confié le rôle de contremaître à un Gobelin ?','',26972),
(81001,'frFR','Gazleu a supervisé la construction d’Orgrimmar.','',26972),
(81002,'frFR','Orgrimmar ! La forteresse impénétrable !','',26972),
(81003,'frFR','N’a-t-elle pas été mise à sac récemment ?','',26972),
(81004,'frFR','Oui, bon, d’accord, mais c’était un tout petit pillage.','',26972),
(81005,'frFR','Omnuron, tâchez d’activer les choses en Gorgrond. Quels que soient les projets de la Horde de Fer, nous devons nous tenir prêts.','',26972),
(81023,'frFR','Qu’est-ce que… Oreille-Dressée ! Tu es en vie !','',26972),
(81024,'frFR','Mène-nous à Durotan, mon vieil ami !','',26972),
(81025,'frFR','C’est à Wor’gol que le clan Loup-de-Givre a ses quartiers d’hiver.','',26972),
(81026,'frFR','Entre les Orcs sire-tonnerre et les ogres flèchelames, Durotan est sur le fil du rasoir.','',26972),
(81027,'frFR','Ga’nar semblait fermement décidé à en découdre avec tout le monde.','',26972),
(81028,'frFR','Oh, oui ! Je me fais du souci pour le frère de Durotan. Il a toujours été prompt au combat. Son désir de vengeance le rendra plus téméraire que jamais.','',26972),
(81029,'frFR','Qu’est-ce que c’est que ÇA ? On dirait une forteresse de pierre !','',26972),
(81030,'frFR','La citadelle de Flèchelame. Autrefois, c’était un avant-poste lointain de l’empire ogre.','',26972),
(81031,'frFR','Si nous voulons donner à notre peuple une chance de survivre, nous devons chasser les ogres de leur forteresse.','',26972),
(81032,'frFR','C’est l’objectif que Durotan s’est fixé. Il ne vous demandera rien de lui-même, mais nous avons besoin de votre aide !','',26972),
(81041,'frFR','','Ga’nar n’a pas attendu l’appel au ralliement. Il a le sang bien trop chaud pour ça.',26972),
(81042,'frFR','','Allez-y ! Offrez-nous une belle victoire. Dites à mon époux que je défendrai la ville jusqu’à son retour.',26972),
(81056,'frFR','','La légion n’abandonnera pas si facilement. Auchindoun a trop de valeur pour eux.',26972),
(81057,'frFR','','Teron’gor ! La Lumière vient te chercher !',26972),
(81060,'frFR','La Légion n’en restera pas là. Ils veulent Auchindoun plus que tout.','',26972),
(81061,'frFR','Nyami, Tuulani, nous partons pour Le Repos de la Lumière immédiatement.','',26972),
(81176,'frFR','L’avant-garde s’effondre. Faisons en sorte qu’elle ne se soit pas sacrifiée en vain !','',26972),
(81177,'frFR','Notre dernière tâche, c’est de mourir au combat. Qui me suit ?','',26972),
(81178,'frFR','Archimage, je vais rester ici. J’ai fait le serment de surveiller cette porte.','',26972),
(81179,'frFR','C’est un devoir qui m’incombait autant qu’à vous, Dar’toon. Nous irons ensemble au-devant de l’ennemi. ','',26972),
(81180,'frFR','Votre chanson de geste fera mention de votre héroïsme, Dar’toon.','',26972),
(81181,'frFR','Libérez-moi. Je pourrais tuer une centaine de ces porcs rien qu’avec cette pelle.','',26972),
(81182,'frFR','Préparez-vous à CTRL-E héroïquement avec moi à travers le portail !','',26972),
(81192,'frFR','','Je vais conduire les blessés en sûreté. Couvrez-nous !',26972),
(81222,'frFR','Qui que vous soyez… Merci.','Qui que vous soyez… Merci.',26972),
(81223,'frFR','Ils nous saignaient. Nous n’en avions plus pour longtemps…','Ils nous saignaient à blanc. Nous n’en avions plus pour longtemps…',26972),
(81224,'frFR','Qui que vous soyez… Merci.','Qui que vous soyez… Merci.',26972),
(81225,'frFR','Ils nous saignaient à blanc. Nous n’en avions plus pour longtemps…','Ils nous saignaient à blanc. Nous n’en avions plus pour longtemps…',26972),
(81226,'frFR','Aidez-nous !','Aidez-nous !',26972),
(81227,'frFR','Libérez-nous !','Libérez-nous !',26972),
(81228,'frFR','Il y a quelqu’un ?','Il y a quelqu’un ?',26972),
(81229,'frFR','Au secours ! À l’aide !','Au secours ! À l’aide !',26972),
(81276,'frFR','','$p, je pense que vous devriez suivre Tuulani et la protéger. Nous devons assurer la sécurité du cristal jusqu’à Auchindoun. ',26972),
(81277,'frFR','$p, vous devriez suivre Tuulani et la protéger. Nous devons faire en sorte que le cristal arrive en sécurité à Auchindoun.','',26972),
(81279,'frFR','Soyez $gbéni:bénie;, $gétranger:étrangère;. Grâce à vous, je reverrai la lumière du jour.','',26972),
(81280,'frFR','','Merci, $gétranger:étrangère; ! Ils allaient faire de moi leur prochain repas…',26972),
(81281,'frFR','','Merci, $ghéros:héroïne;. Je trouverai moi-même le chemin de la sortie.',26972),
(81282,'frFR','Nous devons empêcher Teron’gor d’entrer dans Auchindoun. Venez, rassemblons-nous à la halte de la Vindicte pour discuter du meilleur moyen de combattre l’ennemi sur son terrain.','',26972),
(81293,'frFR','Vous avez… *tousse*… sauvé l’honneur d’un vieil orc mourant, $gchampion:championne;. Je vous tire ma révérence… ainsi qu’à toi, Neigepatte, mon vieil ami…','',26972),
(81295,'frFR','','Merci, $ghéros:héroïne;. Nous nous souviendrons de vos exploits.',26972),
(81373,'frFR','J’en ai assez vu. ','',26972),
(81374,'frFR','Kargath, espèce de lâche !','',26972),
(81375,'frFR','Vous ne tiendrez pas dix secondes face à moi, Draeneï. ','',26972),
(81376,'frFR','Votre voix trahit votre peur, Kargath. ','',26972),
(81377,'frFR','Deux contre un ? Ah, les grands esprits se rencontrent !','',26972),
(81378,'frFR','Ce n’est pas très sport, Lamepoing. Pourquoi ne pas régler ça dans l’arène ?','',26972),
(81379,'frFR','Arrêtez tout ! Vous voyez, on se comprend !','',26972),
(81380,'frFR','J’ai peur que vous ne soyez qu’un échauffement, Draeneï. Quelqu’un d’autre a envie de mourir aujourd’hui ?','',26972),
(81381,'frFR','Je n’aurais jamais cru que vous demanderiez. ','',26972),
(81382,'frFR','Retournez à Khadgar, $gchampion:championne; ! Nous allons gagner le temps nécessaire !','',26972),
(81418,'frFR','Je sens que les flammes s’éteignent. Que se passe-t-il, exarque ?','',26972),
(81419,'frFR','Quelqu’un vient… pour nous sauver, peut-être ?','',26972),
(81420,'frFR','Nous sommes libres ! Suivez-moi, chaman. Nous allons fuir en traversant les collines.','',26972),
(81443,'frFR','Il a raison. La Horde de Fer ne tardera pas à nous attaquer. Nous devons être prêts.','',26972),
(81446,'frFR','Non, je ne serais jamais d’accord avec cela.','',26972),
(81447,'frFR','Il a fait son choix.','',26972),
(81457,'frFR','Occupez-vous des lieutenants, $gchampion:championne;, Lamepoing est à moi. ','',26972),
(81458,'frFR','Exécuter des prisonniers non armés ? Pourquoi ne pas livrer un vrai combat ?','',26972),
(81482,'frFR','','Maître Velen, je n’ai jamais dirigé de soldats auparavant. Êtes-vous certain…',26972),
(81483,'frFR','Tu sous-estimes tes capacités, Yrel.','',26972),
(81485,'frFR','Maintenant, va. Les Rangari sont à tes ordres. Trouvez les prisonniers.','',26972),
(81509,'frFR','Prépare-toi pour l’arrivée de nos navires à Karabor.','',26972),
(81534,'frFR','','Nyami ! Nous sommes là…',26972),
(81535,'frFR','','Qu’est-ce que c’est ? Oh, non, non…',26972),
(81536,'frFR','','Vous devez les arrêter !',26972),
(81537,'frFR','','…Le protecteur… est toujours à ses ordres… vous devez le vaincre !',26972),
(81538,'frFR','','Ahhh ! ',26972),
(81555,'frFR','','C’est TOI, Tuulani, et tes amis étrangers.',26972),
(81556,'frFR','','Cet endroit est condamné. Ce n’est qu’une question de temps…',26972),
(81557,'frFR','','Oui ! Oui ! Le cristal bourdonne… On se concentre un peu et…',26972),
(81559,'frFR','Attention, derrière vous !','Attention, derrière vous !',26972),
(81560,'frFR','Je crois que je l’ai eu. ','Je crois que je l’ai eu.',26972),
(81561,'frFR','Je vous remercie. ','Je vous remercie.',26972),
(81562,'frFR','Louée soit la Lumière !','Louée soit la Lumière !',26972),
(81563,'frFR','Une arme !','Une arme !',26972),
(81564,'frFR','Voyons s’ils aiment ça, eux, de se faire ouvrir le ventre !','Voyons s’ils aiment ça, eux, de se faire ouvrir le ventre !',26972),
(81565,'frFR','Enfin libres !','Enfin libres !',26972),
(81566,'frFR','Adieu, mon amour. ','Adieu, mon amour.',26972),
(81568,'frFR','J’ai bien cru que j’allais mourir ici. ','J’ai bien cru que j’allais mourir ici.',26972),
(81569,'frFR','Vous n’imaginez pas depuis combien de temps j’attends de faire ça. ','Vous n’imaginez pas depuis combien de temps j’attends de faire ça.',26972),
(81570,'frFR','Crève, porc !','Crève, porc !',26972),
(81571,'frFR','Je vous vengerai, Tannosh. ','Je vous vengerai, Tannosh.',26972),
(81572,'frFR','Que la Lumière soit avec vous, ma sœur. ','Que la Lumière soit avec vous, ma sœur.',26972),
(81573,'frFR','Que votre esprit repose en paix avec ceux de vos ancêtres. ','Que votre esprit repose en paix avec ceux de vos ancêtres.',26972),
(81574,'frFR','Tuez-les. Tuez-les tous. ','Tuez-les. Tuez-les tous.',26972),
(81575,'frFR','Faites-les souffrir, comme moi j’ai souffert. ','Faites-les souffrir, comme moi j’ai souffert.',26972),
(81576,'frFR','Merci. ','Merci.',26972),
(81577,'frFR','Je n’ai jamais manié une arme. ','Je n’ai jamais manié une arme.',26972),
(81578,'frFR','C’est agréable. ','C’est agréable.',26972),
(81579,'frFR','Ooh !','Ooh !',26972),
(81580,'frFR','Vous apportez espoir à mon peuple, $gétranger:étrangère;. ','Vous apportez espoir à mon peuple, $gétranger:étrangère;. ',26972),
(81585,'frFR','Dagg remercie vous, l’$gami:amie; ! <Dagg laisse échapper un rire guttural.>','',26972),
(81593,'frFR','Ces Orcs attrapent moi sans cesse. Je sais pas comment y font. <Dagg ricane d’une manière désarmante.>','',26972),
(81594,'frFR','Bonjour.','',26972),
(81595,'frFR','Ils vont se poser la question : « C’est Dagg qui s’est fait attraper ou Dagg qui les a attrapés ? »

$gLe grand héros:La grande héroïne; a grillé la couverture de Dagg ! Mais Dagg, il pense que vous avez quelque chose de spécial. Dagg est le maître du déguisement, et il veut vous rejoindre.

Dagg est unanime.','',26972),
(81596,'frFR','Approuver unanimement Dagg ? (Sujet de fief)','Approuver unanimement Dagg ? (Sujet de fief)',26972),
(81607,'frFR','Balancez pas Dagg !$B$BIls interrogent pas les arbres.$B$BDagg est unanime là-dessus.','',26972),
(81608,'frFR','Faut pas qu’ils nous voient parler !

Ils interrogent jamais les deux-têtes.

Dagg est unanime là-dessus.','',26972),
(81609,'frFR','Chut ! Ayez l’air naturel.','',26972),
(81610,'frFR','Chut ! Me faites par repérer !','',26972),
(81674,'frFR','Je crains de devoir partir pour rejoindre notre meute à Wor’gol. Aka’Magosh.','',26972),
(81675,'frFR','Hors de mon chemin, péon !','Hors de mon chemin, péon !',26972),
(81787,'frFR','Cette acolyte et moi allons rejoindre le reste de notre groupe. Vous, empêchez à tout prix l’orc d’ouvrir le portail !','',26972),
(81788,'frFR','','Nous reviendrons avec des renforts.',26972),
(81808,'frFR','Non… NON ! Mon peuple ne peut pas connaître une telle fin !','',26972),
(81809,'frFR','C’est Ner’zhul qui nous entraîne sur cette voie. Pour sauver Karabor, nous devons l’arrêter.','',26972),
(81810,'frFR','Retrouvez-moi dans la clairière Crépusculaire. Nous avons beaucoup à faire.','',26972),
(81821,'frFR','Habitants du Fort Wrynn, notre commandant a terminé la construction d’un nouveau bâtiment !','',26972),
(81822,'frFR','Nous allons devoir œuvrer ensemble pour optimiser la production. Faites en sorte que le commandant n’ait pas à attendre !','',26972),
(81824,'frFR','Oyez, oyez, braves gens. Grâce à notre commandant, nous avons un nouveau bâtiment !','',26972),
(81825,'frFR','Va falloir s’activer pour avoir ce nouveau bâtiment, et fissa, OK ? C’est à faire pour hier, dernier délai !','',26972),
(81826,'frFR','Vous pourrez gérer la suite, j’en suis certain. Bien joué !','',26972),
(81827,'frFR','Vous n’aurez pas besoin de moi, c’est vous le chef, après tout.','',26972),
(81832,'frFR','','La Draeneï et moi allons retourner voir Khadgar. Empêchez l’orc d’ouvrir le portail !',26972),
(81866,'frFR','Variateur de puissance actif. Réinitialisation des systèmes principaux. Veuillez patienter.','',26972),
(81867,'frFR','Très bien, Robot-bonheur 8000. Au travail !','',26972),
(81868,'frFR','Commande inconnue. En attente d’ordre du propriétaire du Robot-bonheur 8000 : $p.','',26972),
(81870,'frFR','Bon sang, j’abandonne. $p, vous pouvez l’avoir ! J’en ai ras la casquette !','',26972),
(81875,'frFR','Très bien, Robot-bonheur 8000. Exécute la commande X47G5 !','',26972),
(81876,'frFR','Ça suffit, j’en ai ma claque ! $p, vous pouvez le garder ! Je retourne à la construction de chars une bonne fois pour toutes !','',26972),
(81957,'frFR','Ah, liberté chérie ! Vous ne le regretterez pas, commandant. Je vous fabriquerai les meilleures armes de tout Draenor !','',26972),
(81959,'frFR','Voyons le matériel disponible.','',26972),
(81960,'frFR','La forge est l’âme de la fonderie. Celle-ci est petite, mais avec le bon équipement, je peux l’améliorer.','',26972),
(81961,'frFR','C’est pas mal, mais avec quelques modifications, je devrais pouvoir en faire une charge explosive pour les canons.','',26972),
(81971,'frFR','Chut ! Faut pas qu’ils nous voient, vous allez me faire repérer !','',26972),
(81980,'frFR','Je vais voir si je peux faire fonctionner ce truc. Khadgar, j’ai besoin de temps !','',26972),
(81981,'frFR','Nous ferons ce que nous pourrons, Thaelin.','',26972),
(81982,'frFR','Vous, empêchez ces Orcs de s’en prendre à nous !','',26972),
(81983,'frFR','','Attention ! Un char en approche !',26972),
(81984,'frFR','Ces commandes, c’est du grand N’IMPORTE QUOI ! Rappelez-moi de plus jamais conduire un char orc.','',26972),
(81985,'frFR','Tenez bon, ils arrivent !','',26972),
(81986,'frFR','Ils apportent des explosifs. Détruisez ces chariots avant qu’ils soient trop près !','',26972),
(81987,'frFR','Ils sont si nombreux…','',26972),
(81988,'frFR','Ne baissez pas les bras, paladin.','',26972),
(81989,'frFR','Ça y est, il démarre ! Finissons-en.','',26972),
(82005,'frFR','Oh oh, joli tir.','',26972),
(82103,'frFR','Très bien, mais faites vite. J’aurai besoin de vous deux plus tard, et il faudrait que vous soyez en vie.','',26972),
(82111,'frFR','Venez, Cordana !','',26972),
(82117,'frFR','Je rassemble un petit groupe pour aller explorer les fortifications ennemies.','Je rassemble un petit groupe pour aller explorer les fortifications ennemies.',26972),
(82120,'frFR','Thrall, prenez la tête des derniers survivants et rejoignez-nous plus loin.','Thrall, prenez la tête des derniers survivants et rejoignez-nous plus loin.',26972),
(82121,'frFR','Maraad, prenez la tête des derniers survivants et rejoignez-nous plus loin.','Maraad, prenez la tête des derniers survivants et rejoignez-nous plus loin.',26972),
(82122,'frFR','Très bien.','',26972),
(82124,'frFR','Oui, archimage.','',26972),
(82130,'frFR','Devant ! Regardez !','',26972),
(82131,'frFR','Par mes ancêtres… regardez ça !','',26972),
(82149,'frFR','Je sais ce que je dois faire.','',26972),
(82150,'frFR','SANG ET HONNEUR !','',26972),
(82151,'frFR','KILROGG ŒIL-MORT','KILROGG ŒIL-MORT',26972),
(82152,'frFR','SEIGNEUR DE GUERRE DE L’ORBITE-SANGLANTE','SEIGNEUR DE GUERRE DE L’ORBITE-SANGLANTE',26972),
(82153,'frFR','Regardez un peu qui voilà. De la viande fraîche !','',26972),
(82154,'frFR','On ne tombera pas sans combattre, Œil-Mort.','',26972),
(82155,'frFR','On dirait que vous avez besoin d’un coup de main.','',26972),
(82156,'frFR','Non ! Venez plutôt m’affronter !','',26972),
(82157,'frFR','Allez… trouver… Khadgar…','',26972),
(82178,'frFR','','Génial ! Merci, merci, merci, merci BEAUCOUP !',26972),
(82179,'frFR','Je croyais que tout le monde m’avait oublié. Merci, $Gm’sieur:m’dame; !','',26972),
(82180,'frFR','Ouah, vous avez vaincu tous les Orcs ? Vous êtes balaise !','',26972),
(82182,'frFR','','<La petite fille pleure toutes les larmes de son corps.>',26972),
(82199,'frFR','Avec un peu de chance, les petits vont fuir maintenant et on pourra lancer la construction.','',26972),
(82258,'frFR','Hum.','',26972),
(82259,'frFR','Ce bourreau esclavagiste n’a aucun sens de l’honneur.','',26972),
(82260,'frFR','Nous ne pourrons pas nous terrer éternellement ici.','',26972),
(82261,'frFR','Pénétrez dans mon arène et tâchez de mourir honorablement.','',26972),
(82262,'frFR','Vous êtes dans mon arène, étrangers. Vous la quitterez en champions… ou les pieds devant.','',26972),
(82263,'frFR','Telle est la loi de la MAIN-BRISÉE.','',26972),
(82264,'frFR','Une arène. C’est sans doute un piège, mais quitte à mourir, que ce soit avec honneur.','',26972),
(82361,'frFR','','Vite, Yrel. La puissance de ton marteau nous sera d’une grande aide.',26972),
(82486,'frFR','Je pars en reconnaissance aux portes pendant que vous neutralisez ces catapultes. Lok’tar ogar !','',26972),
(82494,'frFR','Commandant, par ici !','',26972),
(82496,'frFR','La peste soit de ces ogres et de leur magie ! Je n’arrive pas à neutraliser la barrière, nous allons devoir la contourner.','',26972),
(82497,'frFR','Je passe devant pour dégager la voie. Rejoignez-moi de l’autre côté.','',26972),
(82525,'frFR','Sang et tonnerre, quelle belle bataille !','',26972),
(82530,'frFR','Allons tuer quelques ogres !','',26972),
(82568,'frFR','Volons ensemble. Nous les aiderons depuis les airs !','',26972),
(82569,'frFR','La lumière purificatrice des naaru est à la fois notre marteau et notre bouclier.','',26972),
(82570,'frFR','Ils sont devant les portes du temple… Approchons-nous ! Vite !','',26972),
(82571,'frFR','Poursuivons. Nous devons libérer les marches.','',26972),
(82572,'frFR','Jamais plus vos hordes d’Orcs ne feront vaciller la Lumière de Karabor !','',26972),
(82573,'frFR','Merci, l’ami !','',26972),
(82574,'frFR','Jamais plus vous ne ferez vaciller la flamme de Karabor !','',26972),
(82575,'frFR','Continuez d’avancer ! Par la lumière des naaru !','',26972),
(82576,'frFR','Faites rayonner la lumière, mes frères et sœurs !','',26972),
(82577,'frFR','Nous avons fait tout notre possible là-haut…','',26972),
(82578,'frFR','Nous avons réussi à percer leur barrage !','',26972),
(82579,'frFR','Nous avons repoussé leur principale force d’assaut ! Allons retrouver nos troupes.','',26972),
(82580,'frFR','C’est tout ce qu’il reste de nos troupes. Nous allons rester ici et garder les portes du temple.','',26972),
(82581,'frFR','Je veux que vous vous frayiez un chemin jusqu’au port.','',26972),
(82582,'frFR','','J’approcherai l’ennemi par le sud. Que la lumière des naaru vous guide !',26972),
(82583,'frFR','','Le naaru est venu nous aider. Protégeons-le pendant qu’il concentre son énergie !',26972),
(82584,'frFR','','Nous avons réussi ! À présent mettons un terme à cet assaut…',26972),
(82585,'frFR','Admirez la VÉRITABLE puissance de la Horde de Fer !','',26972),
(82586,'frFR','ASSEZ. Fini de jouer. C’est moi qui vais m’occuper de vous.','',26972),
(82587,'frFR','','Là-haut ! Le commandant de la flotte se montre enfin !',26972),
(82588,'frFR','','Qu’est-ce que le naaru est en train de faire ?',26972),
(82589,'frFR','C’est terminé. Nous avons gagné.','',26972),
(82590,'frFR','','Vous avez vaillamment combattu. Je vous remercie vivement.',26972),
(82592,'frFR','Salutations, défenseur de mon peuple !','',26972),
(82593,'frFR','Si vous écoutez ce message, c’est que je ne suis plus… mais que Karabor est sauf.','',26972),
(82594,'frFR','Je vous dois une explication.','',26972),
(82595,'frFR','Les naaru que nous, Draeneï, révérons, sont des créatures de lumière pure.','',26972),
(82596,'frFR','Mais lorsque leur fin est proche, elles perdent leur essence et déclinent jusqu’à se transformer en créatures de l’ombre.','',26972),
(82597,'frFR','Lorsque les Draeneï découvrirent ce monde, les naaru nous accompagnaient. Mais ils ne purent empêcher le crash de notre vaisseau.','',26972),
(82598,'frFR','« L’Étoile noire » qui apparut dans les cieux de Draenor cette terrible nuit n’avait rien d’un corps céleste…','',26972),
(82599,'frFR','C’était un naaru déchu, éjecté de notre vaisseau, pris de panique et terrorisé. Il s’appelait K’ara.','',26972),
(82600,'frFR','Celui qui jadis incarnait la foi et la beauté se changea en dieu sombre et affamé, une source vivante de ténèbres.','',26972),
(82601,'frFR','Notre dette envers K’ara était grande. Sans lui, mon peuple n’aurait jamais pu fuir Argus, notre monde natal.','',26972),
(82602,'frFR','Voir K’ara ainsi réduit à l’état d’ombre fut un fardeau bien lourd à porter. Lorsqu’il revint auprès de nous… Je fis ce qu’il fallait.','',26972),
(82603,'frFR','N’oubliez pas… La vie est la Lumière, et la Lumière est elle-même la vie. Elles sont interchangeables, mais rien ne se perd jamais.','',26972),
(82676,'frFR','Les ténèbres… approchent…','',26972),
(82677,'frFR','Les ombres se rapprochent !','',26972),
(82678,'frFR','L’Étoile noire arrive…','',26972),
(82679,'frFR','Le Vide engloutira tout…','',26972),
(82684,'frFR','Merci, l’$gami:amie;. Ces fourbes de Chanteguerres, y s’en prennent au pauvre vieux J’wan !','',26972),
(82685,'frFR','Moi j’vais au royaume de Samedi. À la prochaine.','',26972),
(82687,'frFR','SEIGNEUR DE GUERRE MAIN-NOIRE','SEIGNEUR DE GUERRE MAIN-NOIRE',26972),
(82688,'frFR','CHEF DES ORCS ROCHENOIRES','CHEF DES ORCS ROCHENOIRES',26972),
(82711,'frFR','Merci pour la bénédiction, mec. Que le seigneur de la Tombe vous sourie.','',26972),
(82712,'frFR','Mon âme, y a quelque chose à Oshu’gun qui l’appelle. Je dois aller voir.','',26972),
(82714,'frFR','Mais quoi… Je suis mort !','',26972),
(82715,'frFR','J’vais hanter les Chanteguerres pour toujours. Et méfiez-vous du vaudou.','',26972),
(82716,'frFR','AHHHHHHHHHHHHHHHHHHHHHHHH !','AHHHHHHHHHHHHHHHHHHHHHHHH !',26972),
(82847,'frFR','Fureurs du Trône des éléments, nous répondons à votre appel.','',26972),
(82858,'frFR','Commandant ! J’ai accouru dès que j’ai entendu le cri d’agonie de l’ogre. Tout s’est bien passé ?','',26972),
(82860,'frFR','Quelqu’un veut que je l’emmène ?','',26972),
(82963,'frFR','Vous trois ! Suivez le commandant sur le champ de bataille et attendez mon signal.','',26972),
(82964,'frFR','J’ai un plan.','',26972),
(82969,'frFR','Et la Mère corbeau m’a dit : « Krikka, tu es mon cher enfant. Tu vas partir à la recherche de mes autres enfants égarés et les ramener au nid. »','',26972),
(82970,'frFR','Quand toute la Nuée sera réunie, ce sera la fin. Le monde sera déchiré par une grande catastrophe ! N’ayez crainte, car la Mère corbeau nous sauvera !','',26972),
(82971,'frFR','La Mère corbeau descendra des cieux pour ses enfants. Nous nous élèverons sur ses grandes ailes d’ébène pour occuper notre place légitime dans son obscur royaume !','',26972),
(82972,'frFR','En attendant ce jour, louez la Mère corbeau ! Tournez-vous vers sa grande famille pour trouver force et conseils. Puisse-t-elle projeter son ombre sur vous !','',26972),
(82973,'frFR','Scribe ! Tu as tout noté ?','',26972),
(82974,'frFR','Oui, grand corborateur.','',26972),
(82975,'frFR','Louée soit la Mère corbeau !','',26972),
(82993,'frFR','Avec la clé de voûte, vous seul pourrez traverser. Une fois à l’intérieur, désactivez leurs boucliers et nous vous rejoindrons.','',26972),
(83044,'frFR','','Ared n’aimerait pas me voir plantée là à pleurnicher. Allons donc à votre armurerie.',26972),
(83045,'frFR','','C’est absolument incroyable ! Si seulement Ared pouvait être là pour voir ça. Il serait tellement fier !',26972),
(83047,'frFR','Les quais. Courez vers les quais. Courez… COUREZ !','',26972),
(83048,'frFR','Viens donc à moi, Hurlenfer !','',26972),
(83049,'frFR','Ne sois pas stupide, Ga’nar… cours ! Le combat attendra.','',26972),
(83050,'frFR','','Attention !',26972),
(83051,'frFR','','Continuez. Je vois les navires, droit devant.',26972),
(83052,'frFR','Toute leur armée est sur nos talons.','',26972),
(83054,'frFR','Et maintenant… où allons-nous ?','',26972),
(83056,'frFR','Foncez vers les navires au bout de la route.','',26972),
(83057,'frFR','Par ici. Allez, on se dépêche !','',26972),
(83058,'frFR','Vous ne pourrez pas vous cacher, étrangers. C’est MON monde. Nous vous retrouverons !','',26972),
(83060,'frFR','Les Loups-de-Givre t’attendront, Hurlenfer ! Tes ogres, ta Horde de Fer et toi… vous êtes tous des morts en sursis !','',26972),
(83061,'frFR','Ne faites pas attention à ses menaces. Nous allons chercher des renforts en Ombrelune. Cette fois, les Draeneï triompheront.','',26972),
(83062,'frFR','Alors mettons-nous en route. Si nous voulons mettre un terme à la menace, il nous faudra bâtir une forteresse. Et nous allons avoir besoin de l’aide de la population locale.','',26972),
(83063,'frFR','Cap sur Ombrelune !','',26972),
(83064,'frFR','Direction le foyer des Loups-de-Givre !','',26972),
(83102,'frFR','','Je vais avancer et observer leurs portes pendant que vous neutralisez les catapultes. Dioniss aca.',26972),
(83105,'frFR','','Commandant, par ici !',26972),
(83106,'frFR','','Cette barrière magique est trop solide pour nos explosifs. Je n’ai pas trouvé moyen de la faire tomber ; il va donc falloir la contourner.',26972),
(83127,'frFR','Leurs maudites troupes vont se pointer d’une minute à l’autre. Il faut se remuer !','',26972),
(83132,'frFR','Dispositif d’évacuation du personnel activé.','',26972),
(83145,'frFR','','Par la Lumière, quel combat épique !',26972),
(83154,'frFR','','Allons-y !',26972),
(83203,'frFR','C’était… moins une.','',26972),
(83204,'frFR','Pas de retour en arrière. On continue, droit dans la gueule du loup.','',26972),
(83255,'frFR','Qui aurait cru que les Draeneï cachaient des trésors aussi… délicieux dans leur temple ?','',26972),
(83256,'frFR','Vous osez me défier, défenseurs d’Auchindoun ?','',26972),
(83257,'frFR','Libérez-moi de mes liens… et c’en sera fini du Portail…','',26972),
(83258,'frFR','Quelle décadence… Tout sera consumé.','',26972),
(83259,'frFR','Oui… Oui !','',26972),
(83260,'frFR','Grommash paiera pour son arrogance.','',26972),
(83261,'frFR','La légion vient vous chercher… Nous nous repaîtrons de ces âmes.','',26972),
(83262,'frFR','Ne perdez pas de temps. Je sens les forces de vos armées décliner. Vous aurez tout loisir de vous morfondre plus tard…','',26972),
(83263,'frFR','Nous nous retrouverons…','',26972),
(83264,'frFR','Gul’dan… quelle inconscience. Ce don… est bien plus puissant que ce que tu pouvais imaginer.','',26972),
(83265,'frFR','J’ai attendu bien longtemps…','',26972),
(83266,'frFR','J’étais affamé… de pouvoir…','',26972),
(83268,'frFR','Mais désormais, tous se soumettront à moi !','',26972),
(83282,'frFR','Mes entraves vont céder. Je serai bientôt libre !','',26972),
(83285,'frFR','Que tout le monde se mette à couvert !','',26972),
(83312,'frFR','','Il révèle notre position. Cet imbécile a mené un génésaure droit vers nous.',26972),
(83324,'frFR','Qu’avons-nous là ? En Gorgrond, les héros ne font pas de vieux os, vous savez.','',26972),
(83338,'frFR','Ils ont ouvert le feu sur le Voile Akraz !','',26972),
(83339,'frFR','Il a disparu… Comme ça…','',26972),
(83340,'frFR','Venez, ne restons pas là !','',26972),
(83386,'frFR','Enfin libre.','',26972),
(83387,'frFR','Par l’esprit de mon père, ILS VONT LE PAYER… J’en fais le serment.','',26972),
(83388,'frFR','Gah !','',26972),
(83389,'frFR','Argh… oh !','',26972),
(83390,'frFR','Eh bien…','',26972),
(83391,'frFR','Je dirais que notre action a eu un certain impact.','',26972),
(83406,'frFR','On dirait que nous sommes arrivés juste à temps.','',26972),
(83431,'frFR','Enfin libre ! Rejoignez-moi au tertre des ogres quand vous aurez terminé, et nous tuerons leur chef ensemble.','',26972),
(83635,'frFR','Ramène-les-moi vivants, Roltall. Ils pourraient rapporter gros.','',26972),
(83688,'frFR','La Horde de Fer est entrée sur nos rives. Nous allons le lui faire regretter.','',26972),
(83711,'frFR','Par ici !','',26972),
(83718,'frFR','Ne nous attardons pas. Nous aurons bientôt la Horde de Fer tout entière sur le dos.','',26972),
(83719,'frFR','Quelqu’un doit rester en arrière et semer la confusion dans le camp ennemi. Les autres iront se mettre à l’abri dans la jungle.','',26972),
(83720,'frFR','Bonne chance.','',26972),
(83721,'frFR','Bon courage.','',26972),
(83762,'frFR','AAAAAAHHHHHHHHHH !','',26972),
(83774,'frFR','','Exarque, demandez à vos lieurs d’âme de me rejoindre à mon camp. Je compte arrêter Teron’gor avant qu’il ne libère d’autres démons.',26972),
(83775,'frFR','Nous devons arrêter Teron’gor avant que ce monde ne soit détruit comme tant d’autres.','',26972),
(83778,'frFR','Ne vous inquiétez pas. Nous sommes là pour vous couvrir !','',26972),
(83834,'frFR','','Allez, on doit se mettre en route fissa !',26972),
(83847,'frFR','Et voilà, mademoiselle Sifflepince !','',26972),
(83848,'frFR','','Pas trop tôt ! Venez, Gazvanne.',26972),
(83849,'frFR','','Bien sûr, madame.',26972),
(83850,'frFR','','Je te superviserai, cette question ! Maintenant, remue-toi !',26972),
(83959,'frFR','Bien joué, $n.','',26972),
(83960,'frFR','Cette grotte va nous être bien utile.','',26972),
(84009,'frFR','Suivez-moi de près.','',26972),
(84020,'frFR','Tuez cent adversaires ou mourez en essayant !','',26972),
(84021,'frFR','Désolé, mais nous allons clairement manquer de temps…','',26972),
(84022,'frFR','Hum. Ça ne fait que quatre-vingt-dix-neuf, sorcier.','',26972),
(84023,'frFR','Alors j’imagine que nous vous en devons encore un.','',26972),
(84024,'frFR','Tous avec moi !','',26972),
(84025,'frFR','Vite ! Dans la grotte, avant que la glace ne fonde.','',26972),
(84062,'frFR','Nous avons fait tout notre possible là-haut…','',26972),
(84086,'frFR','Poursuivez-les ! Ne les laissez pas s’échapper !','',26972),
(84108,'frFR','Je pourrais vous regarder combattre pendant des heures, bande de rats.','',26972),
(84122,'frFR','Exarque Maladaar, allez explorer la grotte avec Qiana.','',26972),
(84123,'frFR','À vos ordres.','',26972),
(84124,'frFR','$n, j’ai un travail spécial à vous confier.','',26972),
(84125,'frFR','Dame Liadrin, allez explorer la grotte avec Olin.','',26972),
(84126,'frFR','','À vos ordres.',26972),
(84248,'frFR','Fini de courir, bande de rats.','',26972),
(84249,'frFR','Pas si vite, Ner’zhul.','',26972),
(84250,'frFR','Oui… approchez ! Je vais vous enterrer vivants pour la Horde de Fer !','',26972),
(84268,'frFR','Pathétique…','',26972),
(84374,'frFR','Je les ai vus en rêve… des étrangers d’un autre monde, qui venaient réduire à néant tout ce pour quoi nous avions combattu.','',26972),
(84375,'frFR','Mais c’est du sang orc qui coule dans les veines de Draenor !','',26972),
(84376,'frFR','En avant, soldats de la Horde de Fer ! Allons anéantir l’ennemi.','',26972),
(84377,'frFR','Pour la gloire de Grommash !','',26972),
(84445,'frFR','Où est mon pouvoir, ogre ?','',26972),
(84446,'frFR','Ton pouvoir ? (C’est le MIEN !)','',26972),
(84447,'frFR','Tu vas obéir, disciple. Donne-moi la bride.','',26972),
(84448,'frFR','Je ne crois pas. (On ne suit plus tes ordres !)','',26972),
(84463,'frFR','Nous avons beaucoup appris de K’ure. (De quoi écrire un livre.)','',26972),
(84464,'frFR','Tu es fou à lier.','',26972),
(84465,'frFR','Fuis, vieux fou… (Bientôt, Cognefort brûlera. Et le monde suivra !)','',26972),
(84566,'frFR','La mort… me libère…','',26972),
(84576,'frFR','Ces lâches nous utilisaient comme catalyseurs pour alimenter leur porte et ils vont le regretter.','',26972),
(84577,'frFR','Le Conseil des ombres vous remercie.','',26972),
(84580,'frFR','Cherchez Gul’dan, si vous voulez vraiment arrêter la Horde de Fer. (Gul’dan ! Gul’dan alimente la porte !)','',26972),
(84581,'frFR','Gul’dan ! Gul’dan alimente la porte !','',26972),
(84658,'frFR','Je dois reconnaître qu’il y avait une pointe de vérité dans les divagations de Socrethar.','',26972),
(84659,'frFR','Il a remis en cause notre relâchement. Peut-être avons-nous été trop satisfaits, trop en sécurité, cachés ici sur Draenor.','',26972),
(84660,'frFR','Quelque chose nous attend, $ghéros:héroïne;. Je le ressens, juste au-delà de l’horizon. Et quand l’heure arrivera, les Draeneï devront se tenir prêts.','',26972),
(84662,'frFR','','Aujourd’hui, nous avons vaincu l’un des plus puissants alliés de Gul’dan.',26972),
(84663,'frFR','','Sans leur commandant, les sargereï ne tiendront pas longtemps. Les Auchenaï pourront bientôt reprendre possession de leur ville.',26972),
(84665,'frFR','','Pour l’instant, considérons qu’il s’agit d’une victoire monumentale. Merci, $ghéros:héroïne;.',26972),
(84866,'frFR','Nous n’avons pas le choix, nous devons nous replier. Que tout le monde me suive !','',26972),
(84872,'frFR','Cho’gall !','',26972),
(84873,'frFR','Gardes ! Arrêtez-le !','',26972),
(84874,'frFR','Scellez les portes ! Protégez le palais ! Cognefort ne tombera jamais entre vos mains.','',26972),
(84883,'frFR','Tu pensais nous emprisonner, Mar’gok ? (Tu n’as jamais pu nous contrôler !)','',26972),
(84884,'frFR','Détruisez-les tous. Rasez la ville ! (Les pierres seront à nous ! Tous succomberont aux ténèbres !)','',26972),
(85014,'frFR','Les opérations à Tanaan se déroulent bien. La citadelle sera bientôt opérationnelle.','',26972),
(85015,'frFR','J’ai les ogres de Cognefort à l’œil, chef de guerre. Pour l’instant, ils se montrent… obéissants.','',26972),
(85016,'frFR','Et de ton côté, Main-Noire ?','',26972),
(85017,'frFR','Les forces de l’Alliance et de la Horde ont pris la fonderie pour cible, mais je vais m’occuper d’eux.','',26972),
(85018,'frFR','Encore ? Tes promesses sonnent comme des excuses.','',26972),
(85019,'frFR','Azuka ! Comment se déroulent les recherches pour l’alpha ?','',26972),
(85020,'frFR','','Bien, chef de guerre. Nous n’avons plus besoin que du cœur de Gorgorek pour lui donner vie.',26972),
(85021,'frFR','Bien. Tu peux t’occuper de ces étrangers d’un autre monde ? Ou manques-tu de la fureur sanguinaire de tes ancêtres ?','',26972),
(85022,'frFR','','Je surpasse mes aïeux, chef de guerre. Je vais réparer les erreurs de Main-Noire.',26972),
(85023,'frFR','Je vais t’arracher la langue pour ça !','',26972),
(85024,'frFR','Hahaha… des paroles audacieuses pour mon nouveau seigneur de guerre. Très bien.','',26972),
(85026,'frFR','Brandis ta lame. Plonge-la dans le sang de nos ennemis. Montre-moi sa puissance légendaire.','',26972),
(85027,'frFR','Fais tes preuves, Azuka, et j’envisagerai de t’élever au rang de seigneur de guerre.','',26972),
(85028,'frFR','','Ne te fais pas de souci, minable. Je ne t’ai pas oublié. Je m’occuperai de toi… plus tard.',26972),
(85041,'frFR','Tenez bon, $Gmessire:gente dame;. Je suis là pour vous aider.','',26972),
(85049,'frFR','Ne vous inquiétez pas pour moi. Je connais bien le coin.','',26972),
(85050,'frFR','Je vais fouiner dans les parages. Voyez si vous pouvez trouver quoi que ce soit ailleurs dans le camp.','',26972),
(85052,'frFR','Que savez-vous des plans de Grommash Hurlenfer ?','Que savez-vous des plans de Grommash Hurlenfer ?',26972),
(85058,'frFR','Grommash Hurlenfer a tenu conseil avec ses seigneurs de guerre : Main-Noire, Kargath Lamepoing, Kilrogg Œil-Mort et Azuka Lames-Furieuses. Il faut se méfier d’Azuka… on dirait qu’elle a été chargée d’anéantir les forces de l’Alliance sur Draenor.','',26972),
(85060,'frFR','<Une note est rédigée sur un morceau de papier :$B$BNous avons découvert Gorgorek le Tranche-monde, un magnaron sans âge prisonnier des bassins de pierre de Gorgrond.$B$BLes anciens chanteguerres pensent qu’il était autrefois un puissant alpha, une créature supérieure capable de régir ses semblables.$B$BD’après les données dont dispose le clan, il serait possible d’éveiller ce monstre.>','<Une note est rédigée sur un morceau de papier :$B$BNous avons découvert Gorgorek le Tranche-monde, un magnaron sans âge prisonnier des bassins de pierre de Gorgrond.$B$BLes anciens chanteguerres pensent qu’il était autrefois un puissant alpha, une créature supérieure capable de régir ses semblables.$B$BD’après les données dont dispose le clan, il serait possible d’éveiller ce monstre.>',26972),
(85061,'frFR','<Des feuilles de papier entourent la carte de la fonderie des Rochenoires. On dirait des ordres de construction de machines de guerre.>','<Des feuilles de papier entourent la carte de la fonderie des Rochenoires. On dirait des ordres de construction de machines de guerre.>',26972),
(85062,'frFR','<Sur cette carte, bon nombre de marques ont été faites dans le périmètre de la jungle de Tanaan. On y trouve entre autres des représentations de fortifications et des indications relatives aux mouvements de troupes. Hurlenfer a l’air de s’intéresser de près à la région.>','<Sur cette carte, bon nombre de marques ont été faites dans le périmètre de la jungle de Tanaan. On y trouve entre autres des représentations de fortifications et des indications relatives aux mouvements de troupes. Hurlenfer a l’air de s’intéresser de près à la région.>',26972),
(85098,'frFR','','Kajassa est là, mec. J’viens vous aider.',26972),
(85099,'frFR','','Chhuuut… les yeux et les oreilles, on les garde grands ouverts.',26972),
(85109,'frFR','J’ai entendu parler du seigneur de guerre Lames-Furieuses. C’est vraiment une fine lame, Même dans les autres clans orcs, personne peut la vaincre. Ceux qui la sous-estiment, ils meurent.','',26972),
(85110,'frFR','Elle est ambitieuse, maline et cruelle, aussi. Maintenant qu’elle est devenue seigneur de guerre, on a intérêt à faire attention, ça oui.','',26972),
(85111,'frFR','J’ai entendu parler du seigneur de guerre Lames-Furieuses. Cette Orque est une véritable virtuose de la lame. Nombreux sont ceux qui la sous-estiment, mais elle reste invaincue au sein de son peuple. ','',26972),
(85112,'frFR','Elle est ambitieuse, intelligente et cruelle. Maintenant qu’elle a accédé au pouvoir, je crains que nous ne soyons forcés de l’affronter bientôt.','',26972),
(85175,'frFR','Chacun est à sa place ? Bien, nous pouvons commencer !','',26972),
(85179,'frFR','« Le temps ne suspend son vol pour personne. » est-il écrit dans le tome des Averses de sable. La Mère corbeau savait qu’une personne n’appartenant pas à la Nuée viendrait nous aider à accomplir le rituel ! Oh, vous êtes $gbéni:bénie; entre tous vos semblables !','',26972),
(85270,'frFR','Allez-y !','',26972),
(85374,'frFR','[Placeholder Scene!]','',26972),
(85430,'frFR','Que peuvent faire quelques esclaves face à la machine de guerre rochenoire ?','',26972),
(85431,'frFR','Rochenoires… ÉCRASEZ-LES !','',26972),
(85560,'frFR','Khadgar ! Sortez-nous d’ici !','',26972),
(85680,'frFR','','C’est donc vrai. Le cœur a le pouvoir d’insuffler la vie à ces créatures.',26972),
(85681,'frFR','','Ah, noble $ghéros:héroïne;… je savais que vous viendriez. Vous arrivez juste à temps pour être témoin de la puissance du cœur.',26972),
(85682,'frFR','','Ce magnaron foulait la surface de Draenor longtemps avant l’apparition du premier orc. Et maintenant, le voilà… lui et une armée innombrable de ces destructeurs… pliés à MA volonté !',26972),
(85683,'frFR','','Suivez-moi, $n. Elle se trouve dans cette direction.',26972),
(85700,'frFR','Mais avant ça… il faut que j’aille me laver les mains. Je vous rejoindrai à votre camp.','',26972),
(85708,'frFR','Commandant, quelque chose ne va pas ?','',26972),
(85734,'frFR','','Argh ! On dirait que nous allons devoir nous occuper de ce gronn.',26972),
(85735,'frFR','','Enfin, ça fait au moins un problème de réglé. Venez, $gchampion:championne;, nous ferions bien d’aller présenter notre rapport au quartier général.',26972),
(85811,'frFR','Comment les choses avancent-elles ? J’espère que les nouvelles seront meilleures que la fois dernière !','',26972),
(85812,'frFR','','Nous avons découvert comment asservir mentalement les gronns.',26972),
(85813,'frFR','Bien… terminez votre travail et amenez-les-moi.','',26972),
(85814,'frFR','','À vos ordres, commandant Gar.',26972),
(86013,'frFR','Des kilomètres de terres mortelles nous séparent encore des Rochenoires.','',26972),
(86015,'frFR','','Nous aurions dû venir avec une armée pour affronter la Horde de Fer !',26972),
(86019,'frFR','','Ta taille est ta faiblesse, géant.',26972),
(86074,'frFR','Ils ont pris le caporal Thukmar !','',26972),
(86212,'frFR','','Pour la Lumière !',26972),
(86245,'frFR','Commandant, notre escadron aérien a affaibli le magnaron, mais nous sommes coincés. Nous avons besoin de votre aide pour prendre d’assaut la base principale.','',26972),
(86246,'frFR','Moi, j’aime pas trop la tête qu’il a, ce truc.','',26972),
(86250,'frFR','','Ah, bienvenue, redresseuse de torts. Vous devez être là pour l’épreuve de Maladaar.',26972),
(86251,'frFR','','Les esprits sentent votre motivation. Ils ont hâte de vous mettre au défi.',26972),
(86252,'frFR','','C’est un honneur pour moi d’affronter les héros du passé. J’espère leur faire grande impression.',26972),
(86253,'frFR','','Bonne chance, dame Yrel.',26972),
(86254,'frFR','Yrel, j’espérais bien te voir ainsi un jour. Ne me déçois pas.','',26972),
(86255,'frFR','','Bonjour, maître. Laissez-moi vous montrer ce que j’ai appris.',26972),
(86256,'frFR','Tu as comblé toutes mes attentes, Yrel. Tu peux continuer.','',26972),
(86257,'frFR','','Il est temps d’apporter la paix aux cendres de Maraad.',26972),
(86258,'frFR','Yrel… comme tu as grandi depuis la dernière fois. Mais… est-ce que ça suffira ? Sauras-tu diriger notre peuple ?','',26972),
(86259,'frFR','C’est à mon tour de tester ta force.','',26972),
(86260,'frFR','Quand tu seras confrontée à un adversaire plus puissant, pourras-tu lui faire face ?','',26972),
(86261,'frFR','','N’aie pas peur, je ferai face !',26972),
(86262,'frFR','Quand notre peuple se tournera vers toi, seras-tu prête à lui commander ?','',26972),
(86263,'frFR','','Je ne les abandonnerai pas !',26972),
(86264,'frFR','Quand tout espoir sera perdu, continueras-tu… de te battre ?','',26972),
(86265,'frFR','','Je ne céderai jamais !',26972),
(86266,'frFR','','Je… le pourrai…',26972),
(86267,'frFR','Quand tu regarderas au fond de toi et que tu ne verras que les ténèbres, pourras-tu toujours trouver la Lumière ?','',26972),
(86268,'frFR','Pardon ?','',26972),
(86269,'frFR','','Parce que… dans ce monde… nous ne sommes jamais…',26972),
(86270,'frFR','','Maintenant ! Utilisez le marteau !',26972),
(86271,'frFR','Yrel… c’est vrai. L’étudiante a surpassé le maître. Tu es prête.','',26972),
(86272,'frFR','Si seulement le prophète Velen pouvait te voir aujourd’hui… il serait fier.','',26972),
(86273,'frFR','Lève-toi, Yrel. C’est à toi d’unir les Draeneï. Prépare-les aux évènements à venir.','',26972),
(86274,'frFR','Adieu…','',26972),
(86275,'frFR','','Maraad, mon ami… repose en paix.',26972),
(86276,'frFR','','Merci. Je vous retrouverai plus tard. J’ai besoin d’un moment pour faire mes hommages aux ancêtres.',26972),
(86277,'frFR','Une dernière épreuve t’attend, Yrel. Nous !','',26972),
(86278,'frFR','Tu as choisi ton défenseur. Il est temps de commencer !','',26972),
(86279,'frFR','Aah… je suis vaincu.','',26972),
(86280,'frFR','','Quelle force !',26972),
(86281,'frFR','J’admets ma défaite !','',26972),
(86282,'frFR','Yrel. Aujourd’hui, tu as surmonté les épreuves de l’exarque.','',26972),
(86283,'frFR','Tu as fait preuve de courage, de bienveillance, de conviction et de force… qui sont les piliers de notre société.','',26972),
(86284,'frFR','Toutefois, un dirigeant n’est pas jugé qu’à son mérite, mais aussi à celui de ses compagnons.','',26972),
(86285,'frFR','Quant à vous, nous avons également jugé vos actes pendant ces épreuves.','',26972),
(86286,'frFR','Nous avons tous constaté votre bravoure, votre loyauté et votre persévérance.','',26972),
(86287,'frFR','Votre dévouement envers Yrel nous prouve à tous sa valeur. C’est vous qui avez choisi la prochaine exarque. ','',26972),
(86288,'frFR','Yrel, un dirigeant exceptionnel inspire les gens qui l’entourent. Aie confiance en ton peuple et en toi-même. ','',26972),
(86289,'frFR','Maintenant, lève-toi…','',26972),
(86290,'frFR','EXARQUE YREL !','',26972),
(86294,'frFR','','Contemplez celui par qui vous perdrez tout, héros.',26972),
(86295,'frFR','','Ce magnaron vivait sur Draenor bien avant la naissance du premier orc. Et maintenant, il est sous mon contrôle.',26972),
(86296,'frFR','','Il écrasera vos ennemis et votre pitoyable forteresse. Mais tout d’abord, il va vous écraser, VOUS !',26972),
(86297,'frFR','La bête est vaincue, mais ce n’est pas terminé. Il nous reste un adversaire à affronter.','',26972),
(86298,'frFR','Ma présence est requise aux portes. On a aperçu le chef de guerre Hurlenfer sur le champ de bataille.','',26972),
(86299,'frFR','Trouvez Lames-Furieuses. Rapportez-moi sa tête !','',26972),
(86300,'frFR','Taz’dingo ! Bien combattu, mec. Mais on part pas avant que cette saleté d’Orque elle soit morte.','',26972),
(86301,'frFR','On a besoin de moi à la porte principale. Les gars, ils disent que Grommash a rejoint le combat.','',26972),
(86302,'frFR','Occupez-vous de Lames-Furieuses. Sa tête, z’allez me la rapporter !','',26972),
(86303,'frFR','','J’en ai assez de ces petits jeux, méprisable parasite. Il est temps d’en finir.',26972),
(86304,'frFR','','Ma lame réclame votre sang !',26972),
(86305,'frFR','','Non… noooon… chef de guerre… j’ai manqué… à mes devoirs…',26972),
(86306,'frFR','','Halte ! Hurlenfer approche.',26972),
(86307,'frFR','Regardez ! Hurlenfer se montre enfin.','',26972),
(86308,'frFR','','La bataille touche à son terme ! Nous avons vaincu la Horde de Fer et repoussé ses troupes aux portes !',26972),
(86309,'frFR','La Horde de Fer n’est jamais vaincue ! Je ne me rendrai JAMAIS !','',26972),
(86310,'frFR','Je n’oublierai pas ce jour, héros. Je me souviendrai de vos noms et de vos visages… et le moment venu, je vous massacrerai les uns après les autres.','',26972),
(86373,'frFR','L’entrée du hall principal s’ouvre !','',26972),
(86374,'frFR','La barrière qui se trouve derrière l’exarque Hataaru s’ouvre !','',26972),
(86377,'frFR','Le téléporteur menant à la plateforme centrale est désormais opérationnel !','',26972),
(86467,'frFR','','SEULS !',26972),
(86586,'frFR','Merci $gl’ami:l’amie; ! Vous m’avez sauvé la mise !','',26972),
(86635,'frFR','Connaissance et stratégie jouent pour moitié dans une victoire.','',26972),
(86636,'frFR','Restez sur le qui-vive, commandant.','',26972),
(86637,'frFR','Ça commence à chauffer. Nous devons effectuer une percée !','',26972),
(86638,'frFR','C’est l’occasion de disperser les troupes de la Horde de Fer. Préparez-vous. Nous devons tenir la ligne de front !','',26972),
(86673,'frFR','Bonne chance, $R. Je vais tâcher de trouver un bon feu auprès duquel me réchauffer !','',26972),
(86678,'frFR','','Bonne chance, $R. N’oubliez jamais que le temps est votre bien le plus précieux ! Ne le perdez jamais !',26972),
(86715,'frFR','Si vous osez me défier, vous me trouverez dans la jungle de Tanaan. Au-delà de ces portes, seule la mort vous attend.','',26972),
(86747,'frFR','','Suivez-moi, $gchampion:championne; !',26972),
(86748,'frFR','','Abandonne, Grommash ! Regarde autour de toi. Tu es vaincu !',26972),
(86749,'frFR','','Comme tu veux, Grommash. Tu n’attendras pas longtemps.',26972),
(86750,'frFR','','Félicitations ! À nous la victoire !',26972),
(86775,'frFR','Commandant, nos chevaucheurs de rylaks ont affaibli le magnaron, mais on est coincés. On a besoin d’votre aide pour pénétrer dans la base principale.','',26972),
(86786,'frFR','','La bataille touche à son terme ! Nous avons repoussé les troupes de la Horde de Fer jusqu’aux portes.',26972),
(86788,'frFR','Rends les armes, Grommash ! Regarde autour de toi. Tu es fini.','',26972),
(86789,'frFR','Comme tu veux, Grommash. Attends, car nous viendrons te voir.','',26972),
(86790,'frFR','Merci à vous. Aujourd’hui, nous savourons notre victoire ! Lok’tar ogar !','',26972),
(86947,'frFR','Ma prochaine mascotte sera plus difficile à battre !','',26972),
(86948,'frFR','À la guerre comme dans ce genre de combat, tous les coups sont permis.','',26972),
(86949,'frFR','Quoi ? Comment ?? Je me vengerai, bougre de foie jaune !','',26972),
(86950,'frFR','Encore un combat épique que je remporte haut la main, sans surprise !','',26972),
(86951,'frFR','Préparez-vous à prendre la raclée de votre vie !','',26972),
(86952,'frFR','Ah, vous avez de la chance que je me sois laissé déconcentrer !','',26972),
(86958,'frFR','Aussi puissant que je puisse être, je n’ai pas le don d’ubiquité.','',26972),
(86959,'frFR','Mais vous, commandant, vous êtes ma pièce maîtresse. Entre les atouts de vos alliés et la puissance de votre fief, pas une seule forteresse ne pourra vous résister.','',26972),
(86960,'frFR','Sous votre commandement, la pleine puissance de l’Alliance affrontera la Horde de Fer.','',26972),
(86961,'frFR','Sous votre commandement, les meilleurs guerriers de la Horde affronteront Grommash et son armée.','',26972),
(86962,'frFR','Pendant ce temps, je me concentrerai sur la plus grande menace pour la sécurité d’Azeroth :','',26972),
(86963,'frFR','Gul’dan, les ténèbres incarnées.','',26972),
(86964,'frFR','De toute ma vie, je n’ai jamais rencontré ennemi aussi rusé et diabolique que Gul’dan. Je me tiens pour responsable de sa libération.','',26972),
(86965,'frFR','Nous devons trouver et éliminer Gul’dan, ainsi que son tout jeune réseau du Conseil des ombres.','',26972),
(86966,'frFR','Avec votre aide, je peux le retrouver. Je vais vous demander beaucoup, vous mener aux limites de vos capacités.','',26972),
(86967,'frFR','Mais je vous aiderai autant que je le peux. Ensemble, nous créerons pour vous une relique d’une puissance légendaire.','',26972),
(86968,'frFR','Le cœur forgé dans le noyau du soleil de Draenor, cet anneau est la prémisse d’une merveille de puissance. ','',26972),
(86969,'frFR','…Voilà, c’est fait. Maintenant, trouvons Gul’dan.','',26972),
(86970,'frFR','Suivez-moi, commandant !','',26972),
(86971,'frFR','Une fois que nous aurons localisé Gul’dan, nous devrons agir rapidement…','',26972),
(86972,'frFR','Mes yeux sont ouverts. Van Shalach, om Aeschis, Khaz’tolim !','',26972),
(86973,'frFR','Allez, allez… Où es-tu…','',26972),
(86974,'frFR','Attendez… ici… qu’est-ce que… ?','',26972),
(86975,'frFR','Il se cache ! Il contre mon sort.','',26972),
(86976,'frFR','Tuer Teron’gor a dû le secouer. C’est très bien. Mais maintenant, il sait que nous nous rapprochons.','',26972),
(86977,'frFR','Nous avons besoin de plus de puissance !','',26972),
(86979,'frFR','','Nous vous suivrons depuis les airs !',26972),
(86980,'frFR','La piste ne sera pas facile à suivre. Dirigez-vous vers l’est.','',26972),
(86981,'frFR','','Suivez les anomalies temporelles comme celle-ci.',26972),
(86982,'frFR','','Là ! On dirait que Garrosh a suivi cette voie seul après son arrivée sur Draenor. Mais où a pu passer Kairoz ?',26972),
(86983,'frFR','Regardez Garrosh. Ses mains sont liées, mais il est seul. Quand Kairoz et lui se sont-ils séparés ?','',26972),
(86984,'frFR','','Hmmm… cet ogre ne devrait pas être là. Quelque chose d’étrange s’est produit sur cette crête.',26972),
(86985,'frFR','Qui est-ce ?','',26972),
(86986,'frFR','','C’est Kairoz, qui était déguisé. Garrosh l’a tué ! Mais où est son corps ?',26972),
(86987,'frFR','Nous ne devons plus être loin !','',26972),
(87018,'frFR','Je sais comment vaincre Gul’dan et démasquer le Conseil des ombres. Mais nous aurons besoin de plus de puissance.','',26972),
(87020,'frFR','Nous allons devoir dérober des artéfacts au cœur de l’empire ogre.','',26972),
(87021,'frFR','Je peux vous aider. Augmentons la puissance de votre anneau…','',26972),
(87022,'frFR','Tendez votre main et placez-vous dans la lumière !','',26972),
(87023,'frFR','Je suis désolé, j’aurais dû vous prévenir que ce serait… légèrement mortel.','',26972),
(87026,'frFR','Merveilleux. Nous avons tout ce dont nous avions besoin !','',26972),
(87027,'frFR','Gul’dan ne pourra pas se soustraire à mon regard, cette fois.','',26972),
(87028,'frFR','','Archimage, soyez prudent.',26972),
(87030,'frFR','Il est exactement où nous le souhaitions !','',26972),
(87031,'frFR','Mes yeux sont ouverts. Val’mir, khar abra, mal ozymius…','',26972),
(87032,'frFR','Viens...viens par là… je vais te trouver…','',26972),
(87033,'frFR','… là ! Gul’dan ! Il est…','',26972),
(87034,'frFR','Toi ! Le mage humain de Tanaan…','',26972),
(87035,'frFR','Je t’ai trouvé !','',26972),
(87036,'frFR','Je me suis renseigné, « Khadgar ». Il semblerait que nous ayons un passé commun.','',26972),
(87037,'frFR','Alors tu sais comment ça finit. Rends-toi.','',26972),
(87038,'frFR','Ta magie de pacotille marche dans les deux sens. Moi aussi, je t’ai trouvé.','',26972),
(87039,'frFR','','Archimage, attention !',26972),
(87040,'frFR','Stupide mage. Ta mort sera lente et douloureuse. J’aimerais tellement être là pour y assister.','',26972),
(87041,'frFR','','L’archimage… Aidez-moi !',26972),
(87055,'frFR','','Ne bougez pas Khadgar. La dague de Garona était enchantée.',26972),
(87056,'frFR','%s pousse un grognement de douleur.','',26972),
(87057,'frFR','','Cette blessure n’est pas belle à voir. Vous devriez consulter un prêtre.',26972),
(87061,'frFR','Non… Pas de prêtre. Cordana, suturez ma plaie.','',26972),
(87072,'frFR','Venez par ici. Ça ne fera pas mal… enfin pas trop.','',26972),
(87073,'frFR','Ce pouvoir était autrefois réservé au roi-sorcier. Je le place aujourd’hui entre vos mains.','',26972),
(87074,'frFR','Omnivus, al-vitrade ! Arcanum totalus!','',26972),
(87075,'frFR','','Ce sont des forces dangereuses que vous manipulez, archimage.',26972),
(87076,'frFR','C’est nécessaire. Les épreuves les plus dures sont encore à venir.','',26972),
(87085,'frFR','','Je vais vous garder à l’œil.',26972),
(87086,'frFR','','Bonne chance. Faites attention dans cette fonderie !',26972),
(87087,'frFR','Maintenant, ne bougez plus.','',26972),
(87088,'frFR','Cette magie est très fiable. Elle peut être légèrement… fatale. Arrêtez de bouger !','',26972),
(87089,'frFR','Je puise ma force dans le CŒUR de Draenor…','',26972),
(87090,'frFR','Viens, Grommash. Bois.','',26972),
(87091,'frFR','Je t’ai dit… de partir !','',26972),
(87092,'frFR','Ils assaillent ta fonderie. Ils tuent tes alliés. Tu sais que c’est la seule solution.','',26972),
(87093,'frFR','Va-t-en !','',26972),
(87095,'frFR','','Ça a marché.',26972),
(87096,'frFR','J’ai toujours un défibrillateur gobelin sur moi pour ce genre d’urgences. Vous allez bien, commandant ?','',26972),
(87098,'frFR','Venez avec moi. Gul’dan ne laissera pas sa prisonnière lui échapper sans résister.','',26972),
(87099,'frFR','','Tue-moi et qu’on en finisse, archimage.',26972),
(87100,'frFR','Je ne suis pas venu te tuer, assassine.','',26972),
(87101,'frFR','','%s se tord de douleur.',26972),
(87102,'frFR','Où est ton maître ? Réponds !','',26972),
(87103,'frFR','','Va… brûler… en enfer…',26972),
(87104,'frFR','Après toi. Maintenant, où est Gul’dan ?','',26972),
(87105,'frFR','','Rhaaa… Il… te détruira…',26972),
(87106,'frFR','Où se cache-t-il ?','',26972),
(87107,'frFR','','Archimage…',26972),
(87108,'frFR','RÉPONDS !','',26972),
(87109,'frFR','','%s se prend la tête entre les mains.',26972),
(87110,'frFR','','Arrêtez, Khadgar ! Quelle différence y a-t-il avec de la torture ?',26972),
(87111,'frFR','Mais elle sait…','',26972),
(87112,'frFR','','Je ne sais même plus pourquoi vous vous battez.',26972),
(87113,'frFR','Vous… vous avez raison. Gul’dan a déjà détruit son esprit.','',26972),
(87114,'frFR','Je suis désolé, Garona. Nous trouverons un autre moyen.','',26972),
(87156,'frFR','Si c’est ce « cœur de Gorgorek » qu’elle cherche, il faut le trouver avant elle. Dès que j’en saurai plus, je vous ferai part de mes informations.','',26972),
(87157,'frFR','Commandant, ce sera une campagne interminable. Je devrais pouvoir vous donner plus d’informations d’ici une semaine.','',26972),
(87158,'frFR','Si elle et la Horde de Fer, ils cherchent ce « cœur de Gorgorek », alors nous, on doit le trouver d’abord. Je vous préviendrai quand j’en saurai plus là-dessus.','',26972),
(87159,'frFR','Commandant, ce sera super long comme campagne. J’aurai plus d’infos pour vous dans une semaine.','',26972),
(87198,'frFR','On dirait que tout le monde est en position. Ka’alu, donnez le signal et sortez-nous de là !','',26972),
(87393,'frFR','Il reste des troupes de la Horde de Fer dans la cour nord.','',26972),
(87419,'frFR','Gro le Démolisseur, entends mon appel !','',26972),
(87420,'frFR','Les esprits des Crânes-Ricanants ont parlé. Nous devons unir nos forces pour affronter notre ennemi commun : la Horde de Fer !','',26972),
(87421,'frFR','Oui ! Ça marche ! Les esprits avaient raison !','',26972),
(87423,'frFR','Xuk…','',26972),
(87447,'frFR','Ah la voilà. C’est MA relique. Qu’est-ce qui m’a pris de confier à Brak un objet de cette valeur ?','',26972),
(87448,'frFR','Dommage que vous arriviez trop tard pour m’arrêter. Rendez-moi l’artéfact, et je vous laisserai repartir en vie.','',26972),
(87449,'frFR','Hahahaha, comme vous voulez ! HORDE DE FER, EN AVANT !','',26972),
(87450,'frFR','Contemplez l’arsenal que je possède !','',26972),
(87451,'frFR','Vous ne faites pas le poids face à Goc !','',26972),
(87452,'frFR','LIBÉREZ LES ÉTOILES DE FER !','',26972),
(87453,'frFR','Gronnlins, à l’attaque !','',26972),
(87454,'frFR','RAAH… INCROYABLE ! Vous allez payer votre insolence ! JE VAIS VOUS DÉMEMBRER !','',26972),
(87455,'frFR','NON !!! Je préfère MOURIR que vous céder ce qui m’appartient ! VOUS NE…GAGNEREZ…PAS…CETTE… GUERRRRR~~~ !!! ARRRRGHHHH !','',26972),
(87456,'frFR','HAHAHAHA. On commence à avoir peur, pas vrai ?! Affrontez-moi à la loyale, lâches !','',26972),
(87556,'frFR','Les Crânes-Ricanants renaîtront !','',26972),
(88053,'frFR','','C’est fini. Quant à vous, ce n’est que justice que l’un de mes instruments se débarrasse des autres.',26972),
(88605,'frFR','Pour Skettis !','',26972),
(88606,'frFR','Vous faites trop confiance à vos yeux, imbécile.','',26972),
(88712,'frFR','','La Lumière triomphe, parce que nous nous dressons face aux ténèbres.',26972),
(88942,'frFR','','Mais que sont ces créatures ?',26972),
(88945,'frFR','Vas-y, Ga’nar. Empare-toi du clan. Tue ton propre frère de sang froid. Nous verrons qui te suivra, après ça.','',26972),
(88946,'frFR','Tu crois que c’est ÇA que père voulait ?','',26972),
(88948,'frFR','Mon totem vous donnera plus de puissance.','',26972),
(88949,'frFR','Restez à proximité du totem pour puiser sa force !','',26972),
(88950,'frFR','Ne vous éloignez pas du totem pour bénéficier de ses pouvoirs.','',26972),
(89096,'frFR','','Mes loups vont mettre vos mascottes en pièces !',26972),
(89106,'frFR','','%s fixe sur vous un regard des plus sombres.',26972),
(89372,'frFR','En route… Vous savez ce que vous avez à faire. Moi, je pars pour Tanaan.','',26972),
(89379,'frFR','J’espère simplement que mon peuple comprendra.','',26972),
(90001,'frFR','','Oh, ça promet d’être intéressant. J’espère que ça ne vous dérange pas que je prenne des notes ?',26972),
(90002,'frFR','','À voir le résultat, j’imagine que ces artéfacts étaient chers aux cœurs de leurs inventeurs respectifs ! Et euh, désolée pour vos mascottes.',26972),
(90003,'frFR','','Des résultats pour le moins intéressants. Merci de m’avoir aidée à tester ça !',26972),
(90004,'frFR','','À quoi vous attendiez-vous de la part d’une relique enfouie depuis mille ans ?',26972),
(90005,'frFR','','Chez ceux qui en ont la paternité, cette mascotte aurait certainement été considérée comme une martyre.',26972),
(90006,'frFR','','Euh… je me disais bien que ça risquait de se passer comme ça.',26972),
(90007,'frFR','','Heureusement, Gyressieu peut réparer n’importe quoi. Y compris lui-même.',26972),
(90008,'frFR','','Bon… est-ce que ce truc était supposé faire ça… ou est-ce qu’il a juste explosé, tout bêtement ?',26972),
(90009,'frFR','','Encore une victime de la science.',26972),
(90011,'frFR','','J’ai des bandages dans mon paquetage, si vous en avez besoin…',26972),
(90012,'frFR','','L’ingéniosité des créateurs de cet engin impose le respect.',26972),
(90014,'frFR','','Je penserai à remercier votre mascotte dans la préface de mon mémoire de recherche.',26972),
(90019,'frFR','','C’est parti !',26972),
(90020,'frFR','','Oh, mes mascottes ont bien assuré. Je vais leur faire plein de câlins.',26972),
(90021,'frFR','','Oh, bon… c’est la vie. Cela dit, Gribouille va avoir besoin d’un nouvel œil.',26972),
(90022,'frFR','','Ne t’inquiète pas… un gros bisou, et fini le bobo.',26972),
(90023,'frFR','','Qui va avoir droit à une bonne sousoupe pour se requinquer ?',26972),
(90024,'frFR','','Oh, non !',26972),
(90025,'frFR','','Elle n’est pas morte… elle fait juste dodo.',26972),
(90026,'frFR','','On va mettre le bandage arc-en-ciel là-dessus.',26972),
(90028,'frFR','','Votre mascotte aussi, elle fait dodo ?',26972),
(90029,'frFR','','Vous pouvez soigner votre mascotte, pas vrai ?',26972),
(90032,'frFR','','Vous avez de la chance que mes loups n’aient pas encore achevé leur croissance, sinon vous auriez fini en steak tartare.',26972),
(90033,'frFR','','Seule la défaite nous montre où sont nos faiblesses. Cette déculottée leur servira de leçon.',26972),
(90034,'frFR','','Cette mascotte-là était trop stupide.',26972),
(90035,'frFR','','Cette mascotte ne manquait pas de tripes.',26972),
(90036,'frFR','','Cette mascotte ne commettra pas deux fois la même erreur.',26972),
(90037,'frFR','','Cette mascotte était trop lente.',26972),
(90038,'frFR','','Cette mascotte-là va avoir besoin de soins.',26972),
(90039,'frFR','','Belle exécution.',26972),
(90040,'frFR','','Une exécution propre.',26972),
(90041,'frFR','','Un combat dépourvu de piment.',26972),
(90042,'frFR','','Comment se fait-il que vos mascottes soient si faibles ?',26972),
(90043,'frFR','','Une victoire facile. Mes loups n’en apprendront rien.',26972),
(90044,'frFR','Gladiateurs, pas de quartier !','',26972),
(90045,'frFR','Je reste le plus grand seigneur de guerre de Nagrand !','',26972),
(90046,'frFR','Quoi ? Comment est-ce possible ? Vous avez dû tricher !','',26972),
(90047,'frFR','Qu’est-ce qu’un mort pour une armée de trois soldats ?','',26972),
(90048,'frFR','Mes gladiateurs combattront jusqu’à la mort !','',26972),
(90049,'frFR','Vous mettez Tarr en colère !','',26972),
(90050,'frFR','Je t’ai ordonné de tuer, pas de mourir !','',26972),
(90051,'frFR','Ha ha, cette mascotte est aussi pathétique que vous, $R.','',26972),
(90052,'frFR','Victoire écrasante de mon gladiateur !','',26972),
(90053,'frFR','Alors, on s’amuse bien ?','',26972),
(90054,'frFR','Tarr va vous pulvériser !','',26972),
(90055,'frFR','C’est ce qui fait de Tarr le plus grand seigneur de guerre de Nagrand !','',26972),
(90058,'frFR','','Je ne suis pas bien grande, mais si vous faites du mal à mes mascottes, je vous plante.',26972),
(90059,'frFR','','Merci, $gmessire:madame; ! J’avais misé 100 pièces de cuivre sur ce combat.',26972),
(90060,'frFR','','Ça me rappelle la fois où mon village s’est retrouvé envahi par les démons.',26972),
(90061,'frFR','','C’est bon, mes mascottes ont l’habitude de mourir.',26972),
(90062,'frFR','','Ce n’est pas la première fois que quelqu’un fait des pieds et des mains pour lui donner la chasse.',26972),
(90063,'frFR','','Hé, du calme ! Cette mascotte m’a coûté son pesant de cuivre.',26972),
(90064,'frFR','','Je suis prête à vous vendre une pierre de Jordanie si vous me promettez de ne jamais refaire ça.',26972),
(90065,'frFR','','La poisse, on a ça dans le sang, dans ma famille.',26972),
(90066,'frFR','','Désolée, $gmessire:madame;.',26972),
(90067,'frFR','','Ne vous débarrassez pas de cette mascotte. On peut la requinquer.',26972),
(90068,'frFR','','Eh oui ! Mes mascottes viennent des mauvais quartiers de Caldeum.',26972),
(90069,'frFR','','Vous n’avez pas eu de chance, $gmessire:madame;.',26972),
(90072,'frFR','Nous fondons de grands espoirs sur ces mascottes. Pour nous, elles sont sacrées.','',26972),
(90073,'frFR','Gloire à Anzu !','',26972),
(90074,'frFR','Nous autres, arakkoa, ne nous laissons pas démonter par une simple défaite.','',26972),
(90075,'frFR','Un mauvais présage.','',26972),
(90076,'frFR','Anzu, protège tes enfants !','',26972),
(90077,'frFR','Non ! Les gardiens doivent être infaillibles !','',26972),
(90078,'frFR','Malédiction ! Maaaaléééédiiictioooon !','',26972),
(90079,'frFR','La malédiction de Sethe est sur nous.','',26972),
(90080,'frFR','Un bon présage.','',26972),
(90081,'frFR','La force des arakkoa est avec nous.','',26972),
(90082,'frFR','Le dieu corbeau nous a accordé sa bénédiction, aujourd’hui.','',26972),
(90083,'frFR','Les gardiens tiennent bon.','',26972),
(90084,'frFR','Anzu veille sur ses enfants.','',26972),
(90087,'frFR','','Attention, $n. Certaines créatures sont dotées d’une force qu’on ne soupçonnerait pas.',26972),
(90088,'frFR','','J’espère vous avoir appris quelque chose, aujourd’hui.',26972),
(90090,'frFR','','Je suis désolée de cette perte, mais vous remportez là une belle victoire.',26972),
(90091,'frFR','','N’ayez crainte, un simple sort de soins et tout rentrera dans l’ordre.',26972),
(90092,'frFR','','La vie réserve bien des surprises.',26972),
(90093,'frFR','','La Lumière ne l’a pas encore rappelée à elle. Elle se repose juste.',26972),
(90094,'frFR','','Les phalènes aiment jouer avec le feu, c’est dans leur nature.',26972),
(90096,'frFR','','Il faut être inconscient pour sous-estimer la force de la nature.',26972),
(90097,'frFR','','Un phalène semble fragile, mais il sait se défendre.',26972),
(90098,'frFR','','Ne désespérez pas. Votre mascotte et vous allez tirer des enseignements de ce combat.',26972),
(90099,'frFR','','Une bonne leçon… apprise un peu tard, malheureusement.',26972),
(90105,'frFR','Les ténèbres… enveloppent tout mon être. Elles parcourent chaque fibre de mon corps.','',26972),
(90106,'frFR','Venez, étrangers. Plongez dans le royaume des Ténèbres ! Je vous guiderai vers le trépas.','',26972),
(90250,'frFR','Ça mord ? En ce qui me concerne, j’ai découvert que la patience (et la bière) étaient les meilleures alliées du pêcheur en quête de grosses prises !','',26972),
(90251,'frFR','Vous avez prévu de quoi boire un coup ? On ne part jamais à la pêche sans avoir pris de quoi se rafraîchir !','',26972),
(90253,'frFR','*HIC !* C’était un dauphin, ça ?! *HIC !* J’adore les dauphins !','',26972),
(90254,'frFR','Sérieusement ? Personnellement, c’est le genre de truc que je préfère remettre à l’eau.','',26972),
(90265,'frFR','À la revoyure !','',26972),
(90266,'frFR','Je repasserai plus tard. Gardez-moi une bière !','',26972),
(90267,'frFR','Bonne chance avec la poiscaille !','',26972),
(90268,'frFR','Salut, $n ! Alors, la chance vous a souri, dans le coin ?','',26972),
(90269,'frFR','$n, vous voilà !','',26972),
(90270,'frFR','Salutations, $n !','',26972),
(90493,'frFR','Les exarques sont chargés de guider les Draeneï. Nous sommes les gardiens des valeurs sur lesquelles repose notre société.','',26972),
(90511,'frFR','','Voilà des années que je ne m’étais pas retrouvée sur le terrain.$B$B<L’impressionnante archimage prend une profonde inspiration.>$B$BRien de tel que l’air frais… et le parfum du danger.',26972),
(90512,'frFR','','Si ça ne tenait qu’à moi, je m’occuperais de cette mission en personne, mais l’archimage Khadgar m’assure que vous saurez faire preuve d’un peu plus de tact.',26972),
(90513,'frFR','','Je garde de vilains souvenirs du premier passage des démons en Azeroth. Je me souviens de l’horreur, du chaos… et du silence qui s’est abattu sur une ville détruite.$B$BJe ferai tout ce qui est en mon pouvoir pour éviter qu’une telle chose ne se reproduise.',26972),
(90514,'frFR','','Je ne comprends pas comment on peut choisir de servir la Légion corps et âme.$B$BCertains ont soif d’un pouvoir qu’ils seraient bien incapables de maîtriser.',26972),
(90515,'frFR','','Le village sargereï est comme une ruche.$B$BSi on dérange ses habitants, nous nous ferons piquer. Si on le détruit par le feu, c’en est fini du bon miel que nous convoitons.$B$BPour récupérer les informations dont nous avons besoin, il va falloir y aller en douceur.',26972),
(90522,'frFR','','Nous n’avons pas vu venir la trahison de l’exarque Othaar. Comment un dirigeant draeneï peut-il tourner le dos à la Lumière et rejoindre le camp de ceux qui ont persécuté son peuple ?',26972),
(90525,'frFR','','Ses nouveaux alliés lui ont donné un nom, une nouvelle identité… « Socrethar ». C’est un adversaire puissant, et je redoute ce qu’il est capable de faire.',26972),
(90528,'frFR','','Vous avez entendu parler de moi, $n ? Je suis Modera, archimage du Conseil des Six qui dirige le Kirin Tor et Dalaran.$B$BJe pourrais raser ce village, si je le voulais.$B$BMais ce n’est pas pour ça que nous sommes ici. Comme je l’ai appris avec l’âge, on n’attrape pas les mouches avec du vinaigre.',26972),
(90779,'frFR','','Ah, $gchampion:championne;… Je savais que vous viendriez. Découvrez l’auteur de votre fin !',26972),
(90780,'frFR','','Vous allez admirer la puissance nouvelle de la Horde de Fer !',26972),
(90809,'frFR','Et si on trouvait qui se cache derrière ces magouilles bizarres ?','',26972),
(90811,'frFR','Juxtaposition temporelle imminente !','',26972),
(90813,'frFR','Wouah ! Ça a marché. Et on n’a même pas été temporellement inversés.','',26972),
(90900,'frFR','Je suis désolé, Cénarius. Je croyais en votre cause, mais je n’ai pu me résoudre à trahir…','',26972),
(90901,'frFR','','Vous m’avez rendu un grand service, Farondis.',26972),
(90902,'frFR','','Hélas, vous ne vivrez pas assez longtemps pour profiter de ma gratitude…',26972),
(90903,'frFR','… Quoi ?!','',26972),
(90904,'frFR','','Cette vallée regorge de comploteurs.',26972),
(90905,'frFR','','Ainsi, vous conspirez avec Cénarius dans mon dos ? Je ne tolérerai aucune dissension !',26972),
(90910,'frFR','','La voici, mon prince : la Pierre-des-Marées de Golganneth, relique sacrée des Kaldorei et l’une des sept pierres de la création.',26972),
(90911,'frFR','Très bien. Laissez-moi.','',26972),
(91842,'frFR','Commandant, Morthis Murmedaile, un druide de la Serre, cherche à vous voir. Vous le trouverez au pied du grand arbre, au sud.','',26972),
