(92164,'frFR','','Il est grand temps qu’on vous donne une leçon à tous.',26972),
(92206,'frFR','Il y a dix mille ans de cela, je me suis retrouvé dans une sorte d’alliance rebelle.','',26972),
(92207,'frFR','C’était au temps où l’influence de la reine Azshara sur les Elfes était à son apogée. Elle abusait de la magie, ce qui la rendait aussi puissante que dangereuse.','',26972),
(92208,'frFR','Nous avions donc l’intention d’utiliser la Pierre-des-Marées de Golganneth contre elle.','',26972),
(92209,'frFR','Cénarius. Je suis en mesure d’utiliser la Pierre-des-Marées, mais je me dois de vous prévenir : nous risquons de détruire la totalité du Puits d’éternité !','',26972),
(92210,'frFR','Mais c’est exactement le plan.','',26972),
(92211,'frFR','Bah ! Nous devons nous débarrasser d’Azshara, pas de la source du pouvoir de notre peuple !','',26972),
(92212,'frFR','Je suis d’accord. Cela revient à utiliser un canon contre des moineaux.','',26972),
(92214,'frFR','','La reine Azshara est de connivence avec les démons. Elle fait courir un grand risque à notre monde tout entier.',26972),
(92215,'frFR','Très bien. Prince Farondis, êtes-vous en mesure de récupérer la Pierre-des-Marées de Golganneth ?','',26972),
(92216,'frFR','C’est comme si c’était fait, Cénarius.','',26972),
(92360,'frFR','Ma reine.','',26972),
(92780,'frFR','Ceci est un bastion fortifié de haute sécurité. Seul un idiot tenterait de s’y rendre sans une armée.$b$bEnfin… bonne chance, $gchampion:championne;.$b$b<Khadgar vous donne une petite tape réconfortante sur l’épaule.>','',26972),
(93026,'frFR','Suivez-moi. C’est justement ce qu’il me faut pour libérer Garona de l’emprise de Gul’dan.','',26972),
(93027,'frFR','Nous retournons les armes de notre ennemi contre lui !','',26972),
(93028,'frFR','Jamais tant que je serai en vie. Je vais mettre fin à vos tourments, Garona.','',26972),
(93029,'frFR','Om na ka om, Fel na om kal...','',26972),
(93030,'frFR','Vite, détruisez cette chose !','',26972),
(93031,'frFR','Réveillez-vous, Garona. Vous êtes enfin libre.','',26972),
(93032,'frFR','Venez avec moi, Garona. Nous devons préparer ensemble la chute de Gul’dan.','',26972),
(93033,'frFR','','Archimage. Ce que vous faites, c’est de la magie noire.',26972),
(93034,'frFR','','Vous utilisez ses armes tout court !',26972),
(93035,'frFR','','Je n’aime pas ça.',26972),
(93036,'frFR','','Donnez-moi cet orbe, Khadgar. Je vais détruire cette chose immonde.',26972),
(93037,'frFR','','Avez-vous déjà abandonné, mage ?',26972),
(93038,'frFR','','La douleur fait suffoquer %s.',26972),
(93039,'frFR','','Gul’dan... Il n’est plus dans ma tête…',26972),
(93040,'frFR','','Je vous dois tout ! À tous les deux !',26972),
(93041,'frFR','','Je ferai ce qu’il faut pour arrêter Gul’dan. Partout où vous irez, je suivrai vos ordres… commandant !',26972),
(93462,'frFR','','Ha ha ha haaa… Vous allez connaître mon courroux.',26972),
(93463,'frFR','Commençons.','Commençons.',26972),
(93464,'frFR','Impossible !','Impossible !',26972),
(93465,'frFR','Je gagne encore une fois.','Je gagne encore une fois.',26972),
(93466,'frFR','Ce n’était pas prévu.','Ce n’était pas prévu.',26972),
(93467,'frFR','Votre mascotte récupère avec le temps.','Votre mascotte récupère avec le temps.',26972),
(93475,'frFR','Voyons comment vous gérez un autre type de menace.','Voyons comment vous gérez un autre type de menace.',26972),
(93645,'frFR','','Nous cherchons Solog Roark !',26972),
(93646,'frFR','','Nous ne voulons pas votre mort. Juste un constructeur de navire.',26972),
(93647,'frFR','Vous l’avez trouvé. Si vous voulez ma mort, donnez-moi un marteau et battons-nous.','',26972),
(93648,'frFR','Hah ! Je suis le meilleur.','',26972),
(93775,'frFR','Oubliez la Pierre-des-Marées, mes frères. Laissons leur précieux cristal aux lézards et à la plèbe.','',26972),
(93776,'frFR','Nous allons nous rabattre sur les dragons !','',26972),
(94046,'frFR','Vous tirez Porte-Cendres du sol et brandissez la lame dans un geste triomphal. Aussitôt, Balnazzar se matérialise devant vous.','',26972),
(94426,'frFR','Paladins d’Azeroth, vous êtes venus rendre hommage à notre défunt généralissime Tirion Fordring. Il fut un modèle pour nombre d’entre vous, et l’incarnation de toutes les valeurs qui sont chères à nos yeux.','',26972),
(94430,'frFR','Nous cherchons Solog Roark !','',26972),
(94431,'frFR','Non, l’ami. Nous avons un ennemi commun et nous avons besoin de vos talents.','',26972),
(94432,'frFR','Dites-m’en un peu plus.','',26972),
(95654,'frFR','Guet du Lion','',26972),
(95655,'frFR','Vol’mar','',26972),
(95744,'frFR','','Bienvenue, commandant ! Khadgar m’a dit que vous aviez accompli de grandes choses…',26972),
(95745,'frFR','','Mettez-vous à genou. C’est un privilège rare d’être béni par un naaru.',26972),
(95746,'frFR','Bénis soient les porteurs de torche, dont la lumière perce les ténèbres.','',26972),
(95747,'frFR','Bénis soient les valeureux, qui se dressent face à l’injustice.','',26972),
(95748,'frFR','De puissantes ténèbres ont pris racines sur Draenor.','',26972),
(95749,'frFR','Les vertueux se rallieront à votre bannière. Vous ne devez pas faiblir.','',26972),
(95750,'frFR','Allez avec la bénédiction de la Lumière. Combattez nos ennemis.','',26972),
(95751,'frFR','Le destin de deux mondes est en jeu…','',26972),
(95752,'frFR','','Avez-vous entendu quelque chose ? Le naaru vous a-t-il parlé ?',26972),
(95753,'frFR','','Commandant, quoi que vous décidiez pour la suite, sachez que vous avez le soutien inconditionnel du peuple draeneï.',26972),
(95754,'frFR','','Nous sommes avec vous !',26972),
(95755,'frFR','Commandant, est-ce bien vous ? Votre aura est devenue très forte.','',26972),
(95756,'frFR','Même les éléments de Draenor tremblent. Vous les entendez ? Écoutez… écoutez…','',26972),
(95757,'frFR','Esprits de la pierre, accordez votre force à notre champion.','',26972),
(95758,'frFR','Esprits de l’air, donnez-lui la rapidité du corps et de l’esprit.','',26972),
(95759,'frFR','Esprits de l’eau, faites-lui don de votre sagesse.','',26972),
(95760,'frFR','Esprits de la flamme, donnez-nous votre fureur, et qu’elle balaye nos ennemis !','',26972),
(95761,'frFR','Debout. Sachez que le cœur primordial de Draenor brûle en vous.','',26972),
(95762,'frFR','Gul’dan est prêt à tout pour rompre le lien qui nous unit aux éléments et nous priver de leur force. Vous devez l’arrêter.','',26972),
(95763,'frFR','Le sort de notre monde est entre vos mains, commandant. Lok’tar ogar.','',26972),
(95974,'frFR','','Oh, non…',26972),
(95980,'frFR','Ce n’est pas possible… Ils sont beaucoup trop nombreux.','',26972),
(96011,'frFR','Tenez bon, soldats de l’Alliance ! Nous ne tomberons pas aujourd’hui ! Repoussez-les jusqu’au portail !','',26972),
(96085,'frFR','','Des chasseurs de démons se sont infiltrés dans mon royaume, commandant. C’est inadmissible.',26972),
(96109,'frFR','','Ne les laissez pas entrer dans le volcan. La clé des mondes de la Légion ne doit pas tomber entre leurs mains, Beliash.',26972),
(96145,'frFR','Mes érédars sont en train d’invoquer d’autres démons pour les prendre à revers, votre altesse.','',26972),
(96500,'frFR','Transporteur','',26972),
(96501,'frFR','Porte-nefs','',26972),
(96502,'frFR','Destroyer','',26972),
(96521,'frFR','Cuirassé','',26972),
(96522,'frFR','Sous-marin','',26972),
(96932,'frFR','Je me chargerai personnellement de leur chef, ma reine.','',26972),
(96947,'frFR','','Je vous conseille de réussir.',26972),
(97024,'frFR','Mes troupes sont à votre service.','',26972),
(97025,'frFR','Nous vous aiderons à établir un avant-poste sur le volcan.','',26972),
(97026,'frFR','Cendrelangues, en avant !','',26972),
(97071,'frFR','Maudite soit Helya ! Maudits soient ses fidèles ! Je n’aurai pas de répit tant qu’elle ne sera pas morte !','',26972),
(97080,'frFR','J’étais un Illidari. On m’a laissé pour mort au Temple noir. Voyez maintenant la puissance de mon nouveau maître !','',26972),
(97629,'frFR','J’ai déjà perdu bien trop de temps ici. Ça suffit !','',26972),
(97630,'frFR','','Il est impossible de raisonner Malfurion depuis que nous avons perdu Cénarius.',26972),
(97631,'frFR','','Dépêchez-vous d’aller à l’Arbre-Monde. Il s’y rend peut-être, prêt à prendre des risques insensés.',26972),
(97632,'frFR','','Pendant ce temps, vous et moi allons suivre sa piste à partir d’ici. Malfurion ne doit pas tomber.',26972),
(97762,'frFR','','Commandant illidari, je vous présente les Glissentailles.',26972),
(97763,'frFR','','Le seigneur Illidan vous souhaite une prompte victoire. ',26972),
(97764,'frFR','','L’avant-poste a été établi, je suppose ?',26972),
(97765,'frFR','','Formidable… Encore un volcan gangrené.',26972),
(97786,'frFR','','Ah, vous voilà. Le seigneur Illidan a décidé de mettre mes shivarra à votre service.',26972),
(97787,'frFR','','Un petit groupe s’est infiltré dans le Temple noir, mais l’armée sha’tari est toujours en difficulté.',26972),
(97788,'frFR','','Nous devons obtenir la clé sargerite au plus vite et retourner soutenir nos défenses.',26972),
(97790,'frFR','','Maintenant, si vous voulez bien m’excuser… Venez, mes chères. Nous partons pour l’avant-poste, sur le volcan.',26972),
(98239,'frFR','Azeroth n’a jamais connu de plus grand guerrier. C’est la raison pour laquelle je vous ai sauvé la vie.','',26972),
(98242,'frFR','J’avais prédit que viendrait sur ces terres quelqu’un qui tuerait d’innombrables ennemis et prouverait sa valeur maintes fois. Quelqu’un qui mènerait mes armées à la victoire face aux ténèbres qui tentent d’engloutir ce monde !','',26972),
(98244,'frFR','Je vous déclare officiellement Valarjar ! À charge pour vous de redorer le blason de ces salles avec le concours de mes val’kyrs !','',26972),
(98695,'frFR','Chevaliers de la Lame d’ébène, rassemblez-vous. Rendons hommage à notre condisciple !','',26972),
(98696,'frFR','Vous avez tous eu vent de ses nombreux combats… et des rudes épreuves surmontées au prix de terribles sacrifices.','',26972),
(98697,'frFR','Ses exploits honorent la Lame d’ébène et attestent de son immense valeur ; nous sommes fiers de lui accorder notre plus haute distinction.','',26972),
(98699,'frFR','Par la volonté du roi-liche et par les pouvoirs qui me sont conférés en tant que généralissime, je vous déclare légataire des lames du prince déchu. Vous rejoignez ainsi le cercle des seigneurs de la mort de la Lame d’ébène, $n.','',26972),
(98700,'frFR','Par la volonté du roi-liche et par les pouvoirs qui me sont conférés en tant que généralissime, je vous déclare légataire de Gueule-du-damné. Vous rejoignez ainsi le cercle des seigneurs de la mort de la Lame d’ébène, $n.','',26972),
(98701,'frFR','Par la volonté du roi-liche et par les pouvoirs qui me sont conférés en tant que généralissime, je vous déclare légataire d’Apocalypse. Vous rejoignez ainsi le cercle des seigneurs de la mort de la Lame d’ébène, $n.','',26972),
(98703,'frFR','Prosternez-vous tous devant lui comme vous l’avez fait autrefois devant moi, et servez-le fidèlement dans sa lutte contre la Légion !','',26972),
(98706,'frFR','S… sauvez le temple ! Vite !','',26972),
(98757,'frFR','','C’est donc lui la clé de la chute d’Azeroth.',26972),
(98777,'frFR','Nous accueillons aujourd’hui notre camarade $n.','',26972),
(98911,'frFR','Assez ! Je vais vous briser moi-même !','',26972),
(98937,'frFR','L’heure de votre consécration a sonné, $n.','',26972),
(99135,'frFR','Vous allez mourir !','',26972),
(99136,'frFR','Votre précieux Cercle terrestre sera dispersé aux quatre vents !','',26972),
(99137,'frFR','Votre monde va succomber !!','',26972),
(99138,'frFR','LA LÉGION SERA…','',26972),
(99229,'frFR','Ils battent en retraite.','',26972),
(99230,'frFR','J’ai le sentiment que cette bataille n’est pas encore terminée.','',26972),
(99231,'frFR','','Varian, il est là ! De l’autre côté du gouffre ! C’est Tirion !',26972),
(99232,'frFR','Que toutes les troupes suivent Jaina !','',26972),
(99352,'frFR','Quoi ?','',26972),
(99353,'frFR','C’est pas des troupes d’invasion, ça. C’est une armée !','',26972),
(99354,'frFR','','Encochez vos flèches… En joue… Tirez !',26972),
(99393,'frFR','Ils battent en retraite.','',26972),
(99394,'frFR','','C’était trop facile. Il y a quelque chose qui ne va pas.',26972),
(99395,'frFR','Là, de l’autre côté du gouffre, Gul’dan ! Il a Tirion !','',26972),
(99396,'frFR','La Horde, tous avec Thrall !','',26972),
(99511,'frFR','','Cordana ! Vous devrez répondre de vos actes devant le Haut conseil.',26972),
(99512,'frFR','Bientôt. Son corps est froid, mais son âme n’a pas encore cessé de lutter. Nous avons fort à faire avant qu’il ne soit prêt.','',26972),
(99517,'frFR','Illidan Hurlorage. Après toutes ces années, je rencontre enfin le Traître.','',26972),
(99588,'frFR','Par le marteau, cette montagne est à moi !','',26972),
(99621,'frFR','Flummox pas besoin de mascottes ! Flummox manger eux MAINTENANT !','',26972),
(99696,'frFR','','Qu’ils y viennent !',26972),
(99698,'frFR','','N’en parlez à personne, d’accord ?',26972),
(99699,'frFR','','Prenez ça !',26972),
(99700,'frFR','','Oh, allez, quoi…',26972),
(99701,'frFR','','C’est une blague ?',26972),
(99702,'frFR','','C’est quoi, votre problème ?',26972),
(99703,'frFR','','Seriez-vous ABS ?',26972),
(99704,'frFR','','Vous pourriez peut-être utiliser vos meilleures mascottes…',26972),
(99705,'frFR','','Tu pourrais faire des efforts.',26972),
(100103,'frFR','Quelle puissance !','',26972),
(100104,'frFR','Retournez à l’école !','',26972),
(100105,'frFR','Ha ! Un petit effort, quoi !','',26972),
(100106,'frFR','Chopez-les !','',26972),
(100107,'frFR','J’ai déjà vu mieux.','',26972),
(100108,'frFR','Il aurait fallu amener une vraie bête !','',26972),
(100109,'frFR','Non ! Comment avez-vous pu ?','',26972),
(100110,'frFR','Utilisez-vous des mascottes de type mécanique ?','',26972),
(100111,'frFR','Tout ça fait partie du plan.','',26972),
(100136,'frFR','Maintenant, voyons comment activer ce portail.','',26972),
(100297,'frFR','Un seul d’entre nous s’en tirera en vie. Euh, attendez…','',26972),
(100298,'frFR','Je vais vous emmener moi-même à Helheim, s’il le faut !','',26972),
(100300,'frFR','Ce qui ne nous tue pas nous rend plus forts !','',26972),
(100302,'frFR','Réessayez si vous l’osez !','',26972),
(100303,'frFR','Mon guide ne m’avait pas parlé de ça !','',26972),
(100304,'frFR','Comment est-ce possible ? Mon plan était parfait !','',26972),
(100305,'frFR','Grrrrr…','',26972),
(100308,'frFR','Vous n’êtes vraiment pas $gdoué:douée;.','',26972),
(100309,'frFR','Ma stratégie est impeccable !','',26972),
(100310,'frFR','Vous n’êtes pas de taille face à mes mascottes !','',26972),
(100341,'frFR','Cyana, Jace, Allari… Trouvez la clé.','',26972),
(100404,'frFR','Quel est ce sortilège ?!','',26972),
(100405,'frFR','Ce marteau… Il me le faut pour mes maîtres…','',26972),
(100450,'frFR','Ils arrivent !','',26972),
(100452,'frFR','Tenez votre position, braves-guerriers !','',26972),
(100633,'frFR','Bien joué. Vos compagnons et vous devez partager un lien puissant.','',26972),
(100634,'frFR','S’il le faut vraiment…','',26972),
(100635,'frFR','Vous aurez peut-être une chance de me battre lorsque vous commencerez à les considérer comme des amis, et non plus comme de simples mascottes.','',26972),
(100636,'frFR','Cela ne me procure aucun plaisir.','',26972),
(100637,'frFR','Vous devriez mieux vous occuper de vos amis.','',26972),
(100638,'frFR','Votre lien n’est pas encore assez puissant.','',26972),
(100639,'frFR','Ça va, mon petit ?','',26972),
(100644,'frFR','Il faut se reposer, maintenant.','',26972),
(100646,'frFR','Quand tout sera fini, nous irons chercher quelques friandises.','',26972),
(100701,'frFR','','Vous êtes vraiment $gun fin:une fine; stratège.',26972),
(100706,'frFR','','Que le plus courageux l’emporte !',26972),
(100707,'frFR','','Ce n’est pas grave, vous pouvez réessayer.',26972),
(100708,'frFR','','Peut-être que ça irait mieux avec une mascotte plus puissante ?',26972),
(100709,'frFR','','Cette dernière mascotte semblait un peu faible.',26972),
(100710,'frFR','','Vous allez devoir faire plus d’efforts si vous voulez l’emporter.',26972),
(100711,'frFR','','Là, ça va devenir sérieux !',26972),
(100712,'frFR','','Ça, ce n’était qu’un échauffement.',26972),
(100713,'frFR','','Vous avez combattu avec vaillance, petit être.',26972),
(100769,'frFR','Quoi ? Vous avez triché, c’est sûr !','',26972),
(100770,'frFR','Ça va être du gâteau !','',26972),
(100771,'frFR','Ha ! Et vous vous dites $gdompteur:dompteuse; de mascottes ?','',26972),
(100772,'frFR','J’atteins toujours ma cible.','',26972),
(100773,'frFR','Boum, bébé !','',26972),
(100774,'frFR','Et voilà, dégommé.','',26972),
(100775,'frFR','Qui m’a vendu cette nullité ?','',26972),
(100776,'frFR','Je croyais qu’il suffisait de payer pour gagner !','',26972),
(100777,'frFR','Un remboursement, c’est possible ?','',26972),
(100819,'frFR','Mon cauchemar ! C’est le tournoi d’Argent junior qui recommence !','',26972),
(100820,'frFR','Retournez donc à l’entraînement ! Vous me ferez cinquante pompes !','',26972),
(100821,'frFR','On dirait que je me suis trouvé $gun nouvel ennemi juré:une nouvelle ennemie jurée;.','',26972),
(100822,'frFR','Je peux y arriver les yeux bandés, si vous préférez.','',26972),
(100823,'frFR','Bel effort.','',26972),
(100824,'frFR','La pointe de la lance est toujours la plus redoutable.','',26972),
(100825,'frFR','Vous pouvez toujours être mon $gécuyer:écuyère;.','',26972),
(100826,'frFR','Prêt, Messire de Bourbetonne ? Battez-vous dans les règles de l’art !','',26972),
(100827,'frFR','Belle performance ! Bravo !','',26972),
(100855,'frFR','Quand on affronte l’océan, l’océan l’emporte toujours.','',26972),
(100856,'frFR','Le soleil vient de se coucher ! Sortez les mascottes !','',26972),
(100857,'frFR','Mes petits gars ont besoin de passer plus de temps hors de l’eau, on dirait.','',26972),
(100858,'frFR','Une tempête approche !','',26972),
(100859,'frFR','Les vagues déferlent, et moi, j’écrase tout !','',26972),
(100860,'frFR','Il va vous falloir plus d’entraînement avant de pouvoir raisonnablement patauger.','',26972),
(100861,'frFR','Toutes les vagues ne sont pas des raz-de-marée.','',26972),
(100862,'frFR','Quelle déferlante !','',26972),
(100863,'frFR','C’est encore plus douloureux quand on frotte du sable sur la plaie, pas vrai ?','',26972),
(100970,'frFR','','Il semblerait que le seigneur des abîmes prépare une invasion.',26972),
(100971,'frFR','Fourbissez vos armes, enfants de mon courroux ! Ce soir, nous frapperons les défenses des mortels en plein cœur !','',26972),
(100973,'frFR','','Oh, non… Le portail !',26972),
(100974,'frFR','…','',26972),
(100976,'frFR','','Ils ont dû le lier à notre portail d’invocation. Ils vont assiéger Dalaran ! Il faut à tout prix refermer le passage !',26972),
(100978,'frFR','','À supposer qu’on puisse l’atteindre…',26972),
(101216,'frFR','Allons bon, qu’est-ce encore que cette agitation ? Pourquoi le portail s’est-il refermé ?','',26972),
(101252,'frFR','Qu’est-ce que c’est ? Les mortels osent déstabiliser mes portails et envahir mes archives ? J’aurais dû tous vous détruire comme j’ai détruit ce misérable petit Gnome.','',26972),
(101856,'frFR','','Jugez-moi si ça vous chante, chère sœur, mais sachez que rien ne nous arrêtera.',26972),
(101857,'frFR','Vous arrivez trop tard, Gardienne. Ce caveau sera votre tombeau.','',26972),
(101859,'frFR','','Vous devez survivre, chasseurs de démons. Trouvez l’archimage dénommé Khadgar. Vous pouvez lui faire confiance.',26972),
(101861,'frFR','','Je surveillerai toujours Illidan !',26972),
(101865,'frFR','','Alors, faites vite. Les Gardiennes arrivent, suivies des Illidari.',26972),
(101866,'frFR','Leur situation doit être vraiment désespérée !
','',26972),
(101941,'frFR','Pendant des générations, les Taurens de cette montagne se sont battus. D’innombrables vies, et même des tribus entières, furent perdues.','',26972),
(101942,'frFR','Un jour, en rentrant d’une de ces batailles, Huln Haut-Roc découvrit que son peuple avait été massacré par un adversaire inconnu.','',26972),
(101943,'frFR','Combattant son chagrin, Huln alla parler aux chefs des tribus restantes. Il les convainquit de s’unir sous la même bannière pour affronter cette nouvelle menace.','',26972),
(101944,'frFR','Je vais vous raconter l’histoire de Huln Haut-Roc.','',26972),
(101945,'frFR','Et maintenant, vous allez assister aux épreuves de Huln…','',26972),
(101986,'frFR','','La bête est là ! An’she nous garde !',26972),
(102020,'frFR','','Allons-y.',26972),
(102027,'frFR','','Elle a disparu dans cet épais nuage de brume. Elle peut être cachée n’importe où ! Auriez-vous un piège assez puissant pour immobiliser cette bête ?',26972),
(102058,'frFR','Vous me barrez la route.','',26972),
(102059,'frFR','Nous sommes fidèles à Haut-Roc.','',26972),
(102061,'frFR','','Elle essaie de nous lacérer depuis la brume ! Faites vite !',26972),
(102062,'frFR','','Ça a marché ! Tuez ce monstre !',26972),
(102116,'frFR','','Pour moi… l’aventure s’achève… ici… À vous… d’en finir.',26972),
(102139,'frFR','Nous sommes légion.','',26972),
(102155,'frFR','Vous ne pouvez vous soustraire à ma vue.','',26972),
(102209,'frFR','Tout le monde doit payer le prix du sang !','',26972),
(102255,'frFR','Enfants des profondeurs, réveillez-vous et écrasez ces shan ronir !','',26972),
(103019,'frFR','Illidan… vous appartenez désormais à la Légion.','',26972),
(103354,'frFR','Avortons insolents !','',26972),
(103355,'frFR','','Manifestement, nous avons été repérés.',26972),
(103356,'frFR','Vous croyiez vraiment pouvoir m’échapper aussi facilement ?','',26972),
(103357,'frFR','','Argh… Lâche-moi, sale démon !',26972),
(103358,'frFR','Quelle arrogance, démonistes ! Vous osez donner des ordres à ceux de mon espèce ! Affrontez les conséquences de votre insolence !','',26972),
(103359,'frFR','','Shinfel, non !',26972),
(103360,'frFR','Je vais vous écraser, misérables cafards que vous êtes !','',26972),
(103361,'frFR','Brûlez ! Brûlez dans le gangrefeu !','',26972),
(103362,'frFR','Personne ne s’échappe ! Ce n’est pas encore fini !','',26972),
(103363,'frFR','Ce crâne fera un magnifique trophée !','',26972),
(103364,'frFR','','Argh ! Dépêchez-vous, démoniste… Refermez le portail !',26972),
(103365,'frFR','Je vais tous vous réduire en cendres !','',26972),
(103366,'frFR','Ce n’est pas fini, démoniste ! J’aurai ta tête !','',26972),
(103422,'frFR','','Zinnin, attention !',26972),
(103431,'frFR','','Zinnin…',26972),
(103432,'frFR','','Éliminez… ce monstre. Trouvez… Griffe-Serre…',26972),
(103440,'frFR','','Oh, non !',26972),
(103495,'frFR','Le rituel va canaliser notre énergie pour ouvrir un portail au centre. Il faut bien le stabiliser !','',26972),
(103496,'frFR','Excellent, le passage prend forme ! Il est de plus en plus stable !','',26972),
(103498,'frFR','Le chemin du Rêve est prêt ! Beau travail, tout le monde.','',26972),
(103810,'frFR','DÉCROISEZ LES FILS POUR SAUVER MA VIE NUMÉRIQUE','DÉCROISEZ LES FILS POUR SAUVER MA VIE NUMÉRIQUE',26972),
(103836,'frFR','Le diacre a entamé le rituel ! Il ne doit être interrompu sous aucun prétexte !','Le diacre a entamé le rituel ! Il ne doit être interrompu sous aucun prétexte !',26972),
(103843,'frFR','Maître Martel-Scories ! Quelqu’un tente de s’introduire !','Maître Martel-Scories ! Quelqu’un tente de s’introduire !',26972),
(103920,'frFR','$n, voilà un cadeau du seigneur Illidan.','',26972),
(104165,'frFR','','Nous ne pourrons rien faire tant que vous n’aurez pas posé le piège ! Faites vite !',26972),
(104166,'frFR','','Retenez ces bêtes en attendant que le piège se déclenche !',26972),
(104367,'frFR','Oui… La lame a raison ! Rien ne peut m’arrêter ! Une fois que nous aurons ressuscité Zakajz, le monde sera à moi !','',26972),
(104368,'frFR','Nos anciens chefs préféraient œuvrer au travers de pions, mais je choisis le VRAI pouvoir !','',26972),
(104430,'frFR','Défendez-moi ! Vous m’aviez assuré que ça marcherait !','',26972),
(104508,'frFR','Je… Je ne comprends pas ! Pourquoi vous ne me protégez pas ?','',26972),
(104510,'frFR','Laissez-moi une autre chance ! Non ! Nooooooooooooon !','',26972),
(104575,'frFR','Vous croyez pouvoir m’arrêter ? Avec cette arme, je suis capable de tout ! DE TOUT !','',26972),
(104902,'frFR','Contemplez Saraka, le destructeur de mondes ! Enfin dompté après plusieurs millénaires de destruction aveugle.','',26972),
(104904,'frFR','Les Draeneï tentent de concevoir un rituel pour ramener les naarus dans la Lumière. J’ai fait appel à d’autres prêtres pour les y aider.','',26972),
(104905,'frFR','La victoire est proche. Je pense que votre arme peut faire pencher la balance en notre faveur. Si vous voulez bien entrer dans le cercle, nous pourrons lancer le rituel.','',26972),
(104906,'frFR','Oui ! Utilisez la lame pour attirer l’énergie du Vide !','',26972),
(104908,'frFR','Oui ! Gorgez-le de lumière réparatrice !','',26972),
(104909,'frFR','Oui ! Purgez-le par les flammes sacrées !','',26972),
(104990,'frFR','Oui ! Ça fonctionne ! Le sentez-vous ?','',26972),
(104991,'frFR','La faim, la rage, elles ont disparu. La Lumière m’ouvre à nouveau les bras.','',26972),
(105015,'frFR','L’arme prodigieuse appelle à propager la Lumière. Nous répondrons quand vous serez en détresse.','',26972),
(105019,'frFR','Une fois encore, vous avez prouvé toute votre valeur. Avec l’aide de Saa’ra et la puissance de votre arme prodigieuse, nul ne peut rivaliser !','',26972),
(105022,'frFR','De nombreux clergés d’Azeroth ont accepté de faire don de temps et de ressources au nouveau Conclave. Nous sommes unis par un objectif, la défaite de la Légion ardente !','',26972),
(105023,'frFR','Je déclare le Conclave ouvert ! Ensemble, nous apporterons espoir et réconfort à nos alliés, et nous châtierons nos ennemis !','',26972),
(105025,'frFR','À présent, transformons cette prison en un temple qui nous servira de quartier général. Cela ne devrait pas être long.','',26972),
(105144,'frFR','L’autel est terminé, Betild.','',26972),
(105388,'frFR','Vous ne pouvez même pas faire confiance à votre propre esprit !','',26972),
(105390,'frFR','Voyez comme je vous asservis à ma volonté !','',26972),
(105391,'frFR','Les ténèbres dévoreront tout !','',26972),
(105393,'frFR','Bah !','',26972),
(105394,'frFR','M’entendez-vous ?','',26972),
(105395,'frFR','Par ici !','',26972),
(105397,'frFR','','Aaaah !',26972),
(105399,'frFR','Regardez ! La Pierre-des-Marées !','',26972),
(105401,'frFR','Bon sang…','',26972),
(105422,'frFR','Suivez-moi. Nous devons parler aux autres.','',26972),
(105423,'frFR','Contemplez la puissance des lames jumelles du Trompeur. Le Marteau gangrené est à nous !','',26972),
(105424,'frFR','Nous sommes les lames qui feront tomber la Légion. Nous sommes les guerriers choisis par le seigneur Illidan.','',26972),
(105425,'frFR','Nous sommes les ILLIDARI !','',26972),
(105456,'frFR','Par ici. Vos troupes vous attendent.','',26972),
(105458,'frFR','Enfin, le Marteau gangrené est à nous. Admirez la puissance des lames jumelles du Trompeur !','',26972),
(105459,'frFR','Nous suivrons notre chef au combat, et nous ferons tomber la Légion une bonne fois pour toutes !','',26972),
(105460,'frFR','Gloire aux Illidari !','',26972),
(105479,'frFR','Gnnnn…','',26972),
(105480,'frFR','Malfurion, mon vieil ami… Voilà l’appât idéal !','',26972),
(105482,'frFR','Ah, la matriarche des rêves est enfin là.','',26972),
(105687,'frFR','','Moines du temple Brisé !',26972),
(105688,'frFR','','$n, notre chef, nous a permis aujourd’hui d’acquérir une force nouvelle.',26972),
(105689,'frFR','','Grâce au légendaire breuvage des tempêtes, nous allons pouvoir redoubler d’efforts dans la guerre qui nous oppose à la Légion.',26972),
(105690,'frFR','','Combattons en souvenir de nos morts et ramenons la paix en ce monde !',26972),
(105691,'frFR','','Merci encore, $n.',26972),
(105750,'frFR','Que faites-vous là ? Fuyez, le démon approche !','',26972),
(106039,'frFR','Préparez-vous et entrez dans le cercle dès que vous vous sentirez d’attaque.','',26972),
(106077,'frFR','C’est là qu’a eu lieu mon ultime combat… et que gît l’ennemi. Zakajz lutte déjà pour se réveiller. Vous devez faire vite !','',26972),
(106083,'frFR','Salutations à vous deux. Les secousses en provenance du Rêve d’émeraude deviennent plus puissantes. Commençons le rituel sans attendre !','',26972),
(106117,'frFR','','Les plus grands chamans au monde se rassemblent là en bas. Enfin, ceux qu’il nous reste.',26972),
(106221,'frFR','En route. Hruthnir vous attend à la plateforme Céleste pour vous prêter assistance.','',26972),
(106276,'frFR','Les Cendrelangues se battront à vos côtés.','',26972),
(106277,'frFR','','Vous pouvez aussi compter sur les Glissentailles.',26972),
(106278,'frFR','','Notre mission n’est pas encore terminée. Nous sommes à vos ordres.',26972),
(106425,'frFR','','Garde ton calme, Wuho !',26972),
(106715,'frFR','Vos efforts ont été remarqués, $n. Vous avez maintes fois prouvé votre valeur exceptionnelle.','',26972),
(106716,'frFR','La force, la férocité et la noblesse dont vous avez fait preuve sont sans égales. Il est temps que vous receviez les honneurs qui vous sont dus.','',26972),
(106717,'frFR','$n, c’est un honneur de vous accueillir au plus haut rang du Cercle cénarien ! Puissent les créatures sauvages célébrer votre ascension !','',26972),
(106974,'frFR','Vous croyez pouvoir battre mes escargots ?','',26972),
(106976,'frFR','Je n’aurai pas tout perdu. Ces escargots morts feront une délicieuse fricassée.','',26972),
(106977,'frFR','Vous venez de vous faire limaçonner !','',26972),
(106978,'frFR','Ah ! Le dîner est servi !','',26972),
(106979,'frFR','Je vais le garder pour plus tard.','',26972),
(106980,'frFR','On dirait qu’il est cuit.','',26972),
(106981,'frFR','Vous avez un peu de bave sur le visage.','',26972),
(106982,'frFR','Trop lent !','',26972),
(106984,'frFR','Si vous en avez terminé avec celui-ci, il fera un excellent ragoût !','',26972),
(107164,'frFR','Tremblez devant moi ! Je vais plonger ce monde dans les ténèbres !','',26972),
(107419,'frFR','Je suis libre. Libre ! LIBRE ENFIN ! Adieu, maudite prison !','',26972),
(107428,'frFR','','Pitoyables créatures. En reste-t-il d’autres ?',26972),
(107429,'frFR','Oui, ma dame. Les Mörgestran les garderont sous clé jusqu’à ce que vous veniez collecter leurs âmes.','',26972),
(107430,'frFR','','Bien. Réduisez le monastère en poussière !',26972),
(107453,'frFR','Votre ordre est brisé, moines ! Vous ne pouvez rien contre nous.','',26972),
(107454,'frFR','Notre volonté, elle, n’est pas brisée. Nous combattrons jusqu’à notre dernier souffle.','',26972),
(107455,'frFR','La Légion est éternelle…','',26972),
(107456,'frFR','Vous allez périr par ma lame, $c !','',26972),
(107461,'frFR','Ouiiiiii… et feu !','',26972),
(107466,'frFR','','Vite, $n. Les épandeurs de corruption causent des dégâts incroyables.',26972),
(107467,'frFR','Nous allons les retenir ici. Frappez les démons sur-le-champ, ou il sera trop tard !','',26972),
(107468,'frFR','Allez j’suis derrière, cavale ! Le roi est d’enfer si ça s’tasse mal !','',26972),
(107472,'frFR','Vous avez vu de vos yeux le pouvoir destructeur de la Légion.','',26972),
(107478,'frFR','Je suis votre pire cauchemar.','',26972),
(107479,'frFR','Pathétique.','',26972),
(107485,'frFR','La graine est semée.','',26972),
(107486,'frFR','Oui, laissez la colère vous envahir !','',26972),
(107487,'frFR','Je sens la corruption qui se propage !','',26972),
(107488,'frFR','Cette bestiole n’aurait pas tenu longtemps de toute façon.','',26972),
(107490,'frFR','Votre insolence va vous coûter cher.','',26972),
(107491,'frFR','Je fais un mauvais rêve.','',26972),
(107509,'frFR','Tyrande Murmevent ! J’attends cette rencontre depuis des années.','',26972),
(107512,'frFR','Votre très cher époux me rejoindra bientôt dans le Cauchemar. Il a reçu une invitation toute particulière.','',26972),
(107517,'frFR','Venez. Les autres survivants sont par là.','',26972),
(107606,'frFR','Et cette chère Ysera ! Vous me croiriez si je vous disais qu’elle a changé d’allégeance ?','',26972),
(107619,'frFR','Elle va m’aider à conquérir Val’sharah, à commencer par votre précieux temple d’Élune.','',26972),
(107813,'frFR','Quel cruel dilemme, grande prêtresse !','',26972),
(107814,'frFR','Accourir au chevet de votre bien-aimé, ou voir brûler le temple de votre déesse ?','',26972),
(107815,'frFR','<Rire dément>','',26972),
(107827,'frFR','','<Rugissement draconique d’Ysera>',26972),
(107833,'frFR','Enfin, le Marteau gangrené est à nous. Admirez la puissance des lames de guerre des Aldrachi !','',26972),
(107834,'frFR','Contemplez la puissance des lames de guerre des Aldrachi. Le Marteau gangrené est à nous !','',26972),
(108003,'frFR','Commençons votre leçon d’humilité sans plus attendre.','',26972),
(108004,'frFR','Leçon terminée.','',26972),
(108005,'frFR','Hors de ma vue ! J’ai besoin de temps pour digérer cet affront.','',26972),
(108006,'frFR','Quel manque de discipline !','',26972),
(108007,'frFR','Vous allez apprendre le respect ou je me chargerai de votre éducation.','',26972),
(108008,'frFR','Cette pauvre tache n’est pas digne de nettoyer mes latrines, et encore moins de se battre !','',26972),
(108009,'frFR','Intéressant. Continuez.','',26972),
(108010,'frFR','Une malencontreuse erreur de calcul.','',26972),
(108011,'frFR','Vous ne faites pas la différence entre victoire et sacrifice.','',26972),
(108057,'frFR','','Voilà ! Les griffes sont à nous !',26972),
(108137,'frFR','Musquards ! Conférez-moi votre robustesse !','',26972),
(108138,'frFR','Ha ! Les musquards sont encore les plus forts !','',26972),
(108139,'frFR','Je suis déshonoré.','',26972),
(108140,'frFR','Rien ne peut survivre à pareils sabots !','',26972),
(108141,'frFR','Encore ! Amenez d’autres d’adversaires à piétiner !','',26972),
(108142,'frFR','À moi la gloire !','',26972),
(108145,'frFR','Bjorn ! Confère-moi ta sauvagerie !','',26972),
(108146,'frFR','Ha ! Les ours sont encore les plus forts !','',26972),
(108148,'frFR','Une nouvelle victime taillée en pièces !','',26972),
(108149,'frFR','Encore ! Amenez encore de la chair à lacérer !','',26972),
(108206,'frFR','Préparez vos défenses, $gmortel:mortelle;.','',26972),
(108207,'frFR','Rejoignez-moi dans les profondeurs.','',26972),
(108208,'frFR','Je me noie. Je me noie !','',26972),
(108209,'frFR','Une âme de plus nous rejoindra sous peu.','',26972),
(108210,'frFR','Restez immobile et laissez-vous entraîner par le fond.','',26972),
(108211,'frFR','Les faibles n’ont jamais à attendre la mort bien longtemps.','',26972),
(108212,'frFR','Une autre vient prendre sa place.','',26972),
(108213,'frFR','Vous commencez à m’irriter, $gmortel:mortelle;.','',26972),
(108214,'frFR','Vous allez connaître une mort lente dont je vais me délecter.','',26972),
(108282,'frFR','','Voyons si ceux que vous avez amenés sont à la hauteur.',26972),
(108283,'frFR','','Il ne faut en aucun cas sous-estimer ces épreuves.',26972),
(108284,'frFR','','Le terrain de chasse est prêt.',26972),
(108285,'frFR','','Il ne faut point craindre la mort.',26972),
(108287,'frFR','','La vie est éphémère.',26972),
(108288,'frFR','','Seule la grandeur perdure.',26972),
(108289,'frFR','','Vous n’en avez pas encore fini.',26972),
(108308,'frFR','Vous pouvez entrer, mais épargnez-moi vos supplications. Je sais que le Cercle terrestre souhaite unir les éléments.','',26972),
(108309,'frFR','La Légion ardente nous menace tous, mais la puissance des terres de Feu se mérite.','',26972),
(108311,'frFR','Approchez-vous de mon trône et nous verrons jusqu’où vous êtes capable d’aller pour sauver ce monde !','',26972),
(108469,'frFR','Je dois retourner à mes fourneaux !','',26972),
(108470,'frFR','Enfin ! Allons, j’ai encore du pain sur la planche.','',26972),
(108471,'frFR','Je ne peux pas travailler dans ces conditions !','',26972),
(108472,'frFR','Si vous n’arrivez pas à supporter la chaleur…','',26972),
(108473,'frFR','Sortez de ma cuisine !','',26972),
(108475,'frFR','J’ai ici des ingrédients dont vous me direz des nouvelles !','',26972),
(108476,'frFR','Les gens se prennent tous pour des critiques gastronomiques, de nos jours.','',26972),
(108477,'frFR','Ça sent drôlement mauvais.','',26972),
(108478,'frFR','Il faut que je revoie la recette.','',26972),
(108648,'frFR','Nous avons mis la main sur vous et vous, vous avez trouvé la tombe.','',26972),
(108649,'frFR','Quelle est la prochaine étape ?','',26972),
(108650,'frFR','Je vais entamer le rituel. Toi, concentre-toi sur l’esprit, pendant que notre camarade assure notre protection.','',26972),
(108651,'frFR','Au boulot !','',26972),
(108652,'frFR','Je suis mort afin d’atténuer la douleur de mon échec. Pourquoi venez-vous troubler mon sommeil ?','',26972),
(108653,'frFR','J’ai lu vot’ saga. Où avez-vous trouvé l’bouclier ?','',26972),
(108654,'frFR','On dirait que je suis forcé de vous répondre… Mon voyage m’a conduit jusqu’en Tornheim, sur la tombe de rois guerriers.','',26972),
(108655,'frFR','Nous achèverons c’que vous avez commencé.','',26972),
(108656,'frFR','Retrouvez le repos, Vous n’avez plus à avoir honte.','',26972),
(108659,'frFR','Merci pour ton aide, Tahu. Je l’oublierai pas !','',26972),
(108660,'frFR','Ravi d’avoir pu me rendre utile. Je dois retourner au temple Halo-du-Néant afin d’informer le Conclave de notre réussite. Bonne chance.','',26972),
(108661,'frFR','Quant à vous, retournez à Dalaran sans perdre un instant. Je vous retrouverai sur place.','',26972),
(108690,'frFR','Vous voulez connaître la date exacte de votre mort ?','',26972),
(108691,'frFR','Exactement comme je l’avais prédit.','',26972),
(108692,'frFR','Ma vue baisse.','',26972),
(108693,'frFR','Il faut savoir faire des sacrifices.','',26972),
(108694,'frFR','Tout sera réduit en cendres.','',26972),
(108695,'frFR','Je sais déjà ce que vous allez faire.','',26972),
(108696,'frFR','Le destin finit toujours par nous rattraper.','',26972),
(108697,'frFR','Votre destin vous trahit, $gmortel:mortelle;.','',26972),
(108703,'frFR','','Bienvenue, seigneur des flammes ! Bienvenue, Kil’jaeden !',26972),
(108704,'frFR','Je suis satisfait de toi, Akaari. Tu mérites ma bénédiction.','',26972),
(108705,'frFR','Azhir manari kirel. Akim manari galar !','',26972),
(108706,'frFR','','Le pouvoir des crocs… dépasse l’entendement ! Je suis votre humble servante, seigneur !',26972),
(108707,'frFR','L’heure de ta véritable épreuve est venue. Utilise les crocs pour ébranler les royaumes d’Azeroth de l’intérieur. Chaque cadavre est un pas vers la victoire !','',26972),
(108716,'frFR','','Le sang coulera en votre nom !',26972),
(109079,'frFR','Je vous souhaite la bienvenue. Personne n’avait jamais ouvert ces portes.','',26972),
(109080,'frFR','Je suis Yrgrim, le champion de Tyr ! Voyons si vous êtes digne de porter son bouclier.','',26972),
(109092,'frFR','J’attends depuis longtemps quelqu’un qui se montrerait digne. Affrontez-moi et prouvez votre vaillance !','',26972),
(109094,'frFR','Je dois m’assurer que vous avez la volonté, la force et l’endurance nécessaires pour porter ce bouclier. Acceptez-vous pour cela de vous mesurer à moi les armes à la main ?','',26972),
(109095,'frFR','J’accepte votre épreuve, Yrgrim.','J’accepte votre épreuve, Yrgrim.',26972),
(109100,'frFR','Alors, commençons !','',26972),
(109102,'frFR','Je reconnais ma défaite ! Vous êtes digne du bouclier. Si Tyr était vivant, c’est vous qu’il choisirait pour champion. Je vous transmets donc Garde-Vérité. Utilisez-le pour défendre Azeroth contre ses ennemis.','',26972),
(109385,'frFR','','Par le prophète, qu’est-ce que c’est ?!',26972),
(109386,'frFR','Que font de sales mortels près du portail du maître ? Vos âmes vont me livrer la vérité !','',26972),
(109651,'frFR','','En formation !',26972),
(109653,'frFR','','Encore !',26972),
(109654,'frFR','','Beau travail. N’oubliez pas de vous entraîner tous les jours.',26972),
(109655,'frFR','','Vous devez riposter !',26972),
(109656,'frFR','','Continuez comme ça.',26972),
(109657,'frFR','','Apprenez à maîtriser les bases.',26972),
(109658,'frFR','','Bien joué.',26972),
(109659,'frFR','','Et maintenant, la contre-attaque !',26972),
(109663,'frFR','','Poussez votre avantage.',26972),
(110387,'frFR','Nous avons le marteau ! Battez en retraite ! La tombe va s’effondrer !','',26972),
(110388,'frFR','Vous croyez pouvoir fuir… Je vous retrouverai…','',26972),
(110975,'frFR','Mes excuses pour cette sortie agitée ! Retirer le marteau a déclenché l’effondrement de la caverne.','',26972),
(111093,'frFR','Ses exploits honorent la Lame d’ébène. En vérité, elle a prouvé son immense valeur et a su se montrer digne de notre plus haute distinction.','',26972),
(111097,'frFR','Prosternez-vous tous devant elle comme vous l’avez fait autrefois devant moi, et servez-la fidèlement dans sa lutte contre la Légion !','',26972),
(111788,'frFR','Nous avons porté un coup terrible aux ennemis invisibles du Cauchemar.','',26972),
(111790,'frFR','Cependant, Xavius, le seigneur du Cauchemar, vit toujours. Azeroth ne sera vraiment hors de danger que quand il sera mort.','',26972),
(111792,'frFR','Pour mener cette tâche à bien, je vous accorde ma bénédiction. Que mon pouvoir vous aide à servir et protéger la nature.','',26972),
(111793,'frFR','Merci à vous, druides de la Sylverêve. Puisse la sagesse de votre guide vous mener au succès.','',26972),
(111794,'frFR','Adieu.','',26972),
(111860,'frFR','','Tu montres les dents, mais je sais bien que tu ne mords pas.',26972),
(111861,'frFR','','Hé hé hé…',26972),
(111862,'frFR','','Je vais vous faire des petits pansements pour vos petits bobos !',26972),
(111863,'frFR','','Marine ?',26972),
(111864,'frFR','','Ah, les corgis.',26972),
(111865,'frFR','','Ouaf !',26972),
(111866,'frFR','','Mais il était si mignon !',26972),
(111867,'frFR','','Vous êtes un monstre !',26972),
(111868,'frFR','','Ooooh…',26972),
(112308,'frFR','Par la lumière d’Élune ! Qu’est-il arrivé au sanctuaire ?!','',26972),
(112319,'frFR','Très bien ! Nous allons pouvoir riposter.','',26972),
(112427,'frFR','Vos pitoyables barrières ne peuvent rien contre la Légion !','',26972),
(112428,'frFR','Les lames sont à moi !','',26972),
(112430,'frFR','Je ne vous laisserai jamais les crocs d’Ashamane !','',26972),
(112431,'frFR','Quelle insolence ! Nous vous traquerons. Vous ne faites que retarder l’inévitable.','',26972),
(112460,'frFR','RAAAAAARRRHHH !','',26972),
(112472,'frFR','Contemplez les crocs pour la dernière fois, brute !','',26972),
(112473,'frFR','Verstok était là, au sanctuaire ! Allez voir ce qui se passe, là-haut. Je vous rejoins dès que possible, $n.','',26972),
(112508,'frFR','Bravo ! L’assaut de la Légion est repoussé !','',26972),
(112509,'frFR','Mais que… Les crocs ont disparu ! Qu’est-il arrivé, $n ?','',26972),
(112823,'frFR','$n, je vous attendais, mais je ne peux pas en dire autant du traître Altruis.','',26972),
(112826,'frFR','Illidan.','',26972),
(112827,'frFR','Mais qu’importe. Le temps nous est compté.','',26972),
(112828,'frFR','J’ai confié à ce fourbe d’Akama la tâche de planifier la campagne contre la Légion.','',26972),
(112830,'frFR','Lui seul est au fait de tous les détails. Vous aurez besoin de ses conseils si vous espérez réussir.','',26972),
(112831,'frFR','Vous devrez aussi récupérer la clé sargerite pour pouvoir envahir les mondes de la Légion.','',26972),
(112832,'frFR','Trouvez l’endroit où les Gardiennes l’ont cachée.','',26972),
(112833,'frFR','Nous avons attiré l’attention. Je dois me retirer.','',26972),
(112834,'frFR','Me contacter de la sorte ne vous sera plus possible. Les Illidari sont désormais à vous, $n.','',26972),
(112837,'frFR','$n, je vous attendais. Ah, bien… Kayn Solfurie.','',26972),
(112838,'frFR','Monseigneur.','',26972),
(112839,'frFR','Nous avons peu de temps. Écoutez attentivement.','',26972),
(113030,'frFR','Vous m’entendez, $n ? Vous ne devriez plus être loin de Verstok, à présent.','',26972),
(113033,'frFR','Mon balourd de disciple était si pressé de fuir le sanctuaire que je suis sûr qu’il a mal couvert son odeur. En forme de félin, vous devriez la détecter.','',26972),
(113043,'frFR','Prudence ! Ces ruines sont infestées de flétris, de pitoyables créatures rongées par un appétit insatiable pour les arcanes. La puissance des crocs les a peut-être attirés sur la piste de Verstok.','',26972),
(113049,'frFR','Quoi que vous ayez fait, les Flétris n’ont guère apprécié. Cela pourrait tourner à votre avantage. Voyez si vous trouvez un autre interrupteur.','',26972),
(113093,'frFR','Verstok serait-il devenu fou ? Le pouvoir des crocs aiguise les sens de leur porteur, mais en l’occurrence, je crains qu’ils n’aient aussi aggravé sa paranoïa.','',26972),
(113104,'frFR','Vous devez arracher les crocs à Verstok, $n. Plus il les gardera longtemps, plus il s’enfoncera dans ses chimères.','',26972),
(113146,'frFR','C’est fermé ? Cherchez quelque chose qui puisse ouvrir les portes dans la cour, mais attention aux flétris.','',26972),
(113179,'frFR','Qu’est-ce que c’était ? Faites attention, $n !','',26972),
(113345,'frFR','Restez donc pour le dîner !','',26972),
(113346,'frFR','Qu’est-ce que c’est ? Encore une intrusion !','',26972),
(113372,'frFR','Pour ton insolence, ta mort sera douloureuse et lente !','',26972),
(113373,'frFR','Tout ceci ne sert à rien ! Ta fin est proche !','',26972),
(113576,'frFR','Vous serez la première à voir la Légion entrer dans ma ville, imbécile d’Orque !','',26972),
(113577,'frFR','J’attends ce jour depuis longtemps. Ne perdons pas une seconde de plus !','',26972),
(113578,'frFR','Ered’nash ila mornu nakuun. Ered’nash ban man’ari !','',26972),
(113644,'frFR','Ils arrivent !','',26972),
(113718,'frFR','Frappé par la disgrâce, je suis rentré, décidé à laver mon échec dans le sang.','',26972),
(113719,'frFR','','Contemplez Suramar, notre refuge.',26972),
(113720,'frFR','J’ai trouvé le sanctuaire du champion de Tyr, mais je n’ai pu y entrer. J’ai essayé et réessayé jusqu’à ce que la douleur soit trop forte.','',26972),
(113738,'frFR','Beau début ! Vous savez vous battre !','',26972),
(113754,'frFR','','Notre prison.',26972),
(113755,'frFR','','Élisande et la Légion veulent nous soumettre par la peur et la faim.',26972),
(114125,'frFR','','La flamme des Shal’dorei vacille. Nous devons la raviver.',26972),
(114334,'frFR','','Nous devons toucher le noble cœur de mon peuple.',26972),
(114335,'frFR','','VOUS devez lui montrer qu’Azeroth ne l’a pas abandonné.',26972),
(114590,'frFR','Ô Lumière, écoute nos prières, car les ténèbres nous assiègent.','',26972),
(114591,'frFR','Accorde-nous audience, que Porte-Cendres puisse sauver notre monde.','',26972),
(114592,'frFR','Savez-vous où elle est, Uther ? Nous risquons gros si nous retournons là-bas.','',26972),
(114610,'frFR','Maxwell, mon vieil ami ! Cela faisait si longtemps.','',26972),
(114612,'frFR','Vous œuvrez tous deux pour la Lumière. Mais si vous voulez récupérer Porte-Cendres, mieux vaut vous hâter.','',26972),
(114613,'frFR','Je sens l’appel de Porte-Cendres, venant d’une île proche du tombeau maléfique. Mais la lame n’est pas seule…','',26972),
(114614,'frFR','Tirion est vivant, mais sa lueur faiblit. Faites vite, ou il va mourir ! C’est tout ce que je sais.','',26972),
(114615,'frFR','Uther ! Non ! J’avais encore tellement de questions !','',26972),
(114616,'frFR','Bonne chance, mes amis. Que la Lumière vous guide.','',26972),
(114617,'frFR','Uther, c’est bien vous ?','',26972),
(114829,'frFR','Nous prenons place au-dessus de Niskara.','',26972),
(114830,'frFR','Nous prenons place au-dessus de Niskara.','',26972),
(114831,'frFR','À toutes les pièces du haut, feu à volonté !','',26972),
(114832,'frFR','À toutes les pièces du haut, feu à volonté !','',26972),
(115262,'frFR','Silence !','',26972),
(115263,'frFR','','Je n’ai fait que ce qui me semblait…',26972),
(115264,'frFR','J’en ai assez entendu. Le verdict est la peine de mort. Qu’on l’exécute.','',26972),
(115286,'frFR','Saisissez-vous d’elle !','',26972),
(115724,'frFR','Tylos, renvoyez-nous à Mardum.','',26972),
(115725,'frFR','Tylos, renvoyez-nous à Mardum.','',26972),
(115780,'frFR','Marteau-du-Destin peut être n’importe où. Il faut nous séparer.','',26972),
(115781,'frFR','Je vais consulter les chamans du temple de la Terre.','',26972),
(117161,'frFR','Nous serons bientôt exfiltrés. Il faut avertir l’Alliance et la Horde.','',26972),
(117163,'frFR','Leurs flottes doivent faire demi-tour. Le rivage Brisé est un traquenard.','',26972),
(117167,'frFR','Vous avez quelque chose, lieutenant ?','',26972),
(117170,'frFR','','L’île grouille de démons. Ils sont bien plus nombreux que nous le p…',26972),
(117177,'frFR','Vous avez donc découvert notre petit secret.','',26972),
(117189,'frFR','Regardez. Vos chères flottes vont tomber dans notre piège.','',26972),
(117190,'frFR','Tu ne t’en tireras pas comme ça, Detheroc !','',26972),
(117191,'frFR','Bien sûr que si. Et vous allez même m’aider.','',26972),
(117192,'frFR','Je suis le chef du SI:7 !','',26972),
(117228,'frFR','','Nous étions sur le rivage Brisé quelques heures avant l’arrivée des flottes de l’Alliance et de la Horde.',26972),
(117716,'frFR','','Mathias Shaw menait notre équipe d’agents du SI:7 dans une opération de reconnaissance secrète sur l’île. Nous attendions notre évacuation.',26972),
(118586,'frFR','Une offrande digne d’une reine. Je vous remercie…','',26972),
(118587,'frFR','Le pouvoir de l’arcan’dor m’appartient !','',26972),
(118758,'frFR','Aaah, voici qu’arrivent les défenseurs de la Lumière. Nous n’attendions plus qu’eux.','',26972),
(118759,'frFR','Tu n’iras pas plus loin, Balnazzar. Je vais rendre justice à mes frères assassinés !','',26972),
(118760,'frFR','La justice… ou la vengeance, paladin ? Fais le bon choix, car la haine est un chemin sans retour.','',26972),
(118761,'frFR','Péris par ma lame !','',26972),
(118762,'frFR','Arh ! AAAarrrgh !','',26972),
(118763,'frFR','Pathétique. Jarvox, charge-toi de son exécution. Et serait-ce trop demander de la rendre lente et douloureuse ?','',26972),
(119096,'frFR','Je vois une ombre épaisse planant sur le temple Halo-du-Néant. Celle de la Légion ardente, prête à bondir.','',26972),
(119097,'frFR','Notre ordre périra sous ses coups. Personne n’y survivra.','',26972),
(119098,'frFR','Tel sera notre destin. Nous sommes condamnés à mourir sous les coups du démon Balnazzar.','',26972),
(119099,'frFR','Tel sera notre destin. À moins que…','',26972),
(119100,'frFR','Nooooooooon !','',26972),
(119101,'frFR','Je vois un chemin vers la victoire ! Vous êtes là, dans la Lumière. Vous nous guidez.','',26972),
(119103,'frFR','Tout devient clair.','',26972),
(119104,'frFR','Un vieil ennemi devient un allié.','',26972),
(119105,'frFR','Des ombres oubliées surgissent !','',26972),
(119106,'frFR','Tous s’unissent dans la Lumière.','',26972),
(119608,'frFR','Des démons dans la salle du trône ! Protégez le roi !','',26972),
(119609,'frFR','Détruisez leurs portails ! Repoussez la Légion !','',26972),
(120160,'frFR','L’ennemi est parmi nous !','',26972),
(120161,'frFR','Tu nous as découverts trop tard, Illidari ! GANGRELAMES, À L’ATTAQUE !','Tu nous as découverts trop tard, Illidari ! GANGRELAMES, À L’ATTAQUE !',26972),
(120162,'frFR','Des portails ! Les voilà !','',26972),
(120184,'frFR','Tu croyais que ta véritable nature pourrait m’échapper, démon ?','',26972),
(120499,'frFR','Cette fois, Dagg, il a trouvé un gros trésor !','',26972),
(120671,'frFR','Par ordre de la grande magistrice, je vous accuse de rébellion contre l’ordre établi. Vous sapez mon autorité et devez répondre de ce crime.','',26972),
(121034,'frFR','Akama. Ta duplicité n’est pas très étonnante.','',26972),
(121037,'frFR','J’aurais dû vous massacrer depuis longtemps, toi et tes frères déformés.','',26972),
(121194,'frFR','Nous sommes venus mettre fin à ton règne, Illidan. Mon peuple, et l’Outreterre tout entière, seront libres !','',26972),
(121491,'frFR','Citoyens d’Azeroth.','',26972),
(121492,'frFR','Aujourd’hui, est un grand jour pour nous.','',26972),
(121493,'frFR','Qui nous verra reconquérir notre monde.','',26972),
(121494,'frFR','Et renvoyer la Légion dans les enfers qui l’ont engendrée.','',26972),
(121495,'frFR','La voie est libre.','',26972),
(121496,'frFR','Les piliers de la Création nous attendent.','',26972),
(121497,'frFR','Sur les îles Brisées !','',26972),
(121536,'frFR','Bien parlé. Mais je ne suis pas… convaincu.','',26972),
(121542,'frFR','Faites rentrer les vignobles dans le rang. Je ne tolérerai plus aucune insubordination.','',26972),
(121689,'frFR','Archimonde, tu n’iras pas plus loin ! L’âme même d’Azeroth se dresse contre toi !','',26972),
(121690,'frFR','Le voile a disparu de mes yeux, héros. Les ombres se retirent et le Rêve s’avance.','',26972),
(121707,'frFR','Merci, héros.','',26972),
(121724,'frFR','','Regardez, l’ennemi est parmi nous !',26972),
(121725,'frFR','','Tu ne peux pas me cacher ta vraie nature, démon !',26972),
(121726,'frFR','','Il y en a d’autres parmi nous !',26972),
(121727,'frFR','C’est tout, mortels ? Est-ce là toute la fureur que vous pouvez évoquer ?','',26972),
(121729,'frFR','Contemplez les flammes d’Azzinoth !','',26972),
(121731,'frFR','Maiev… Comment est-ce possible ?','',26972),
(121734,'frFR','','Vous nous avez découverts trop tard, Illidari ! GANGRELAMES, À L’ATTAQUE !',26972),
(121758,'frFR','','Leur fureur n’est rien à côté de la mienne, Illidan. Nous avons de vieilles querelles à régler.',26972),
(121759,'frFR','','Ma longue chasse est enfin terminée. Aujourd’hui, justice sera faite !',26972),
(122102,'frFR','Qui sera le prochain à tâter de mes lames ?','',26972),
(122570,'frFR','Esprits ! Que les marées balaient ces mortels !','',26972),
(122571,'frFR','Tous ceux qui invoquent le passeur doivent en payer le prix !','',26972),
(122572,'frFR','Vous souhaitez entrer à Helheim ? Qu’il en soit ainsi ! Ha ha ha ha !','',26972),
(122573,'frFR','Ceux qui m’invoquent en paient le prix : leur âme éternelle !','',26972),
(122693,'frFR','Tu ne peux pas me cacher ta vraie nature, démon !','Tu ne peux pas me cacher ta vraie nature, démon !',26972),
(122695,'frFR','Ha ha ha ha ha ha !','',26972),
(122845,'frFR','','Louée soit la déesse. Le miracle de la vie s’est produit cette nuit.',26972),
(122846,'frFR','','La naissance non pas d’un mais de deux garçons en bonne santé.',26972),
(122864,'frFR','Deux ?','',26972),
(122865,'frFR','','Les jumeaux Hurlorage.',26972),
(122866,'frFR','','Magnifiques. Quasiment identiques, excepté pour…',26972),
(122867,'frFR','Celui-ci ! Il a les yeux dorés !','',26972),
(122868,'frFR','','En effet. Cet enfant est promis à un avenir glorieux et prospère. Son nom… est Illidan.',26972),
(122869,'frFR','Illidan, votre colère n’a pas lieu d’être. Je ne vous ai pas insulté.','',26972),
(122870,'frFR','Vous m’avez banni, Cénarius !','',26972),
(122871,'frFR','Non. Vous pouvez rester ici, mais je ne serai plus votre professeur.','',26972),
(122872,'frFR','Alors…','',26972),
(122873,'frFR','Je vais donc devoir apprendre d’un NOVICE plutôt que d’un MAÎTRE ?','',26972),
(122874,'frFR','Vous devez apprendre le respect.','',26972),
(122875,'frFR','S’engager dans cette voie requiert des sacrifices, Illidan… Chose qu’il vous faut encore comprendre.','',26972),
(122876,'frFR','Mon frère…','',26972),
(122877,'frFR','Contemplez la puissance de la Légion.','',26972),
(122878,'frFR','<Hurle de douleur>','',26972),
(122879,'frFR','Ce monde aura beau se battre de toutes ses forces, il tombera.','',26972),
(122880,'frFR','Nos yeux… nous trompent.','',26972),
(122881,'frFR','Au-delà de cette armée, il y en a une autre, puis une autre, puis une autre…','',26972),
(122882,'frFR','Même si nous les battons ici, cela ne signifiera rien.','',26972),
(122883,'frFR','Nous sommes condamnés… ','',26972),
(122884,'frFR','Et je vais le trouver.','',26972),
(122935,'frFR','Si vous souhaitez continuer à étudier la nature, vous pouvez le faire avec votre frère.','',26972),
(122943,'frFR','Malfurion deviendra le premier druide car c’est un étudiant assidu. Ce que vous n’êtes PAS.','',26972),
(123097,'frFR','L’armée qui marche sur Azeroth n’est qu’un aperçu de la véritable puissance de la Légion.','',26972),
(123098,'frFR','À moins que nous trouvions un autre moyen de les combattre.','',26972),
(123481,'frFR','','Voici donc la troupe disparate qui porte les espoirs de votre rébellion.',26972),
(123482,'frFR','','Les Kaldorei ? Vous souillez votre glorieux passé en vous terrant parmi les arbres. Derrière vos airs de dévotion, vous n’êtes plus que des sauvages, de vulgaires Trolls des forêts.',26972),
(123483,'frFR','','Les Quel’dorei ? Des paysans qui se piquent de noblesse mais mêlent leur sang à celui des races inférieures. Vous n’êtes pas dignes du nom de Haut-Elfes.',26972),
(123484,'frFR','','Les Sin’dorei ? De tous les Elfes, vous devriez comprendre que je fais tout pour préserver mon peuple. Mais non, vous prenez le parti de la racaille et des monstres.',26972),
(123485,'frFR','','Tous, vous souillez votre si pure lignée. Vous avez oublié le pouvoir ancien qui nous revient de droit.',26972),
(123486,'frFR','','Mais Suramar se souvient ! Nous sommes les Sacrenuit, les derniers véritables Elfes. Vous autres n’êtes que de pâles copies de notre grandeur.',26972),
(123487,'frFR','','Que l’échec de cette sédition serve d’exemple à tous ceux qui voudraient défier les Shal’dorei !',26972),
(123697,'frFR','Vos actions sont illogiques. Tous les résultats possibles de cette confrontation ont été calculés.','',26972),
(123912,'frFR','Défais-toi de ta faiblesse, mon garçon ! Contiens ta magie !','',26972),
(123913,'frFR','Trop… de… puissance…','',26972),
(123914,'frFR','Père ! Non !','',26972),
(123986,'frFR','Une année de plus passée dans la torpeur. Je me demande si Medivh se réveillera un jour.','',26972),
(123987,'frFR','Est-ce que notre vieil ami rêve ? Est-il le prisonnier de cauchemars sans fin ?','',26972),
(124000,'frFR','Désormais, tu es prêt à superviser la protection de la tour en mon absence.','',26972),
(124001,'frFR','Protocoles de défense activés.','',26972),
(124002,'frFR','Hmmm, il faut juste que je pense à te désactiver de temps en temps. Un usage prolongé peut te faire agir de manière… erratique.','',26972),
(124016,'frFR','Il n’y avait rien à faire, vous savez. Nous avons essayé de l’éviter, mais cela s’inscrivait dans un plus grand dessein.','',26972),
(124017,'frFR','Je sais. Cela faisait partie d’un cycle supérieur. Un cycle qui peut enfin être brisé.','',26972),
(124032,'frFR','','Comme vous pouvez le voir, l’influence de la Légion va bien au-delà du rivage Brisé.',26972),
(124076,'frFR','','Leurs agents rôdent sur Azeroth, menaçant de faire échouer nos actions sur le site du tombeau. Ils comptent parmi les plus puissants champions de la Légion.',26972),
(124077,'frFR','Si ces démons mettent leur plan à exécution, tous nos efforts et tous nos sacrifices auront été vains.','',26972),
(124078,'frFR','Nous avons besoin de votre aide pour les retrouver. Vous êtes sans doute la seule personne à pouvoir les arrêter.','',26972),
(124297,'frFR','Que notre pouvoir se manifeste : Kirin’var torel, ahm shalar, azakim !','',26972),
(124298,'frFR','','Tous ensemble ! Nous devons unir nos forces !',26972),
(124471,'frFR','Au cours de cette guerre, vos services ont déjà été énormément sollicités. Mais je crains qu’on ne vous en demande encore davantage.','',26972),
(124588,'frFR','Notre ami se trouve juste ici.','',26972),
(124589,'frFR','Cela me fend le cœur de le voir dans cet état.','',26972),
(124824,'frFR','','La justice s’abat des cieux !',26972),
(124825,'frFR','','Courage, vous ferez mieux la prochaine fois !',26972),
(124826,'frFR','','Vous avez eu chaud aux plumes !',26972),
(124827,'frFR','','À l’attaque !',26972),
(124828,'frFR','','J’en connais qui vont y laisser des plumes !',26972),
(124829,'frFR','','On ne fait pas d’omelette sans casser des œufs.',26972),
(126172,'frFR','$gMaudit mortel:Maudite mortelle; ! Qu’avez-vous fait à mon bateau ?','',26972),
(126173,'frFR','Peu importe ! Vous allez me le payer… JE VAIS DÉVORER VOTRE ÂME !','',26972),
(126187,'frFR','Votre attention, s’il vous plaît. Ce navire ne va pas tarder à s’autodétruire. Veuillez évacuer les lieux dans les plus brefs délais.','',26972),
(126189,'frFR','Mon ordinateur ! Comment… Comment avez-vous deviné mon mot de passe ? J’avais mis plein de symboles et de majuscules !','',26972),
(126286,'frFR','Ça suffit ! Je n’ai pas de temps à perdre.','',26972),
(126857,'frFR','Pitoyables mortels ! Pensiez-vous vraiment pouvoir vaincre la Légion ardente aussi facilement ?','',26972),
(126866,'frFR','Tremblez devant la puissance de la corruption !','',26972),
(126867,'frFR','Prenez garde. Je sens une présence émerger d’un portail… elle semble extrêmement puissante !','',26972),
(126926,'frFR','Je… Je survivrai, mais je ne suis plus en état de me battre. Partez, vite ! Vous devez l’arrêter !','',26972),
(126950,'frFR','Commençons.','Commençons.',26972),
(126951,'frFR','Pitoyable.','Pitoyable.',26972),
(126952,'frFR','Vous semblez fin $gprêt:prête;.','Vous semblez fin $gprêt:prête;.',26972),
(126953,'frFR','Encore !','Encore !',26972),
(126954,'frFR','Mettez-y du vôtre.','Mettez-y du vôtre.',26972),
(126955,'frFR','N’abandonnez pas.','N’abandonnez pas.',26972),
(126956,'frFR','Excellente stratégie.','Excellente stratégie.',26972),
(126957,'frFR','Vous faites de nets progrès.','Vous faites de nets progrès.',26972),
(126958,'frFR','Bien, mais saurez-vous le refaire ?','Bien, mais saurez-vous le refaire ?',26972),
(127057,'frFR','','Prenez garde à vous, héros !',26972),
(127161,'frFR','','Odyn a commis une grave erreur en vous choisissant pour $gchampion:championne;.',26972),
(127162,'frFR','','Je me délecterai de son humiliation à vous voir échouer.',26972),
(127163,'frFR','','Vous n’avez rien à faire ici. Cette terre nous appartient et nous seuls sommes dignes de participer à ce tournoi !',26972),
(127164,'frFR','','Je me demande si on se souviendra de vous après votre défaite…',26972),
(127165,'frFR','Votre taille en dit long sur votre force… avorton.','',26972),
(127166,'frFR','On aurait pu s’échauffer ensemble, mais ces poids sont aussi gros que vous. Revenez quand vous aurez pris du muscle.','',26972),
(127167,'frFR','Il est encore temps de déclarer forfait, vous savez. La plupart de mes adversaires renoncent au premier regard.','',26972),
(127168,'frFR','J’ai sous-estimé votre force, brouf. Je pensais que la taille avait de l’importance, mais il faut croire que je me trompais.','',26972),
(127169,'frFR','Quand j’ai consulté le chaman de ma tribu, il m’a prédit une grande victoire. Vous devriez peut-être tirer votre révérence, $gfrère d’armes:sœur d’armes;.','',26972),
(127170,'frFR','Vous affichez une grande détermination, mais ce n’est rien à côté de ma volonté de fer.','',26972),
(127171,'frFR','J’ai hâte de vous affronter, $gguerrier:guerrière;. Espérons que vous survivrez jusque-là.','',26972),
(127172,'frFR','Je comprends à présent la mise en garde du chaman. J’ai appris l’humilité, et j’en ressors plus fort que jamais.','',26972),
(127173,'frFR','Merci, $gguerrier:guerrière;.','',26972),
(127228,'frFR','Bienvenue, guerriers, à l’épreuve de la rage !','',26972),
(127234,'frFR','Nos premiers combattants sont le puissant seigneur de bataille $p et le tristement célèbre drogbar Damrouf le Kostau !','',26972),
(127239,'frFR','Je vais vous secouer comme une poupée de chiffon, $R !','',26972),
(127262,'frFR','Le prochain adversaire du seigneur de bataille $p est Omanawkwa Sabot-d’Acier de la tribu de Haut-Roc.','',26972),
(127263,'frFR','Voyons si le talent |2 $p lui permettra de briser le redouté bouclier de Sabot-d’Acier !','',26972),
(127264,'frFR','Mon bouclier a repoussé des armées entières. Je doute fortement qu’$gun:une:r; simple $R comme vous puisse en venir à bout.','',26972),
(127267,'frFR','Je vais me faire un plaisir de vous écraser.','',26972),
(127268,'frFR','Il n’y a pas de honte à tomber sous mes coups. Ma défense est impénétrable.','',26972),
(127269,'frFR','Odyn m’a fait un grand honneur en m’accueillant ici. Il ne regrettera pas de m’avoir fait confiance.','',26972),
(127298,'frFR','Le prochain adversaire du seigneur de bataille $p est Asrea Lamelune, des Sacrenuit de Suramar.','',26972),
(127299,'frFR','De nombreux guerriers ont goûté à la défaite face à sa lame en ces lieux. Le seigneur de bataille parviendra-t-il à la vaincre ?','',26972),
(127300,'frFR','','Cela fait bien longtemps que ma lame n’a pas bu de sang. Je me demande si le vôtre sera à son goût…',26972),
(127312,'frFR','Assez ! Arrêtez, je… j’ai eu mon compte. Votre supériorité ne fait aucun doute, brouf.','',26972),
(127314,'frFR','Je capitule, seigneur de bataille. Votre supériorité ne laisse aucune place au doute.','',26972),
(127315,'frFR','Mort venir vite.','',26972),
(127328,'frFR','Un excellent premier tour ! On dirait que Damrouf a sous-estimé la force du seigneur de bataille $p.','',26972),
(127329,'frFR','La tant vantée défense de Sabot-d’Acier n’a pas résisté face à la puissance de $p ! Mais qu’en sera-t-il face au prochain adversaire ?','',26972),
(127330,'frFR','Un combat légendaire ! Asrea a dominé l’arène si longtemps que de nombreux spectateurs la considéraient imbattable. Et il semblerait que son orgueil démesuré ait entraîné sa chute !','',26972),
(127331,'frFR','$p, quand vous voudrez affronter votre dernier adversaire, placez-vous sur la rune.','',26972),
(127332,'frFR','Le seigneur de bataille a vaincu tous les adversaires ! L’épreuve est réussie !','',26972),
(127333,'frFR','Célébrons cette éclatante victoire ! Gloire au seigneur de bataille !','',26972),
(127334,'frFR','La dernière adversaire du seigneur de bataille $p est la meilleure élève d’Eyir… l’aspirante Thyri !','',26972),
(127335,'frFR','Les prouesses martiales du seigneur de bataille $p seront-elles suffisantes face à la favorite d’Eyir ?','',26972),
(127336,'frFR','','En vous terrassant, je ferai un pas de plus sur la voie de l’ascension.',26972),
(127337,'frFR','','Je… Je n’arrive pas à croire que j’ai perdu. Peut-être ne suis-je pas digne de l’ascension…',26972),
(127832,'frFR','Votre persévérance est assez cocasse, quand on sait que la partie est perdue d’avance.','',26972),
(127833,'frFR','Votre style de combat ne m’impressionne pas plus qu’il ne m’intéresse. Vous n’allez pas tarder à succomber à ma force.','',26972),
(127834,'frFR','Vous êtes si minuscule ! C’est comme jouer à cache-cache avec un lapin !','',26972),
(128003,'frFR','','Nerus ? Expliquez-vous, mon oncle !',26972),
(128080,'frFR','Ils ne me pardonneront peut-être jamais, mais au moins ils sont en sécurité. Pour le moment, ma famille est saine et sauve.','',26972),
(128337,'frFR','C’est à nouveau la nuit de la chasse, mes amis.','',26972),
(128338,'frFR','Ce soir, les esprits des bêtes de légende réapparaissent sur ces terres.','',26972),
(128339,'frFR','L’un de nous devait être choisi pour s’enfoncer dans les ténèbres.','',26972),
(128340,'frFR','Afin de chasser ces nobles esprits et leur accorder le repos qui leur est dû.','',26972),
(128341,'frFR','Levez vos verres en l’honneur de notre illustre maître chasseur !','',26972),
(128342,'frFR','Que le festin commence !','',26972),
(128354,'frFR','Contemplez la mère de la tanière Fereki, grande prédatrice de la terre, et le puissant Vetholnir, seigneur des cieux.','',26972),
(128393,'frFR','','S’il vous plaît ! Le sanctuaire d’Aviana subit cette fois une attaque à grande échelle ! La gardienne a besoin de nous !',26972),
(128394,'frFR','','Au diable le front. Je vais à l’arrière pour nous débarrasser de leurs lanceurs de sorts et de leur artillerie. Vous pouvez venir avec moi si vous voulez !',26972),
(128395,'frFR','','Vous avez entendu ? Des cris en provenance du sanctuaire ! Nous devons y retourner immédiatement !',26972),
(128396,'frFR','','Crève, pourriture démoniaque !',26972),
(128397,'frFR','Tous périront face à la puissance de la Légion !','',26972),
(128398,'frFR','','Sale… Non ! L’idole !',26972),
(128399,'frFR','','Noooon !',26972),
(128400,'frFR','','Le sanctuaire est perdu. Druides, envolez-vous ! Repli !',26972),
(128401,'frFR','','Qu’est-ce… La forme de vol ne fonctionne plus ?! Sans l’idole, nous avons perdu nos ailes ! Téléportez-vous tous et regroupez-vous à la Sylverêve !',26972),
(128466,'frFR','Quelle chasse ! Voilà le véritable esprit de la nature. Festoyons jusqu’au bout de la nuit et reléguons nos soucis au petit matin !','',26972),
(128617,'frFR','Vous devez vous rendre immédiatement sur le champ de bataille. Débarrassez-nous des démons qui attaquent nos troupes !','',26972),
(128620,'frFR','La Légion fait donner sa puissance et nous parvenons à peine à soutenir le siège.','',26972),
(128683,'frFR','Que pouvons-nous faire pour vous ?','Que pouvons-nous faire pour vous ?',26972),
(128943,'frFR','Le heaume de domination me montre bien des choses.','',26972),
(129671,'frFR','Montrez-vous !','',26972),
(129672,'frFR','Velen. Vous revenez enfin sur les terres que vous avez abandonnées.','',26972),
(129673,'frFR','Vous avez abandonné votre peuple, prophète. Votre monde. Une telle trahison devrait être punie par la mort.','',26972),
(129678,'frFR','Cette voix… Hatuun ? Comment avez-vous survécu aussi longtemps dans cet enfer ?','',26972),
(129679,'frFR','Nous avons changé, tout comme Argus. Nous avons résisté. Quel autre choix avions-nous ?','',26972),
(129681,'frFR','Assez !','',26972),
(129683,'frFR','Arrêtez ! Le prophète et la personne qui l’accompagne ne sont pas nos ennemis.','',26972),
(129685,'frFR','Grand exarque Turalyon… Nous nous rencontrons enfin.','',26972),
(129691,'frFR','Je ne souhaite pas vous combattre, Hatuun. Mais je ne laisserai pas votre amertume entraver notre guerre contre la Légion.','',26972),
(129692,'frFR','Pour avoir ne serait-ce qu’une chance de vaincre la Légion, nous devons faire front ensemble.','',26972),
(129929,'frFR','Pendant des millénaires, l’armée de la Lumière a affronté la Légion ardente, à grand renfort de batailles, d’escarmouches et de sabotages.','',26972),
(129930,'frFR','Nous étions dévoués à notre cause. Nous allions mettre fin à la croisade de la Légion… ou mourir.','',26972),
(129931,'frFR','En lançant notre assaut final sur Argus, nous savions que nous n’y survivrions peut-être pas. Et une fois le Xénédar touché, tout espoir sembla perdu.','',26972),
(130002,'frFR','Votre peuple… vos mondes… capitulent toujours.','',26972),
(130117,'frFR','Oui. Grâce à l’aide de notre camarade. Mais Alleria… j’ai quelque chose à te dire.','',26972),
(130118,'frFR','N’abandonnez… pas !','',26972),
(130133,'frFR','Quand vous voudrez partir, seigneur de bataille, ce portail vous reconduira au Séjour céleste. ','',26972),
(130543,'frFR','Quand vous voudrez. Nous avons beaucoup à nous dire.','',26972),
(130546,'frFR','Mais la Lumière ne nous a jamais abandonnés. Elle vous a conduits ici et nous a donné une nouvelle chance de victoire. Maintenant… c’est à nous de jouer.','',26972),
(131498,'frFR','Il existe un moyen. Nous allons utiliser toute la puissance à notre disposition pour vous aider.','',26972),
(131890,'frFR','Arator… Pas un jour ne s’est écoulé sans que ta mère et moi ne…','',26972),
(131891,'frFR','','Tous nos choix, nous les avons faits pour assurer ta sécurité. Cela nous a brisé le cœur d’être séparés de toi.',26972),
(131958,'frFR','','Andorhal, quelques mois après le Cataclysme. Nous sommes au beau milieu d’un combat entre la Horde et l’Alliance.',26972),
(131959,'frFR','Le voilà ! Vous avez vos ordres. Tuez le dragon !','',26972),
(131960,'frFR','','Vous voyez, c’est l’un des inconvénients d’être gnome. Parfois, les soldats de la Horde ont le besoin irrépressible de vous donner des coups de pied.',26972),
(131961,'frFR','Soldats de l’Alliance ! Tenez bon ! Elle ne pourra pas se cacher indéfiniment.','',26972),
(131962,'frFR','','L’ALLIANCE en a aussi après moi ? Mais qu’est-ce qui se passe ?',26972),
(131981,'frFR','','Le Puits d’éternité, juste avant la guerre des Anciens. Environ dix mille ans avant votre époque, $n. Enfin, plus ou moins.',26972),
(131982,'frFR','','Oh non ! Me voilà !',26972),
(131983,'frFR','','Ces blessures gangrenées sont profondes. Nous devons me ramener au Repos du ver.',26972),
(131984,'frFR','','Il devrait y avoir un portail temporel de l’autre côté du Puits. Je connais le chemin. Suivez-moi !',26972),
(132074,'frFR','Les Man’ari tourmentent mon peuple avec leurs rituels de magie gangrenée. Purgeons leurs occultes paroles… par le feu !','',26972),
(132075,'frFR','Le parchemin calciné que vous avez laissé sur place rappellera à la Légion que nul n’éteindra notre résistance. Merci.','',26972),
(132108,'frFR','Même torturé par la Légion, mon peuple s’est rebellé contre sa croisade maudite. Les démons ont peut-être brisé leur corps, mais pas leur volonté. Libérez leur esprit afin qu’ils reposent en paix.','',26972),
(132109,'frFR','Les esprits de ceux qui ont résisté à la Légion nous inspirent tous.','',26972),
(133050,'frFR','Notre peuple sert à alimenter de vils rituels. Détruisez ces monstrueuses créations et aidez-nous à honorer la mémoire de nos morts.','',26972),
(133051,'frFR','Ces démons capturent mon peuple pour le soumettre à d’effroyables rituels. Nous refusons de nous laisser traquer. Aidez-nous à combattre la Légion !','',26972),
(133052,'frFR','À mesure que la Légion empiète sur le terrain de chasse des pantharas, les bêtes affamées gagnent en agressivité. Réduisez leur population avant qu’elles éradiquent nos troupeaux de talbuks.','',26972),
(133215,'frFR','AL’KSH SYR IIR AWAN ? IILTH SYTHN AGEV.','AL’KSH SYR IIR AWAN ? IILTH SYTHN AGEV.',26972),
(133326,'frFR','Justice environnementale !','',26972),
(133327,'frFR','Le robot de Bert bat les brutes !','',26972),
(133328,'frFR','Il manque un point-virgule dans le code !','',26972),
(133330,'frFR','Robots de Bert battus !','',26972),
(133331,'frFR','Alimentation principale activée !','',26972),
(133332,'frFR','Vérification du code réussie !','',26972),
(133483,'frFR','Maintenant, nos êtres chers peuvent enfin trouver le repos.','',26972),
(133484,'frFR','Grâce à vous, les âmes et les vies de mes semblables sont en sécurité.','',26972),
(133485,'frFR','Ces montures nous sont essentielles pour livrer combat aux démons. Merci de les avoir protégées.','',26972),
(133762,'frFR','Mes éclaireurs ont trouvé le cadavre d’Aggonar. Nous avons une dette envers vous, grand exarque. Et envers vous également.','',26972),
(133884,'frFR','Le vaisseau de Kil’jaeden. Bien que détruit, il ne cesse de nous nuire. Débarrassons les lieux de ce fléau.','',26972),
(133885,'frFR','Dommage que la terrible empreinte de Kil’jaeden ne puisse être effacée aussi facilement que vous avez purifié ces terres.','',26972),
(133886,'frFR','La Légion appareille un dévastateur afin qu’il attaque le Xénédar. Emparez-vous-en !','',26972),
(133887,'frFR','Joli tir ! Maintenant que ce maudit vaisseau est hors service, nous pouvons concentrer nos efforts sur d’autres fronts.','',26972),
(135290,'frFR','Dirigez les canons vers le vaisseau de Kil’jaeden !','',26972),
(135882,'frFR','','Le naaru corrompu palpite d’énergie du Vide.',26972),
(135883,'frFR','','Il s’est transformé en balise…',26972),
(135885,'frFR','','… qui attire ceux qui souhaitent utiliser son pouvoir à leurs fins.',26972),
(135982,'frFR','Mais quelqu’un qui a libéré nombre des nôtres de l’emprise de la Légion se bat à vos côtés. Vous avez peut-être changé.','',26972),
(135988,'frFR','Nous souhaitons former une alliance. Nous sommes venus sur Argus à l’appel de l’armée de la Lumière pour en finir avec la Légion. Combattez à nouveau à nos côtés !','',26972),
(135989,'frFR','En finir ? Bah ! Ils sont innombrables. C’est une tâche impossible. Un suicide !','',26972),
(136040,'frFR','Qu’attendez-vous de moi, maître ?','',26972),
(136041,'frFR','Le cercle approche de son aboutissement. Les mortels ne doivent pas perturber la renaissance.','',26972),
(136042,'frFR','Ceux qui refusent de servir seront détruits. C’est la seule éventualité.','',26972),
(136043,'frFR','Deviens une fois encore l’instrument de ma fureur, Aggramar. Fais cesser cette incursion de la Lumière.','',26972),
(136044,'frFR','L’heure de la renaissance approche. Les âmes sont-elles prêtes ?','',26972),
(136045,'frFR','Nos semblables sont encore récalcitrants, maître. Mais ils se plieront bientôt à la vérité.','',26972),
(136046,'frFR','L’une d’entre eux nous manque encore, et son essence est requise pour garantir la victoire de ma croisade.','',26972),
(136047,'frFR','La Lieuse-de-Vie ne tardera pas à se montrer. Elle ne m’échappera pas, maître !','',26972),
(136048,'frFR','À l’avènement de mon nouveau Panthéon, nul pouvoir dans l’univers ne s’opposera plus à la Légion !','',26972),
(136049,'frFR','','Je me souviens de l’éveil… de la manière dont la vie jaillissait tout autour de nous.',26972),
(136050,'frFR','','Je me souviens de l’unité… jusqu’à ce qu’elle soit fracassée par la trahison.',26972),
(136051,'frFR','','Je me souviens de la fuite… pour l’empêcher d’atteindre sa proie.',26972),
(136052,'frFR','','L’heure n’est plus à la dissimulation. Venez-moi en aide… ou tout sera fini.',26972),
(136053,'frFR','Talgath se retourne contre nous !','',26972),
(136054,'frFR','Non…','',26972),
(136055,'frFR','Cela ne peut se terminer ainsi. Prenez les autres et fuyez, prophète. Nous vous obtiendrons un répit.','',26972),
(136056,'frFR','Hatuun ! Vous n’avez pas à faire cela !','',26972),
(136057,'frFR','S’il vous plaît… veillez sur ma famille.','',26972),
(136058,'frFR','K’ure ! Viens-nous en aide !','',26972),
(136059,'frFR','Je te traquerai par-delà les étoiles, traître ! Dussé-je y passer mille ans !','',26972),
(136061,'frFR','Prête-moi allégeance, dévoue les cœurs de ton peuple à ma cause.','',26972),
(136062,'frFR','Ensemble, nous serons légion et nous vaincrons le vide insatiable qui finirait par nous consumer tous.','',26972),
(136063,'frFR','Il ne demande pas grand-chose pour ce qu’il offre en retour.','',26972),
(136064,'frFR','Une telle puissance… De plus, il dit la vérité.','',26972),
(136065,'frFR','J’espérais que les autres percevraient le mal derrière les paroles de Sargeras.','',26972),
(136066,'frFR','Le cristal d’Ata’mal m’a vite montré l’horrible vérité de ce qui arriverait si nous acceptions l’offre du titan.','',26972),
(137611,'frFR','Je te métamorphoserai, je t’accorderai une connaissance au-delà de l’entendement et une puissance au-delà de toute mesure.','',26972),
(137612,'frFR','Mais leur vanité… leur soif de puissance les a aveuglés.','',26972),
(137613,'frFR','Elle ne ferait pas de nous des dirigeants avisés, mais des monstres pleins de fiel.','',26972),
(138010,'frFR','Tenez-vous prêts !','',26972),
(141110,'frFR','','Camarades, les épreuves que vous avez endurées prouvent que la Lumière resplendit dans vos cœurs.',26972),
(141111,'frFR','','Un dernier défi, le plus difficile, vous attend maintenant.',26972),
(141112,'frFR','','Il vous confrontera à l’essence même de votre existence. À ce que vous pensez être au fond de votre âme.',26972),
(141113,'frFR','','Bien des Draeneï se sont soumis à cette épreuve par le passé et en sont revenus brisés… ou pire.',26972),
(141114,'frFR','','Si vous avez le moindre doute, faites demi-tour. Votre décision sera considérée comme un acte de sagesse, et non de lâcheté.',26972),
(141115,'frFR','','Toutefois, si vous vous sentez prêts, avancez et embrassez votre destin.',26972),
(141116,'frFR','','T’laartos… nous en avons déjà discuté. Chaque initié doit être accompagné. Où es ton partenaire ?',26972),
(141117,'frFR','T’laartos n’a besoin de l’aide de personne !','',26972),
(141118,'frFR','','Le dernier initié qui a tenté de relever le défi seul n’est pas revenu en entier. Désignez quelqu’un ou retournez dans vos quartiers !',26972),
(141119,'frFR','Très bien ! T’laartos choisit… ce petit être chétif, là !','',26972),
(141120,'frFR','','Un choix peu orthodoxe, mais… techniquement dans les règles. Notre camarade n’a jamais reculé face au défi.',26972),
(141121,'frFR','','L’épreuve va commencer. Que la Lumière soit avec vous.',26972),
(141122,'frFR','T’laartos !','',26972),
(141355,'frFR','','Le Vide. Une force dont la faim est insatiable.',26972),
(141356,'frFR','','Les sages et les érudits redoutent le Vide.',26972),
(141357,'frFR','','Mais nous détenons une vérité qu’ils ne peuvent concevoir.',26972),
(141358,'frFR','','Le Vide nous a façonnés… il nous a à jamais changés. Vous garderez toutefois l’ascendant.',26972),
(141359,'frFR','','Nous sommes des soldats.',26972),
(141360,'frFR','','À travers les millénaires, la Lumière nous a montré la voie.',26972),
(141361,'frFR','','Notre ennemi a enfin été vaincu. La Légion n’est plus. Mais la guerre est loin d’être finie. De nouvelles menaces rôdent dans les ténèbres et attendent l’heure de frapper.',26972),
(141362,'frFR','','Vous faites partie des Sancteforge. Vous symbolisez l’espoir face aux ténèbres.',26972),
(141363,'frFR','','Pendant dix mille ans, Suramar a été le seul monde que nous avons connu.',26972),
(141364,'frFR','','Autour de nous, le monde a connu d’innombrables changements… puis il est tombé aux griffes de la Légion.',26972),
(141365,'frFR','','Nos meneurs nous ont trahis, ont passé un pacte avec les démons. Mais nous nous sommes insurgés contre la tyrannie… et avons chassé le mal. Suramar nous appartient à nouveau et nous ne la laisserons plus jamais succomber aux ténèbres.',26972),
(141366,'frFR','','Pour assurer l’avenir de notre peuple, nous devons regagner notre place sur Azeroth.',26972),
(141375,'frFR','','Première arcaniste Thalyssra, honorables invités, bienvenue à Lune-d’Argent.',26972),
(141376,'frFR','','C’est un plaisir d’admirer enfin votre somptueuse cité. Merci pour cette invitation, seigneur régent.',26972),
(141379,'frFR','Je vous en prie, appelez-moi Lor’themar. Mais où sont mes manières ? Laissez-moi vous présenter Alleria Coursevent, une ancienne héroïne de Lune-d’Argent.','',26972),
(141380,'frFR','','Un honneur inespéré, dame Coursevent. Silgryn a vanté votre courage lors de la campagne sur Argus.',26972),
(141381,'frFR','','Tout l’honneur est pour moi, Première arcaniste. Mais je ne souhaite pas imposer ma présence. Il serait plus sage que je revienne une autre fois.',26972),
(141382,'frFR','Ne dites pas de bêtises ! Quelle que soit la raison de votre venue, nos invités peuvent aussi l’entendre.','',26972),
(141383,'frFR','','Si vous insistez. Je viens vous faire part d’une offre du haut roi Anduin Wr…',26972),
(141384,'frFR','J’espérais que votre présence ait été motivée par votre amour de Lune-d’Argent. Au lieu de cela, vous venez sur ordre de l’enfant-roi qui dirige l’Alliance. Quelle déception.','',26972),
(141387,'frFR','','Votre langue est acérée, Lor’themar. Le respectueux forestier que j’ai connu serait-il devenu le porte-parole de son chef de guerre ?',26972),
(141388,'frFR','Vous mettez ma parole en doute, mais que suis-je censé penser de vous ? N’entendez-vous pas les murmures des seigneurs du Vide ? N’avez-vous pas cédé aux ténèbres sur Argus ?','',26972),
(141389,'frFR','','Il semblerait que notre offre ait été escomptée… et rejetée. Qu’il en soit ainsi. J’ai une demande à formuler avant de partir.',26972),
(141391,'frFR','','Cela fait maintenant mille ans que je n’ai pas posé les yeux sur le Puits de soleil. Puis-je le revoir ?',26972),
(141392,'frFR','Je le déconseille. Nous ne savons pas ce qu’elle pourrait…','',26972),
(141393,'frFR','Quoi qu’elle soit devenue, Alleria reste une enfant de Quel’Thalas. Je ne lui refuserai pas l’accès à notre site le plus sacré. Première arcaniste, si vous et votre suite souhaitez vous joindre à nous.','',26972),
(141394,'frFR','','Ce serait pour nous un immense honneur de voir le Puits de soleil, Lor’themar. Et je préfère que mes amis m’appellent Thalyssra.',26972),
(141395,'frFR','Rommath, ouvrez la voie, si vous le voulez bien.','',26972),
(141396,'frFR','Suivez-moi, je vous prie.','',26972),
(141407,'frFR','','Haut-Roc ne faillira pas !',26972),
(141408,'frFR','','Ces mots en disent beaucoup plus long que la terre et la pierre. Ils portent l’histoire de notre peuple qui, dans l’adversité et le conflit, s’est fédéré contre un ennemi commun.',26972),
(141409,'frFR','','Il nous est arrivé de nous déchirer, de nous égarer. Mais les esprits de nos ancêtres veillaient à nous rappeler que nous sommes liés par la terre, la rivière et le ciel. Nous sommes une famille. Et elle vaut la peine d’être défendue.',26972),
(141410,'frFR','','Il est temps pour vous d’aller au-delà de nos sommets sacrés.',26972),
(141908,'frFR','','Je ne pensais pas vous revoir si tôt, grand exarque. Je présume que votre audience avec le roi s’est bien passée ?',26972),
(143468,'frFR','','Salutations, dame Liadrin, $p. C’est un plaisir de vous revoir et de vous accueillir à Suramar en des circonstances plus favorables.',26972),
(143469,'frFR','','Je suis heureuse de voir votre cité enfin libre, Première arcaniste.',26972),
(143470,'frFR','','Nous avons d’ailleurs une dette envers vous. Vous avez joué un rôle décisif.',26972),
(143471,'frFR','','Ce fut pour la Horde un honneur de combattre la Légion ardente à vos côtés, madame.',26972),
(143472,'frFR','','Je dois avouer avoir émis des doutes au sujet de la Horde, convaincue que nos intérêts divergeaient.',26972),
(143473,'frFR','','Je pensais que nos frères de Kalimdor seraient des alliés naturels. Mais leur arrogance et leur méfiance m’ont rapidement détrompée.',26972),
(143474,'frFR','','Arcaniste Thalyssra, je me rappelle la conduite de votre ordre lors de la guerre des Anciens. Qui nous dit que vous ne deviendrez pas une nouvelle Élisande, ou une nouvelle Azshara ?',26972),
(143475,'frFR','','Nous ne comptons pas devenir esclaves du Puits de la nuit. Nous voulons seulement chasser la Légion de Suramar et mettre fin à la tyrannie d’Élisande.',26972),
(143476,'frFR','','Les Kaldorei combattront pour vaincre la Légion et détruire le Puits de la nuit. Ensuite… nous verrons où nous guidera la sagesse d’Élune.',26972),
(143477,'frFR','','Il semblerait que la « sagesse d’Élune » ait altéré le lien qui nous unissait autrefois. Qu’il en soit ainsi.',26972),
(143478,'frFR','','Tyrande et son peuple plein d’orgueil méprisent les Sin’dorei. Ils oublient qu’ils dormaient dans des tanières et se cachaient dans les arbres à l’époque où les miens se battaient déjà pour sauver le monde.',26972),
(143479,'frFR','','L’Alliance est trop fermée… trop hermétique. Et mon peuple refuse d’endurer davantage d’inertie.',26972),
(143480,'frFR','','C’est pourquoi je suis ravie de votre invitation à Lune-d’Argent. J’aimerais savoir s’il y a une place pour les Sacrenuit dans votre Horde.',26972),
(143481,'frFR','','Je suis persuadée que le seigneur régent sera ravi de répondre à cette question. Êtes-vous prête à partir ?',26972),
(143482,'frFR','','Ce serait un honneur, dame Liadrin. Oculeth dispose des coordonnées de votre capitale. Je m’en vais chercher Silgryn et Valtrois, puis je vous retrouverai à Lune-d’Argent.',26972),
(146461,'frFR','','Suivez la voie empruntée par Huln il y a si longtemps, et faites honneur au nom… de Haut-Roc.',26972),
(146462,'frFR','','Et en retour, nous renaissons afin de servir son pouvoir.',26972),
(146463,'frFR','','En revanche, pour ceux qui menacent notre monde… ou s’en prennent à nos alliés… vous incarnez le courroux de la Lumière.',26972),
(146475,'frFR','','Parcourir le monde avec nos nouveaux alliés et montrer à tous la noblesse et la puissance de l’héritage des Sacrenuit.',26972),
(146476,'frFR','','Ses murmures ont brisé la volonté des dragons… et même conduit les enfants des titans à la folie.',26972),
(146477,'frFR','','Le pouvoir du Vide peut être mis à profit… et servir ceux dont la volonté est inflexible.',26972),
(146482,'frFR','','Brandissez les ténèbres telle l’arme de notre salut… et défendez l’Alliance !',26972);
